NAME = 'GerAlbrecht: German Albrecht Neues Testament und Psalmen'
BOOK = 'Psalms'

CHAPTERS = {
    1: {
        1: 'Heil dem, der nicht einhergeht nach der Frevler Weise, / Der sich nicht einläßt auf den Weg der Sünder / Noch in der Spötter Kreis sich mischt,',
        2: 'Der vielmehr am Gesetze Jahwes sich ergötzt / Und Tag und Nacht darüber forschend sinnt!',
        3: 'So gleicht er einem Baum, gepflanzt an Wasserbächen, / Der seine Früchte bringt zu rechter Zeit / Und dessen Blätterschmuck nicht welkt: / Sein ganzes Tun gerät ihm wohl.',
        4: 'Ganz anders ist es mit den Frevlern! / Sie werden wie die Spreu vom Wind verweht.',
        5: 'Drum können auch die Frevler im Gericht nicht bestehn / Noch Sünder bleiben unter den Gerechten.',
        6: 'Denn Jahwe kennt der Gerechten Weg, / Der Weg der Frevler aber endet im Verderben!',
    },
    2: {
        1: 'Warum sind die Heiden so wild erregt? / Warum sinnen die Völker, was nichtig ist?',
        2: 'Der Erde Könige lehnen sich auf, / Und die Würdenträger beraten sich / Wider Jahwe und seinen Gesalbten:',
        3: '"Auf, laßt uns sprengen ihre Bande / Und von uns werfen ihre Seile!"',
        4: 'Der in den Himmeln thronet, lacht, / Adonái spottet ihrer.',
        5: 'Dann aber redet er sie an im Zorn / Und wird sie schrecken in seinem Grimm:',
        6: '"Ich habe meinen König eingesetzt / auf Zion, meinem heilgen Berg!"',
        7: '"Ich will verkünden Jahwes Spruch: / Er hat mir gesagt: \'Mein Sohn bist du, / Ich habe dich heute gezeugt!',
        8: 'Fordre von mir, so geb ich dir Völker zum Erbe / Und die Enden der Erde zum Eigentum.',
        9: 'Du sollst sie zerschmettern mit eisernem Stab, / Wie Töpfergeschirr sie zerschlagen!\'"',
        10: 'Nun denn, ihr Könige, seid verständig! / Lasset euch warnen, ihr Richter auf Erden!',
        11: 'Dienet Jahwe mit Ehrfurcht / Und jubelt ihm zu mit Zittern!',
        12: 'Küsset den Sohn, damit er nicht zürne / Und ihr umkommet auf euerm Weg! / Denn bald wird sein Zorn entbrennen. / Heil allen, die bei ihm Zuflucht suchen!',
    },
    3: {
        1: 'Ein Psalm Davids, als er vor seinem Sohne Absalom floh.',
        2: 'Jahwe, wie sind meiner Dränger so viel! / Viele erheben sich wider mich.',
        3: 'Gar manche sagen von mir: / "Er findet keine Hilfe bei Gott." Sela.',
        4: 'Du aber, Jahwe, bist mir ein Schild, / Du, mein Ruhm, du erhebst mein Haupt.',
        5: 'Zu Jahwe rufe ich laut, / Und er erhöret mich von seinem heiligen Berge. Sela.',
        6: 'Ich legte mich nieder und schlummerte ein; / Nun bin ich erwacht, weil Jahwe mich stützt.',
        7: 'Vor viel Scharen Kriegsvolk fürcht ich mich nicht, / Die sich ringsum wider mich lagern.',
        8: 'Auf, Jahwe! Hilf mir, mein Gott! / Du hast ja stets all meine Feinde ins Antlitz geschlagen, / Du hast der Frevler Zähne zerschmettert. Bei Jahwe ist Hilfe. / Dein Segen komme über dein Volk! Sela.',
    },
    4: {
        1: 'Dem Sangmeister, mit Saitenspielbegleitung. Ein Psalm Davids.',
        2: 'Wenn ich rufe, erhöre mich, Gott meines Heils! / Du hast mich ja schon aus Drangsal errettet; / So sei mir nun gnädig und hör mein Gebet!',
        3: 'Ihr Männer von Ansehn, wie lange wollt ihr meine Ehre schänden, / Indem ihr das Nichtige liebt und auf Lügen sinnt? Sela.',
        4: 'Wisset, daß Jahwe mich reich begnadet: Jahwe hört, wenn ich zu ihm rufe.',
        5: 'Wollt ihr zürnen, so sündigt doch nicht! / Prüft euer Herz im stillen und schweigt! Sela.',
        6: 'Bringt rechte Opfer und traut auf Jahwe!',
        7: 'Viele sagen: "Wer läßt uns Gutes schaun?" / O, erheb über uns das Licht deines Angesichts, Jahwe!',
        8: 'Du hast mir Freude ins Herz gegeben; / Das ist ein besserer Schatz als all ihr Korn und Most. Nun will ich in Frieden mich niederlegen zum Schlaf; / Denn du, o Jahwe, lässest mich ungestört und sicher wohnen.',
    },
    5: {
        1: 'Dem Sangmeister, auf Flöten(?). Ein Psalm Davids.',
        2: 'Höre, Jahwe, meine Worte, / Merke auf mein Seufzen!',
        3: 'Horch auf mein Hilferufen, / Mein König und mein Gott, / Denn ich will zu dir beten!',
        4: 'Am Morgen höre, Jahwe, meine Stimme! / Am Morgen richt ich (mein Gebet) zu dir / Und schaue (nach Erhörung) aus.',
        5: 'Denn nicht ein Gott, dem Böses wohlgefällt, bist du; / Der Frevler darf nicht bei dir weilen.',
        6: 'Nicht dürfen Prahler vor dein Auge treten, / Du hassest alle Übeltäter.',
        7: 'Du bringst die Lügenredner um; / Wer mit Mord und Tücke umgeht, den verabscheut Jahwe.',
        8: 'Ich aber darf ob deiner reichen Gnade in dein Haus eingehn, / Ich darf vor deinem heilgen Tempel niederknien in deiner Frucht.',
        9: 'Jahwe, leite mich in deiner Gerechtigkeit um meiner Feinde willen; / Ebne deinen Weg vor mir!',
        10: 'Denn in ihrem Munde ist keine Wahrheit, / Ihr Herz ist voller Frevel. / Ein offenes Grab ist ihre Kehle, / Mit ihrer Zunge schmeicheln sie.',
        11: 'Laß sie büßen, Elohim, / Daß sie in ihren Plänen scheitern! / Ob ihrer Sünden Menge stoße sie hinweg, / Denn sie sind widerspenstig gegen dich!',
        12: 'Doch freuen laß sich alle, die bei dir Zuflucht suchen; / Auf ewig laß sie jauchzen, da du sie beschirmst! / Frohlocken werden in dir alle, / Die deinen Namen lieben. Denn du, o Jahwe, segnest den Gerechten. / Gleich einem Schild umgibst du ihn mit Huld.',
    },
    6: {
        1: 'Dem Sangmeister mit Saitenspielbegleitung, in der achten Tonart(?). / Ein Psalm Davids.',
        2: 'Jahwe, nicht in deinem Zorne strafe mich, / Und nicht in deinem Grimme züchtige mich!',
        3: 'Sei mir, o Jahwe, gnädig; denn ich bin verschmachtet! / Heile mich, o Jahwe, denn meine Glieder beben!',
        4: 'Ja, meine Seele ist gar sehr erschrocken; / Du aber, Jahwe, — wie so lange!?',
        5: 'Wende dich doch wieder zu mir, Jahwe, rette meine Seele, / Hilf mir um deiner Gnade willen!',
        6: 'Denn im Totenreich gedenket man dein nicht, / Wer könnte in der Unterwelt dich preisen?',
        7: 'Erschöpft bin ich von meinem Seufzen, / Ich schwemme jede Nacht mein Bett (mit Tränen), / Mit meinen Zähren netze ich mein Lager.',
        8: 'Verdunkelt ist vor Gram mein Auge, / Gealtert wegen aller meiner Dränger.',
        9: 'Hinweg von mir, ihr Übeltäter alle! / Denn Jahwe hat gehört mein lautes Weinen.',
        10: 'Hören wird Jahwe auf mein Flehn, / Jahwe wird mein Gebet annehmen. Zuschanden werden und gar sehr erschrecken müssen alle meine Feinde, / Sie weichen vor Scham gar plötzlich.',
    },
    7: {
        1: 'Ein Gedicht(?) Davids, das er Jahwe sang wegen der Reden des Benjaminiten Kusch.',
        2: 'Jahwe, mein Gott, bei dir such ich Schutz, / Hilf mir von all meinen Drängern und rette mich,',
        3: 'Daß sie mich nicht wie Löwen zerfleischen, / Mich nicht zermalmen, weil niemand mich rettet!',
        4: 'Jahwe, mein Gott, hab ich solches verübt, / Findet sich Unrecht an meinen Händen;',
        5: 'Hab ich meinem Freunde Böses getan, / Und meinen Gegner grundlos geplündert:',
        6: 'So verfolge der Feind mich und hole mich ein, / Er trete mein Leben zu Boden / Und leg in den Staub meine Ehre! Sela.',
        7: 'Jahwe steh auf in deinem Zorn, / Steh auf wider meiner Dränger Grimm, / Wach auf, mir zur Hilfe, du hast ja Gericht verordnet!',
        8: 'Die Schar der Völker laß dich umringen, / Und über ihr kehre zur Höhe zurück!',
        9: 'Jahwe richtet die Völker: / Schaffe mir Recht, o Jahwe, / Nach meiner Gerechtigkeit und Unschuld!',
        10: 'Laß doch enden der Frevler Bosheit / Und stärke die Frommen! / Du prüfest ja Herzen und Nieren, / Gerechter Gott!',
        11: 'Meinen Schild hält Gott, / Der den redlichen Herzen hilft.',
        12: 'Ein gerechter Richter ist Elohim / Und ein Gott, der täglich zürnt.',
        13: 'Bekehrt sich der Sünder nicht, so schärft er sein Schwert, / Hält seinen Bogen gespannt und zielt;',
        14: 'Er richtet gegen ihn Todesgeschosse, / Seine Pfeile macht er zu Feuerbränden.',
        15: 'Sieh, Frevel empfängt der Böse: / Dann geht er schwanger mit Unheil und wird Trug gebären.',
        16: 'Er hat eine Grube gegraben und ausgehöhlt / Und sinkt in den Abgrund, den er gemacht.',
        17: 'Das Unheil, das er geplant, fällt auf sein Haupt zurück, / Und auf seinen Scheitel stürzt sein Frevel. Danken will ich Jahwe für sein gerechtes Walten / Und lobsingen dem Namen Jahwes, des Höchsten.',
    },
    8: {
        1: 'Dem Sangmeister, auf der Gittit. Ein Psalm Davids.',
        2: 'Jahwe, unser Herrscher, / Wie herrlich ist dein Name auf der ganzen Erde! / Deine Hoheit zeigst du droben im Himmel.',
        3: 'Aus Kinder- und Säuglingsmund hast du ein Bollwerk gegründet / Deinen Widersachern zum Trutz, / Um Feind und Empörer zum Schweigen zu bringen.',
        4: 'So oft ich die Himmel betrachte, deiner Hände Werk, / Den Mond und die Sterne, die du bereitet:',
        5: 'Was ist da der Mensch, daß du sein gedenkst, / Und der Menschensohn, daß du für ihn so liebreich sorgst?',
        6: 'Du hast ihn nur wenig geringer gemacht als die himmlischen Wesen, / Mit Ehre und Würde hast du ihn gekrönt.',
        7: 'Du hast ihn zum Herrscher gemacht über deiner Hände Werke, / Alles hast du ihm unter die Füße gelegt:',
        8: 'Schafe und Rinder insgesamt, / Dazu auch die Tiere der Felder,',
        9: 'Die Vögel des Himmels und die Fische im Meer. / Auch durchzieht er die Bahnen der Meere. Jahwe, unser Herrscher, / Wie herrlich ist dein Name auf der ganzen Erde!',
    },
    9: {
        1: 'Dem Sangmeister, nach (der Melodie des Liedes:) "Stirb für den Sohn" (?). Ein Psalm Davids.',
        2: 'Anbetend preisen will ich Jahwe von ganzem Herzen, / All deine Wunder will ich erzählen;',
        3: 'Auch will ich mich freuen und jauchzen in dir; / Aufspielen deinem Namen, du Höchster!',
        4: 'Bedenk ich doch: meine Feinde sind rückwärts gewichen, / Sie sind gestrauchelt und umgekommen vor dir.',
        5: 'Denn du hast mein Recht geführt und meine Sache, / Du sitzest auf dem Thron als ein gerechter Richter.',
        6: 'Grimmig schaltest du Völker, verderbtest den Frevler, / Ihren Namen hast du vertilgt auf immer und ewig.',
        7: 'Ha die Feinde! Dahin sind sie, vernichtet für immer; / Ihre Städte hast du zerstört, vertilgt ihr Gedächtnis:',
        8: 'Während Jahwe auf ewig thront; / Er hat zum Gericht seinen Stuhl gestellt.',
        9: 'Er richtet den Erdkreis recht, / Er spricht den Völkern ein gerades Urteil.',
        10: 'Werden wird Jahwe ein Hort dem Bedrückten, / Ein Hort in Zeiten der Not.',
        11: 'Drum trauen dir, die deinen Namen kennen; / Denn du verlässest nicht, die dich, o Jahwe, suchen.',
        12: 'Singt Jahwe, der auf Zion wohnt, / Verkündet inmitten der Völker sein Tun!',
        13: 'Denn als Rächer des Bluts hat er ihrer gedacht, / Nicht vergessen des Schreiens der Dulder.',
        14: 'Gnädig sei mir, o Jahwe! Sieh an das Leid, / Das mir meine Hasser bereiten, — / Du, der mich erhebt aus des Todes Toren!',
        15: 'Dann will ich erzählen all deinen Ruhm; / In den Toren der Tochter Zion / Will ich ob deiner Hilfe jubeln.',
        16: 'Tief sind versunken die Völker / In der Grube, die sie gegraben; / In dem Netz, das sie heimlich gelegt, / Hat sich ihr Fuß gefangen.',
        17: 'Kund geworden ist Jahwe: er hat Gericht geübt; / In seiner Hände Werk / Hat sich der Böse verstrickt. (Higgajôn, Sela.)',
        18: 'Ja, müssen die Frevler zur Hölle fahren, / Alle Heiden, die Gottes vergessen.',
        19: "Kann denn des Armen auf immer vergessen werden? / Ist's mit der Elenden Hoffnung aus für ewig?",
        20: 'Komm, Jahwe, daß der Mensch nicht trotze, / Laß die Heiden vor dir gerichtet werden! Schick ihnen, Jahwe, Schreckenswarnung! / Dann erkennen die Heiden, daß sie nur sterbliche Menschen sind. Sela.',
    },
    10: {
        1: 'Lang schon, Jahwe, stehst du fern! / Warum verbirgst du dich zur Zeit der Not?',
        2: 'Beim Übermut der Frevler muß sich der Dulder ängsten: / Möchten sie gefangen werden in den Ränken, die sie ausgedacht!',
        3: 'Denn der Frevler rühmt sich des, was sein Herz begehrt, / Der Ungerechte schmäht und höhnet Jahwe.',
        4: 'Der Böse denkt in seinem Stolz: "Er strafet nicht; / Es ist kein Gott!" Dahin geht all sein Denken.',
        5: 'Was er sich vornimmt, das gelingt ihm stets; / Es bleiben deine Strafgerichte himmelweit entfernt von ihm. / All seine Widersacher schnaubt er zornig an.',
        6: 'Er denkt: "Ich wanke nimmer, / Für alle Zukunft komm ich nicht in Not."',
        7: 'Sein Mund ist voll Verwünschung, Lug und Trug; / An seiner Zunge kleben Unheil und Verderben.',
        8: 'Er liegt im Hinterhalt in den Gehöften, / Er mordet insgeheim Unschuldige; / Es spähen seine Augen nach den Schwachen.',
        9: 'Er lauert im Versteck gleich einem Löwen, der im Dickicht liegt, / Er lauert, um den Armen zu erhaschen, / Er hascht den Armen, schleift ihn weg in seinem Netz.',
        10: 'Er duckt sich, kauert nieder, / In seine Klauen fallen die Wehrlosen.',
        11: 'Er denkt in seinem Herzen: "Gott vergißt es, / Verbirgt sein Antlitz, sieht es nimmer."',
        12: 'Komm, stehe auf, o Jahwe El!, erhebe deine Hand! / Vergiß nicht der Gebeugten!',
        13: 'Warum darf denn der Frevler lästern Elohim, / In seinem Herzen denken: "Nun, du strafst doch nicht?"',
        14: 'Richtend aber siehst du es, du schauest Müh und Herzeleid, / Um sie (den Frevlern) zu vergelten! / Auf dich verlässet sich der Schwache, / Und dem Verwaisten zeigst du dich als Helfer.',
        15: 'Schmettre doch des Frevlers Arm zu Boden! / Des Bösen Unrecht strafe, daß er vor dir schwinde!',
        16: 'Jahwe ist König auf immer und ewig, / Die Heiden verschwinden aus seinem Land.',
        17: 'Treulich hörst du, o Jahwe, den Wunsch der Dulder, / Du stärkest ihr Herz, du neigest ihnen dein Ohr.',
        18: 'Schaffst du den Waisen, den Bedrückten Recht, / So wird der Mensch, der Erdenwurm, nicht länger trotzen.',
    },
    11: {
        1: 'Dem Sangmeister. Von David. / Auf Jahwe trau ich! / wie könnt ihr mir da raten: / Flieh wie ein Vogel ins Gebirge!',
        2: 'Denn sieh, die Frevler spannen den Bogen, / sie haben den Pfeil auf die Sehne gelegt, / Im Dunkeln zu schießen auf solche, die redlichen Herzens sind.',
        3: 'Wenn die Grundpfeiler niederstürzen, / Was vermöchte da der Gerechte?"',
        4: 'Jahwe wohnt in seinem heiligen Tempel, / Jahwes Thron ist im Himmel: / Seine Augen schauen, / Seine Blicke prüfen die Menschenkinder.',
        5: 'Jahwe prüft den Gerechten; / Die Frevler und alle, die Unrecht lieben, die hasset er.',
        6: 'Er läßt auf die Frevler Feuerkohlen und Schwefel regnen, / Versengender Glutwind ist ihr Teil.',
        7: 'Denn Jahwe ist gerecht, er liebt Gerechtigkeit. / Die Frommen schauen sein Angesicht!',
    },
    12: {
        1: 'Dem Sangmeister, in der achten Tonart (?). Ein Psalm Davids.',
        2: 'Hilf, Jahwe, denn die Frommen sind dahin! / Die Treue schwindet bei den Menschenkindern.',
        3: 'Sie reden miteinander Lüge, / Doppelzüngig reden sie mit schmeichlerischen Lippen.',
        4: 'Es rotte Jahwe alle Schmeichellippen aus / Und jede prahlerische Zunge.',
        5: 'Sie sprechen: "Wir sind stark durch unsre Zunge; / Wenn unsre Lippen mit uns sind, wer ist dann unser Herr?"',
        6: '"Weil die Dulder leiden müssen, weil die Armen seufzen, / Will ich mich nun erheben", so spricht Jahwe, / "Will Hilfe senden dem, der danach schmachtet."',
        7: 'Jahwes Worte sind lautre Worte: / Silber, das in der Werkstatt gereinigt zur Erde fließt, / Geläutert siebenfach.',
        8: 'Du, Jahwe, wirst sie schirmen, / Wirst sie vor diesen Menschen für immer bewahren. Es schreiten ringsum Frevler stolz einher, / Weil niedrige Gemeinheit hochkommt bei den Menschenkindern.',
    },
    13: {
        1: 'Dem Sangmeister. Ein Psalm Davids.',
        2: 'Wie lange, Jahwe, willst du mein so ganz vergessen, / Wie lange noch dein Angesicht vor mir verbergen?',
        3: 'Wie lange soll ich mich mit Sorgen quälen / Und Kummer in mir nähren Tag für Tag? / Wie lange soll mein Feind sich noch erheben über mich?',
        4: 'Schau her, erhöre mich, Jahwe, mein Gott! / Mach meine Augen hell, damit ich nicht in Todesschlaf versinke!',
        5: 'Sonst könnte ja mein Feind sich rühmen: / "Ich hab ihn bezwungen", / Und meine Dränger könnten jubeln, daß ich wanke.',
        6: 'Doch ich vertrau auf deine Gnade; / Jauchzen soll mein Herz ob deines Heils. / Preisen will ich Jahwe: er hat mir wohlgetan!',
    },
    14: {
        1: 'Dem Sangmeister. Von David. / Die Toren denken bei sich: "Es ist kein Gott." / Verderbt, abscheulich handeln sie; / Da ist keiner, der Gutes tut.',
        2: 'Jahwe schaut vom Himmel herab auf die Menschenkinder, / Daß er sehe, ob jemand Einsicht habe / Und frage nach Gott.',
        3: 'Aber sie alle sind abgefallen, alle entartet; / Da ist keiner, der Gutes tut, / Auch nicht ein einziger.',
        4: '"Sind denn so unvernünftig alle Übeltäter, / Die mein Volk verzehren, wie man Brot verzehrt, / Die nicht zu Jahwe beten?"',
        5: 'Dann beben sie schaudernd, / Denn Gott weilt bei dem gerechten Volk.',
        6: 'Mögt ihr auch vereiteln der Dulder Wunsch — / Jahwe bleibt doch ihre Zuflucht.',
        7: 'Ach, käme aus Zion für Israel Heil! / Wendet Jahwe das Los seines Volks, / So wird Jakob sich freun und Israel jauchzen.',
    },
    15: {
        1: 'Ein Psalm Davids. / Wer darf in deinem Zelte weilen, Jahwe, / Wer darf auf deinem heilgen Berge wohnen?',
        2: 'Er, der unsträflich wandelt und das Rechte tut, / Der Wahres denkt in seinem Herzen.',
        3: 'Er verleumdet nicht mit seiner Zunge, / Fügt einem andern nichts Böses zu / Und bringt nicht Schimpf auf seinen Nächsten.',
        4: 'Gering ist er in seinen eignen Augen und verachtet; / Doch ehrt er die, die Jahwe fürchten. / Wenn er auch schwört zu seinem eignen Schaden — / Er ändert es doch nicht.',
        5: 'Sein Geld leiht er nicht aus auf Zins, / Er läßt sich nicht bestechen zum Schaden von Unschuldigen. / Wer so handelt, der wird in Ewigkeit nicht wanken.',
    },
    16: {
        1: 'Ein Gedicht (?) von David. / Behüte mich, Gott, denn ich fliehe zu dir!',
        2: 'Ich spreche zu Jahwe: "Mein Herr bist du, / Du bist mein höchstes Gut."',
        3: 'Und zu den Heiligen, die im Lande sind, (sag ich): / "Das sind die Herrlichen, an ihnen hab ich meine Lust."',
        4: 'Viel Qualen warten derer, die andern Göttern dienen. / Nicht will ich ihre Blut-Trankopfer spenden / Noch ihre Namen auf meine Lippen nehmen.',
        5: 'Jahwe ist mein Erbteil und mein Becher, / Du bewahrst mein Los.',
        6: 'Ich empfing mein Teil in lieblichem Lande, / Ein solches Erbe gefällt mir wohl.',
        7: 'Ich preise Jahwe, der mich beraten, / Auch des Nachts mahnt mich dazu mein Gewissen.',
        8: 'Ich halte mir Jahwe beständig vor Augen. / Ist er mir zur Rechten, so wanke ich nicht.',
        9: 'Drum freut sich mein Herz und frohlockt meine Seele, / Auch mein Leib ist sicher geborgen.',
        10: 'Denn du gibst meine Seele dem Tode nicht preis. / Du läßt deinen Frommen das Grab nicht schaun.',
        11: 'Du wirst mir zeigen den Lebenspfad: / Vor deinem Antlitz ist Fülle an Freuden, / In deiner rechten sind ewige Wonnen.',
    },
    17: {
        1: 'Ein Gebet Davids. / Höre, Jahwe, meine gerechte Bitte, vernimm mein Flehen! / Merk auf mein Gebet, das nicht von falschen Lippen kommt!',
        2: 'Von deinem Antlitz geh mein Urteil aus, / Denn deine Augen sehen recht!',
        3: 'Prüfst du mein Herz, durchforschest du mich des Nachts / Und läuterst mich — so findest du nichts Böses: / Denk ich Arges — es kommt nicht über meinen Mund.',
        4: 'Seh ich der Menschen Tun und Treiben, so hüt ich mich, treu deinem Wort, / Vor der Schadenstifter Pfaden.',
        5: 'Meine Schritte wandeln fest in deinen Wegen, / Meine Tritte wanken nicht.',
        6: 'So ruf ich zu dir, denn du erhörest mich, Gott. / Neig mir dein Ohr, vernimm mein Wort!',
        7: 'Erzeig mir deine wunderbare Gnade, du Retter derer, / Die sich vor ihren Widersachern / Bei deiner starken Hand zu bergen suchen.',
        8: 'Bewahre du mich wie den Augenstern! / Birg mich im Schatten deiner Flügel',
        9: 'Vor den Frevlern, die mich vergewaltigen, / Vor meinen grimmen Feinden, die sich um mich scharen!',
        10: 'Ihr stolzes Herz verschließen sie, / Mit ihrem Munde reden sie voll Übermut.',
        11: 'Auf Schritt und Tritt umringen sie uns jetzt, / Es spähen ihre Augen, wie sie uns zu Boden werfen.',
        12: 'Sie gleichen einem Löwen, der nach Beute giert, / Und einem jungen Leu, der im Verstecke lauert.',
        13: 'Auf, Jahwe! Tritt ihnen entgegen, strecke sie nieder! / Vor den Frevlern rette mich durch dein Schwert!',
        14: 'Rette mich von den Menschen durch deine Hand, o Jahwe, / Rette mich von den Leuten dieser Welt! / Sie haben ihr Teil in diesem Leben, / Und du füllst ihren Bauch mit deinen Schätzen. / Sie haben Söhne die Menge / Und lassen ihren Kindern großen Reichtum.',
        15: 'Ich aber will dein Antlitz schauen in Gerechtigkeit, / Ich werde mich sättigen, wenn ich erwache, an deinem Anblick.',
    },
    18: {
        1: 'Dem Sangmeister. Vom Knechte Jahwes, von David, der vor Jahwe die Worte dieses Liedes redete, als ihn Jahwe errettet hatte aus der Hand aller seiner Feinde, auch aus der Hand Sauls.',
        2: 'Er sprach: Von Herzen lieb ich dich, Jahwe, meine Stärke!',
        3: 'Jahwe, mein Fels, meine Burg, mein Retter bist du! / Mein Gott ist mein Hort, zu dem ich fliehe. / Mein Schild, das Horn meines Heils, meine Feste ist er.',
        4: 'Preiswürdig, ruf ich, ist Jahwe, / Ich ward errettet von meinen Feinden!',
        5: 'Des Todes Stricke umfingen mich, / Verderbliche Bäche schreckten mich;',
        6: 'Der Unterwelt Bande umringten mich, / Es ergriffen mich Schlingen des Todes.',
        7: 'In meiner Angst rief ich Jahwe an / Und schrie zu meinem Gott. / Da vernahm er mein Beten aus seinem Palast, / Mein Schreien drang in seine Ohren.',
        8: 'Es wankte und schwankte die Erde, / Der Berge Grundfesten bebten / Und zitterten, weil er zornig war.',
        9: 'In seiner Nase stieg Rauch empor, / Aus seinem Munde fraß Feuer, / Glühende Kohlen flammten aus ihm.',
        10: 'Er neigte den Himmel und fuhr herab, / Unter seinen Füßen war Wolkennacht.',
        11: 'Er fuhr auf dem Kerub und flog einher, / Schwebte auf den Schwingen des Windes.',
        12: 'Er machte Dunkel zu seiner Hülle, / Zu seinem Gezelte ringsumher; / Es umgab ihn Wasserflut und dickes Gewölk.',
        13: 'Vom Glanz vor ihm her durchzuckten die Wolken / Hagel und feurige Kohlen.',
        14: 'Es donnerte Jahwe vom Himmel her, / Der Höchste ließ seine Stimme schallen / (Mit Hagel und feurigen Kohlen).',
        15: 'Er schoß seine Pfeile, zerstreute sie.',
        16: 'Da wurden sichtbar die Betten des Meeres, / Bloßgelegt des Erdrunds Gründe / Vor deinem Schelten, Jahwe, / Vor deines Zornhauchs Schnauben.',
        17: 'Er griff aus der Höhe, erfaßte mich / Und zog mich aus tiefen Wassern.',
        18: 'Von meinem Todfeind befreite er mich, / Von meinen Hassern, die mir zu mächtig waren.',
        19: 'An meinem Unglückstag überfielen sie mich, / Aber Jahwe ward meine Stütze.',
        20: 'Er führte mich ins Freie hinaus; / Er rettete mich, weil er mich liebte.',
        21: 'Jahwe vergalt mir nach meiner Gerechtigkeit, / Nach meiner Hände Reinheit lohnte er mir.',
        22: 'Denn Jahwes Wege bin ich gewandelt, / Nicht abgefallen von meinem Gott.',
        23: 'Nein, all seine Rechte befolgte ich treu, / Von seinen Satzungen wich ich nicht.',
        24: 'Ich war ohne Tadel vor ihm / Und hütete mich vor Missetat.',
        25: 'Drum vergalt mir Jahwe nach meiner Gerechtigkeit, / Nach meiner Lauterkeit, die ihm bekannt.',
        26: 'Dem Guten erzeigst du dich gütig, / Mit dem redlichen Manne verfährst du redlich;',
        27: 'Dem Reinen zeigst du dich rein, / Dem Falschen vergiltst du nach seinem Verhalten.',
        28: 'Denn du hilfst den bedrückten Leuten, / Doch stolze Augen erniedrigst du.',
        29: 'Du machst meine Leuchte licht; / Jahwe, mein Gott, erhellet mein Dunkel.',
        30: 'Denn im Vertrauen auf dich greif ich Heerhaufen an, / Und mit meinem Gott überspringe ich Mauern.',
        31: 'Gottes Wege sind makellos, / Jahwes Wort ist bewährt; / Ein Schild ist er allen, die zu ihm fliehn.',
        32: 'Denn wer ist Eloah als Jahwe allein? / Und wer ist ein Hort außer unserem Gott?',
        33: "Gott ist's, der mich mit Kraft gegürtet, / Der meinen Weg ohn Anstoß machte.",
        34: 'Er gab mir der Hindin Schnelligkeit / Und stellte mich auf die Höhen.',
        35: 'Er übte meine Hände zum Kampf, / Daß meine Arme den ehernen Bogen spannten.',
        36: 'Du gabst mir den Schild deines Heils, / Deine Rechte stützte mich, / Und deine Milde machte mich groß.',
        37: 'Du ließest mich frei meines Weges gehn, / Und meine Knöchel wankten nicht.',
        38: 'Ich verfolgte die Feinde und holte sie ein; / Ich kehrte nicht um, bis ich sie vernichtet.',
        39: 'Ich zerschellte sie, daß sie nimmer aufstanden, / Zu meinen Füßen sanken sie hin.',
        40: 'Du gürtetest mich mit Kraft zum Streit, / Du beugtest meine Gegner unter mich.',
        41: 'Meine Feinde ließest du vor mir fliehn, / Und meine Hasser zerschellte ich.',
        42: 'Sie schrien, aber kein Helfer war da; / Sie schrien zu Jahwe — er hörte sie nicht.',
        43: 'Ich zerrieb sie wie Staub vor dem Winde, / Wie Gassenkot zertrat ich sie.',
        44: 'Du halfst mir aus Volkesfehden, / Setztest mich ein zum Herrscher der Heiden: / Leute, mir unbekannt, wurden mir dienstbar.',
        45: 'Schon als sie hörten (von meinen Siegen), gehorchten sie mir, / Des Auslands Bewohner schmeichelten mir.',
        46: 'Des Auslands Bewohner welkten dahin / Und kamen zitternd aus ihren Burgen.',
        47: 'Jahwe lebt, mein Hort sei gepriesen, / Erhoben der Gott meines Heils,',
        48: 'Der Gott, der mir Rache verliehn / Und Völker mir unterworfen,',
        49: 'Der mich gerettet von meinen Feinden! / Über meine Gegner erhebst du mich. / Entreißt mich dem Mann der Gewalttat.',
        50: 'Drum preis ich dich, Jahwe, unter den Völkern, / Deinem Namen will ich lobsingen. Denn Jahwe schenkt seinem Könige Heil / Und erweiset Gnade seinem Gesalbten: / David und seinem Samen auf ewig!',
    },
    19: {
        1: 'Dem Sangmeister. Ein Psalm Davids.',
        2: 'Die Himmel erzählen Gottes Herrlichkeit. / Und seiner Hände Werk verkündiget die Feste.',
        3: 'Ein Tag meldet dem andern das Wort, / Eine Nacht bringt der andern die Kunde.',
        4: 'Dies ist keine Sprache, dies ist keine Rede, / Deren Stimme man nicht verstünde.',
        5: 'In alle Lande geht aus ihr Klang, / Ihr Ruf bis ans Ende der Erde. / Dort hat er der Sonne ein Zelt gesetzt.',
        6: 'Sie ist dem Bräutigam gleich, der hervortritt aus seinem Gemach, / Freut sich, wie ein Held zu laufen die Bahn.',
        7: 'Vom Ende des Himmels geht sie aus / Und läuft bis ans andere Ende. / Nichts bleibt verborgen vor ihrer Glut.',
        8: 'Jahwes Gesetz ist makellos, / Es erquicket die Seele. / Jahwes Zeugnis ist zuverlässig, / Es macht den Toren weise.',
        9: 'Jahwes Befehle sind richtig, / Sie erfreuen das Herz. / Jahwes Gebot ist lauter, / Es erleuchtet die Augen.',
        10: 'Jahwes Verehrung ist rein, / Sie bestehet für immer. / Jahwes Sprüche sind wahr, / Rechtschaffen zumal.',
        11: 'Köstlicher sind sie als Gold / Und viel gediegenes Gold. / Ja süßer sind sie als Honig / Und aus den Waben fließender Seim.',
        12: 'Auch wird dein Knecht durch sie belehrt; / Wer sie hält, hat großen Gewinn.',
        13: 'Wer ist sich aller Vergehen bewußt? / Von verborgenen Sünden sprich mich los!',
        14: 'Auch vor Frechen beschirme deinen Knecht, / Daß sie mich nicht beherrschen! / Dann bin ich unsträflich / Und frei von schwerer Schuld. So nimm denn gnädig auf die Worte meines Mundes / Und meines Herzens Sinnen, / Jahwe, / Mein Fels und mein Erlöser!',
    },
    20: {
        1: 'Dem Sangmeister. Ein Psalm Davids.',
        2: '(Der levitische Sängerchor:) / Es erhöre dich Jahwe am Tage der Not, / Der Name des Gottes Jakobs schütze dich!',
        3: 'Er sende dir Hilfe vom Heiligtum / Und stütze dich von Zion her!',
        4: 'Er gedenke all deiner Speisopfer, / Und dein Brandopfer sei ihm wert! Sela.',
        5: 'Er gebe dir, was dein Herz begehrt, / Und all deine Wünsche erfülle er!',
        6: 'Dann wollen wir jauchzen ob deiner Hilfe / Und im Namen unsers Gottes das Banner schwingen. / Jahwe gewähre dir all dein Bitten!',
        7: '(Eine Einzelstimme:) / Nun weiß ich, daß Jahwe seinem Gesalbten hilft, / Aus seinem heiligen Himmel erhört er ihn / Durch gewaltige Taten seiner Rechten.',
        8: 'Diese vertrauen auf Wagen und jene auf Rosse, / Wir aber rufen an den Namen Jahwes, unsers Gottes.',
        9: 'Sie sinken nieder und fallen, / Wir aber stehen und halten uns aufrecht. (Schlußruf des ganzen Sängerchors:) / Jahwe, rette den König! / Erhör uns heut, da wir zu dir flehn!',
    },
    21: {
        1: 'Dem Sangmeister. Ein Psalm Davids.',
        2: '(Der levitische Sängerchor:) / Ob deiner Macht, o Jahwe, freut sich der König / Und ob deiner Hilfe — wie jauchzt er so sehr!',
        3: 'Seines Herzens Verlangen hast du ihm erfüllt, / Seiner Lippen Begehren ihm nicht versagt. Sela.',
        4: 'Ja, reichsten Segen hast du ihm geschenkt, / Ihm aufs Haupt gesetzt eine Krone von Gold.',
        5: 'Um Leben bat er — du gabst es ihm, / Langes Leben für immer und ewig.',
        6: 'Durch deine Hilfe ist groß sein Ruhm, / Glanz und Hoheit legst du auf ihn.',
        7: 'Ja, du machst ihn zum Segen auf ewig, / Erfüllest ihn mit Freude vor dir.',
        8: '(Eine Einzelstimme:) / Denn der König vertrauet auf Jahwe, / Durch des Höchsten Gnade wanket er nicht.',
        9: 'Deine Hand wird treffen all deine Feinde, / Deine Rechte erreichen, die dich hassen.',
        10: 'Du machst sie gleich einem Feuerofen, wenn du erscheinst. / Jahwe verderbt sie in seinem Zorn, / Und Feuer wird sie verzehren.',
        11: 'Ihre Kinder wirst du von der Erde vertilgen, / Ihr Geschlecht von den Menschen ausrotten.',
        12: 'Sinnen sie Böses wider dich, / Erdenken sie Tücke — es ist umsonst!',
        13: 'Denn du schlägst sie in die Flucht, / Deine Pfeile richtest du gegen sie. (Schlußruf des ganzen Sängerchors:) / Erheb dich, Jahwe, in deiner Macht! / Dann preisen wir singend deine Kraft.',
    },
    22: {
        1: 'Dem Sangmeister, nach (der Melodie von:) "Hindin der Morgenröte" (?). / Ein Psalm Davids.',
        2: 'Mein Gott, mein Gott, warum hast du mich verlassen?! / Ohne Hilfe zu finden, muß ich zu dir schrein.',
        3: 'Mein Gott, ich rufe am Tage, doch du hörest mich nicht; / Auch (ruf ich) des Nachts, / Aber mein Klagen wird nicht gestillt.',
        4: 'Und dennoch bist du der Heilige, / Über Israels Lobliedern thronend.',
        5: 'Dir haben unsre Väter vertraut, / sie haben vertraut: du hast sie errettet.',
        6: 'Sie schrien zu dir und wurden frei, / Sie vertrauten dir und sind nicht zuschanden geworden.',
        7: 'Ich aber bin ein Wurm und kein Mensch, / Von den Leuten verhöhnt und verachtet vom Volk.',
        8: 'Alle, die mich sehen, spotten mein, / Verziehen die Lippen, schütteln den Kopf:',
        9: '"Befiehl dich Jahwe — der rette ihn, / Er reiß ihn heraus, hat er Freude an ihm!"',
        10: 'Ja, du hast mich gezogen aus Mutterschoß, / Mit Vertrauen mich erfüllt an der Mutter Brust.',
        11: 'Auf dich bin ich gewiesen von Anfang an, / Seit meiner Geburt bist du mein Gott.',
        12: 'Sei nicht fern von mir, denn Not ist nah — / Ich habe ja sonst keinen Helfer!',
        13: 'Viele Stiere haben mich umringt, / Die Starken Basans umgeben mich.',
        14: 'Ihren Rachen öffnen sie wider mich / Wie ein reißender, brüllender Löwe.',
        15: 'Wie Wasser bin ich hingegossen, / All meine Gebeine sind auseinandergereckt. / Es ist mein Herz wie Wachs, / Zerschmolzen in meinem Innern.',
        16: 'Vertrocknet wie eine Scherbe ist meine Kraft, / Die Zunge klebt mir am Gaumen, / Und du lagerst mich in den Todesstaub.',
        17: 'Ja, es haben mich Hunde umringt, / Eine Bösewichterrotte hat mich umkreist, / Sie durchbohren mir Hände und Füße.',
        18: 'Zählen könnt ich all meine Gebeine; / Sie aber freuen sich meiner Qual.',
        19: 'Sie teilen meine Kleider unter sich / Und werfen das Los über mein Gewand.',
        20: 'Du aber, Jahwe, bleib nicht fern! / Meine Stärke, eil mir zu Hilfe!',
        21: 'Rette mein Leben vom Schwert, / Aus der Hunde Gewalt reiß meine Seele.',
        22: 'Hilf mir doch aus des Löwen Rachen, / Aus der Büffel Hörnern mache mich frei!',
        23: 'Dann will ich meinen Brüdern deinen Namen künden, / Inmitten der Gemeinde dir lobsingen:',
        24: '"Die ihr Jahwe fürchtet, preist ihn, / Alle Nachkommen Jakobs, ehret ihn / Und scheut euch vor ihm, alle Israelsöhne!',
        25: 'Denn nicht verachtet, nicht verschmäht er des Armen Qual, / Nicht hat er sein Antlitz vor ihm verborgen, / Und als er schrie, hat er ihn erhört."',
        26: 'Dir gilt mein Lobpreis in großer Gemeinde. / Meine Gelübde bezahl ich vor allen Frommen.',
        27: 'Essen sollen Demütige und satt werden; / Preisen werden Jahwe, die ihn suchen: / "Euer Herz soll sich laben auf ewig!"',
        28: 'Des gedenkend werden sich wenden zu Jahwe / Alle Enden der Erde; / Und niederfallen werden vor dir / Alle Geschlechter der Heiden.',
        29: 'Denn Jahwes ist das Königtum, / Er ist aller Völker Herrscher.',
        30: 'Niederfallen werden vor ihm alle Großen der Erde, / Wenn sie gegessen haben. / Vor ihm werden auch alle knien. / Die hinabfahren in des Grabes Staub / Und die ihr Leben nicht fristen können.',
        31: 'Die Nachwelt soll ihm dienen, / Man wird vom Herrn erzählen dem künftigen Geschlecht. Sie werden kommen und seine Treue verkünden / Dem spätern Volk, daß er es vollbracht!',
    },
    23: {
        1: 'Ein Psalm Davids.',
        2: 'Jahwe ist mein Hirt: mir mangelt nichts. / Auf grünen Auen läßt er mich ruhn, / Zu stillen Wassern führt er mich.',
        3: 'Er labet meine Seele, / Er leitet mich auf rechten Pfaden / Um seines Namens willen.',
        4: 'Auch wenn ich wandre durch ein Tal des Todesschattens, / Fürcht ich kein Leid. / Denn du bist bei mir; dein Hirtenstab und Stecken, / Die trösten mich.',
        5: 'Du deckest mir den Tisch / Vor meiner Dränger Augen. / Du salbst mein Haupt mit Öl, / Mein Becher fließt über.',
        6: 'Nur Glück und Gnade folgen mir / Mein Leben lang, / Und wieder weilen werde ich in Jahwes Haus / Bis an das Ende meiner Tage.',
    },
    24: {
        1: 'Ein Psalm Davids. / (Der Festchor, während er mit der Bundeslade den Berg Zion hinaufsteigt:) / Jahwe ist die Erde und was sie erfüllt, / Der Erdkreis mit seinen Bewohnern.',
        2: 'Denn er hat sie auf Meere gegründet / Und über Ströme sie aufgerichtet.',
        3: '(Eine Einzelstimme:) / Wer darf Jahwes Berg besteigen, / Wer darf treten an seine heilige Stätte?',
        4: '(Der Festchor:) / Wer schuldlose Hände hat und reines Herzens ist, / Wer nicht auf Lüge sinnt / Und nicht betrügerisch schwört —',
        5: 'Der wird Segen empfangen von Jahwe / Und Hilfe vom Gott seines Heils.',
        6: 'So sind, die nach ihm fragen: / Die dein Antlitz suchen, sind Jakob. Sela.',
        7: '(Der Festchor oben vor den Toren der Zionsburg:) / Erhebt, ihr Tore, eure Häupter, / Ja, reckt euch empor, uralte Pforten, / Damit der König der Ehren einziehe!',
        8: "(Eine Einzelstimme drinnen, die gleichsam eine Antwort der Tore ist:) / Wer ist denn der König der Ehren? / (Der Festchor:) / Jahwe ist's, ein Starker, ein Held, / Jahwe, ein Held im Streit!",
        9: 'Erhebt, ihr Tore, eure Häupter, / Ja reckt euch empor, uralte Pforten, / Damit der König der Ehren einziehe!',
        10: '(Wieder die Einzelstimme drinnen:) / Wer ist denn der König der Ehren? / (Der Festchor draußen:) / Jahwe (der Herr) der Heerscharen, er ist der König der Ehren. / Sela.',
    },
    25: {
        1: 'Von David. / Auf dich, o Jahwe, ist mein Herz gerichtet.',
        2: 'Bei dir, mein Gott, fühl ich mich sicher; / Laß mich nicht zuschanden werden! / Laß meine Feinde nicht über mich frohlocken!',
        3: 'Gar niemand, der dein harret, wird zuschanden. / Zuschanden werden, die ohn Ursach treulos sind.',
        4: 'Deine Wege, Jahwe, tu mir kund, / Deine Steige lehre mich!',
        5: 'Halt mich auf dem Pfade deiner Wahrheit, lehre mich! / Denn der Gott, der mir hilft, bist du. / Dein harr ich allezeit.',
        6: 'Sei eingedenk, o Jahwe, deiner Huld und Gnade, / Denn sie sind von Ewigkeit.',
        7: 'Gedenke nicht der Sünden meiner Jugend / noch meiner Missetaten! / Gedenk du mein nach deiner Gnade / Um deiner Güte willen, Jahwe!',
        8: 'Treugesinnt ist Jahwe und voll Güte; / Drum zeigt er Sündern auch den rechten Weg.',
        9: 'Im Rechte leitet er Demütige / Und lehret die Elenden seinen Weg.',
        10: "Kann's anders sein, als daß die Wege Jahwes / alle Gnade sind und Wahrheit / Für die, die da bewahren seinen Bund und seine Zeugnisse?",
        11: 'Laß, Jahwe, doch um deines Namens willen / Vergebung werden meiner Schuld, denn sie ist groß.',
        12: 'Mit Jahwes Furcht erfülltem Mann / Zeigt Gott den Weg, den er erwählen soll.',
        13: 'Nicht nur ihm selber wird es wohl ergehn, / Nein, auch sein Same wird das Land besitzen.',
        14: 'Sein Wohlgefallen schenkt Jahwe denen, die ihn fürchten, / Und seinen Bund läßt er sie wissen.',
        15: 'Auf Jahwe richten sich beständig meine Augen; / Denn er wird aus dem Netze ziehen meinen Fuß.',
        16: 'Prüfend wende dich zu mir und sei mir gnädig! / Denn einsam bin ich und elend.',
        17: 'Zermalmend trifft die Angst mein Herz; / Aus meinen Nöten rette mich!',
        18: 'Ruhn laß dein Aug auf meinem Leid und Ungemach, / Vergib mir alle meine Sünden!',
        19: 'Richte deinen Blick auf meine Feinde, wie sie zahlreich sind / Und wie sie ohne Grund mich hassen.',
        20: 'Schütze meine Seele und errette mich! / Laß mich nicht zuschanden werden, denn dir vertraue ich.',
        21: 'Treue und Aufrichtigkeit mögen mich behüten, / Denn ich harre dein!',
        22: 'Elohim, erlöse Israel aus allen seinen Nöten!',
    },
    26: {
        1: 'Von David. / Hilf mir zu meinem Recht, o Jahwe; / denn in Unschuld bin ich gewandelt, / Und auf Jahwe hab ich vertrauet, ohne zu wanken.',
        2: 'Prüfe mich, Jahwe, erprobe mich, / Erforsche meine Nieren und mein Herz!',
        3: 'Denn deine Gnade ist mir stets vor Augen, / Und in deiner Wahrheit wandle ich.',
        4: 'Ich sitze nicht bei falschen Leuten, / Mit Hinterlistigen verkehre ich nicht.',
        5: 'Ich hasse der Bösen Versammlung, / Und bei den Gottlosen sitze ich nicht.',
        6: 'Ich will meine Hände in Unschuld waschen / Und möchte wandeln, o Jahwe, um deinen Altar,',
        7: 'Laut anzustimmen den Lobgesang / Und zu erzählen all deine Wunder.',
        8: 'Lieb hab ich, Jahwe, deines Hauses Stätte / Und den Ort, da deine Herrlichkeit wohnt.',
        9: 'Raffe meine Seele nicht hin mit Sündern / Noch mit Blutmenschen mein Leben:',
        10: 'An ihren Händen klebt Schandtat, / Ihre Rechte ist voll Bestechung.',
        11: 'Ich aber will in meiner Unschuld wandeln; / Errette mich und sei mir gnädig!',
        12: 'Mein Fuß steht auf ebenem Weg; / In der Gemeinde will ich Jahwe preisen.',
    },
    27: {
        1: 'Von David. / Jahwe ist mein Licht und mein Heil! / Vor wem sollt ich mich fürchten? / Jahwe ist meines Lebens Schutz! / Vor wem sollt ich zagen?',
        2: 'Dringen Frevler auf mich ein, / Mein Fleisch zu fressen; / Kommen meine Dränger und Feinde heran: / Sie müssen straucheln und fallen.',
        3: 'Lagert sich auch ein Heer wider mich — / Mein Herz ist ohne Furcht. / Erhebt sich Krieg gegen mich — / Auch dann bin ich getrost.',
        4: 'Eins nur erbitt ich von Jahwe, / Dies wäre mein Wunsch: / Daß ich in Jahwes Hause bleiben darf / Mein Leben lang, / Um Jahwes Huld zu schauen / Und immer seinen Tempel zu besuchen.',
        5: 'Denn er bringt mich in seine Hütte / Am Unglückstage, / Schirmt mich in seines Zeltes Schirm, / Auf einen Fels erhöht er mich.',
        6: 'So erhebt sich mein Haupt über meine Feinde ringsum. / Opfer des Jubels will ich opfern in seinem Zelt, / Will Jahwe singen und spielen.',
        7: 'Höre, Jahwe, ich rufe laut! / Sei mir denn gnädig, erhöre mich!',
        8: 'Zu dir spricht mein Herz: (da du geboten:) \'Suchet mein Antlitz!\' / "Dein Antlitz, Jahwe, such ich auch."',
        9: 'Verbirg dein Antlitz nicht vor mir! / Weise nicht ab im Zorn deinen Knecht! / Meine Hilfe bist du. So verwirf mich nicht / Und verlaß mich nicht, Gott meines Heils!',
        10: 'Wenn mich Vater und Mutter verlassen, / Nimmt Jahwe mich auf.',
        11: 'Zeige mir, Jahwe, deinen Weg, / Leit mich auf ebner Bahn / Um meiner Feinde willen.',
        12: 'Gib mich nicht preis meiner Dränger Wut; / Denn es erheben sich gegen mich falsche Zeugen, / Leute, die Frevel schnauben.',
        13: 'Glaubte ich nicht, noch Jahwes Güte zu schauen / In der Lebendigen Land — (ich wäre vergangen in meinem Elend.)',
        14: 'Hoff auf Jahwe! Sei getrost und unverzagt! / Ja, hoff auf Jahwe!',
    },
    28: {
        1: 'Von David. / Zu dir, o Jahwe, rufe ich, / Mein Fels, gib mir doch Antwort! / Denn hörst du mich nicht, / So gleiche ich denen, die in die Grube fahren.',
        2: 'Höre mein lautes Flehn, wenn ich zu dir schreie, / Wenn ich meine Hände erhebe / Zu deinem Allerheiligsten.',
        3: 'Raff mich nicht weg mit Frevlern und Übeltätern, / Die freundlich reden mit ihren Nächsten, / Während sie Böses im Sinne haben.',
        4: 'Vergilt du ihnen nach ihrem Tun und ihren bösen Werken! / Nach ihrer Hände Tat gib ihnen, / Vergilt du ihnen, was sie verdient!',
        5: 'Wenn sie nicht achten auf Jahwes Tun und seiner Hände Werk, / So reiß er sie nieder und baue sie nicht!',
        6: 'Gelobt sei Jahwe! / Denn er hat mein lautes Flehen gehört.',
        7: 'Jahwe ist mein Schutz und mein Schild. / Auf ihn hat mein Herz vertraut, / Und ich hab Hilfe gefunden! / Drum jubelt mein Herz, / Und mit meinem Liede will ich ihm danken.',
        8: 'Jahwe schütze sein Volk! / Ein Heilsort ist er seinem Gesalbten.',
        9: 'O hilf deinem Volk und segne dein Erbe, / Weide und trage sie ewiglich!',
    },
    29: {
        1: 'Ein Psalm Davids. / Bringet Jahwe, ihr Gottessöhne, / Bringet Jahwe Ehre und Preis!',
        2: 'Bringt Jahwe seines Namens Ehre! / Huldigt Jahwe in heiligem Schmuck!',
        3: 'Jahwes Stimme schallt über den Wassern: / Der Gott der Ehre donnert, / Jahwe thront über mächtigen Wassern.',
        4: 'Jahwes Stimme erschallt mit Macht, / Jahwes Stimme erschallt mit Pracht.',
        5: 'Jahwes Stimme zerschmettert Zedern, / Jahwe zerschmettert des Libanons Zedern.',
        6: 'Er läßt hüpfen wie Kälber, / Libanon und Sirjon wie junge Büffel.',
        7: 'Jahwes Stimme sprüht Feuerflammen.',
        8: 'Jahwes Stimme läßt beben die Wüste, / Beben läßt Jahwe die Wüste von Kades.',
        9: 'Jahwes Stimme läßt Hinden gebären, / Entblättert die Wälder. / In seinem Tempel ruft alles: "Ehre!"',
        10: 'Jahwe thronte einst über der Sintflut, / Jahwe wird thronen als König auf ewig.',
        11: 'Jahwe verleiht seinem Volke Macht, / Jahwe segnet sein Volk mit Frieden!',
    },
    30: {
        1: 'Ein Psalm. Nach dem Liede der Hausweihe (?). Von David.',
        2: 'Ich erhebe dich, Jahwe: Du hast mich errettet, / Daß meine Feinde nicht über mich jauchzten.',
        3: 'Jahwe, mein Gott, ich schrie zu dir: / Du hast mich geheilt.',
        4: 'Jahwe, du hast mich dem Tode entrissen, / Mich neubelebt, daß ich nicht in die Grube sank.',
        5: 'Lobsinget Jahwe, ihr, seine Frommen, / Und dankt seinem heiligen Namen!',
        6: 'Denn nur einen Augenblick währet sein Zorn, / Doch lebenslang seine Huld. / Am Abend kehret Weinen ein, / Des Morgens aber ist Jubel.',
        7: 'Ich dachte in meinem Glück: / "Ich werde nimmermehr wanken!"',
        8: 'Jahwe, in deiner Huld / Hattest du meinem Berge Macht verliehn. / Dann aber verbargst du dein Antlitz — / Da war ich bestürzt.',
        9: 'Zu dir, o Jahwe, rief ich, / Zu Jahwe hab ich gefleht:',
        10: '"Was nützt dir\'s, daß du mein Blut vergießt, / Daß ich niederfahre zur Grube? / Kann denn der Staub dich preisen? / Kann er deine Treue verkünden?',
        11: 'O höre, Jahwe, sei mir doch gnädig! / Jahwe, sei mir ein Helfer!"',
        12: 'Du hast mir ja stets schon mein Klagen in Reigen verwandelt, / Meinen Sack gelöst, mich mit Freude gegürtet, Damit ich dir singe und nimmer verstumme. / Jahwe, mein Gott, immerdar will ich dich preisen!',
    },
    31: {
        1: 'Dem Sangmeister. Ein Psalm Davids.',
        2: 'Bei dir, o Jahwe, suche ich Zuflucht: / Mög ich nimmer zuschanden werden! / Nach deiner Treue errette mich!',
        3: 'Neige dein Ohr zu mir, befreie mich eilends! / Sei mir ein schützender Fels, / Eine feste Burg, mir zu helfen!',
        4: 'Ja, mein Fels, meine Burg bist du, / Ob deines Namens wirst du mich führen und leiten.',
        5: 'Herausziehn wirst du mich aus dem Netz, / Das man mir heimlich gelegt; / Denn du bist mein Schutz.',
        6: 'In deine Hand befehl ich meinen Geist! / Du erlösest mich, Jahwe, du treuer Gott.',
        7: 'Verhaßt sind mir, die nichtigen Götzen dienen; / Ich traue auf Jahwe.',
        8: 'Jubeln will ich und fröhlich sein ob deiner Gnade; / Denn du siehest mein Elend an, / Du merkst auf die Not meiner Seele.',
        9: 'Du gibst mich nicht in des Feindes Hand, / Du stellst meine Füße auf freien Raum.',
        10: 'Sei mir gnädig, Jahwe, denn mir ist angst! / Mir schwindet in Gram Aug, Seele und Leib.',
        11: 'In Kummer vergehet mein Leben, / Meine Jahre entrinnen in Seufzen. / Ob meiner Sünde wankt meine Kraft, / Und meine Gebeine verfallen.',
        12: 'Durch all meine Dränger bin ich ein Schimpf geworden, / Eine Last meinen Nachbarn, meinen Freunden ein Schreck; / Die mich draußen erblicken, fliehen vor mir.',
        13: 'Wie ein Toter bin ich vergessen, entschwunden dem Sinn, / Ich bin wie ein zerbrochen Gefäß.',
        14: 'Ja ich höre vieler Verleumdung, / Grauen umgibt mich ringsum. / Beraten sie zusammen wider mich, / So sinnen sie drauf, mir das Leben zu rauben.',
        15: 'Ich aber, Jahwe, traue auf dich, / Ich spreche: "Du bist mein Gott."',
        16: 'In deiner Hand liegt mein Geschick. / Meiner Feinde Gewalt und meinen Verfolgern entreiße mich!',
        17: 'Laß deinem Knechte dein Antlitz leuchten, / Hilf mir durch deine Gnade!',
        18: 'Jahwe, nicht werd ich beschämt, denn ich rufe dich an. / Zuschanden mögen die Frevler werden, / Mögen sie fahren zur Unterwelt!',
        19: 'Verstummen sollen die Lügenlippen, / Die frech den Gerechten schmähn / In Übermut und Hohn!',
        20: 'Wie groß ist deine Güte, / Die du denen bereit hältst, die dich fürchten, / Erweisest denen, die dir vertraun, / Vor allen Menschenkindern.',
        21: 'Du schirmst sie im Schirm deines Angesichts / Vor den Rotten der Menschen, / Birgst sie in einer Hütte / Vor dem Hader der Zungen.',
        22: 'Gepriesen sei Jahwe! / Er hat seine Gnade mir wunderbar / Erzeigt in einer festen Stadt.',
        23: 'Ich aber dachte in meiner Angst, / Ich wäre von dir verstoßen. / Doch du vernahmest mein lautes Flehn, / Als ich zu dir schrie.',
        24: 'Liebt Jahwe, all seine Frommen! / Die Treuen behütet Jahwe, / Aber die Stolzen straft er streng. Seid stark und mutigen Herzens / Alle, die ihr auf Jahwe harrt!',
    },
    32: {
        1: 'Von David. Eine Betrachtung (?). / Heil dem, des Missetat vergeben, des Sünde erlassen ist!',
        2: 'Heil dem Menschen, dem Jahwe die Schuld nicht anrechnet, / Und in des Geist kein Trug ist.',
        3: 'Als ich schwieg, schwand mein Gebein dahin, / Weil ich unaufhörlich seufzen mußte.',
        4: 'Denn deine Hand lag schwer auf mir bei Tag und Nacht, / Mein Lebenssaft vertrocknete wie in der Sommerglut. Sela.',
        5: 'Da tat ich dir meine Sünde kund, / und meine Schuld verdeckte ich nicht. / Ich sprach: "Bekennen will ich Jahwe meine Missetat." / Da hast du meine Sündenschuld weggenommen. Sela.',
        6: 'Drum bete jeder Fromme zu dir, solange du noch zu finden bist. / Fluten auch mächtige Wasser einher, / ihn werden sie sicher nicht treffen.',
        7: 'Du bist mein Schirm, vor Drangsal bewahrest du mich, / Umringst mich mit Rettungsjubeln. Sela.',
        8: 'Ich will dich belehren, dir zeigen den Weg, den du gehen mußt; / Fest will ich auf dich mein Auge richten.',
        9: 'Seid nicht wie das Roß, wie das unverständige Maultier! / Mit Zaum und Halfter, ihrem Geschirr, muß man sie zügeln; / Sonst nahen sie nicht zu dir.',
        10: 'Der Gottlose hat viel Schmerzen. / Wer aber auf Jahwe traut, den umgibt er mit Gnade.',
        11: 'Freut euch in Jahwe, frohlockt, ihr Gerechten, / Und jauchzet, ihr Redlichen alle!',
    },
    33: {
        1: 'Jubelt, Gerechte, in Jahwe! / Den Redlichen ziemet Lobgesang.',
        2: 'Dankt Jahwe auf der Zither, / Auf zehnsaitiger Harfe spielet ihm!',
        3: 'Singt ihm ein neues Lied, / Spielt schön und kräftig mit Jubelgetön!',
        4: 'Denn Jahwes Wort ist wahrhaftig, / Und all sein Tun vollzieht sich in Treue.',
        5: 'Er liebet Gerechtigkeit und Recht, / Jahwes Güte erfüllt die Erde.',
        6: 'Durch Jahwes Wort sind die Himmel gemacht, / Durch den Hauch seines Mundes ihr ganzes Heer.',
        7: 'Er sammelt als Haufen des Meeres Wasser, / Er legt die Fluten in Vorratskammern.',
        8: 'Vor Jahwe fürchte sich alle Welt, / Alle Erdbewohner erbeben vor ihm!',
        9: 'Denn er hat gesprochen — da ward es; / Er hat geboten — und es stand da.',
        10: 'Jahwe vernichtet der Heiden Plan, / Vereitelt der Völker Gedanken.',
        11: 'Jahwes Plan bleibt ewig bestehn, / Seines Herzens Gedanken für alle Geschlechter.',
        12: 'Heil dem Volke, des Gott ist Jahwe, / Dem Volk, das er sich zum Erbe erwählt!',
        13: 'Vom Himmel blicket Jahwe herab, / Er sieht alle Menschenkinder.',
        14: 'Von seiner Wohnstatt schauet er / Auf alle Bewohner der Erde.',
        15: 'Er bildet allen ihr Herz, / Er achtet auf all ihr Tun.',
        16: 'Nicht siegt ein König durch große Macht, / Nicht rettet ein Held sich durch große Kraft.',
        17: 'Nichts nützen Rosse zum Siege, / Ihre große Stärke hilft nicht entrinnen.',
        18: 'Auf die, die ihn fürchten, blickt Jahwes Auge, / Auf die, die harren auf seine Huld,',
        19: 'Daß er ihr Leben vom Tode errette / Und sie erhalte in Hungersnot.',
        20: 'Unsre Seele wartet auf Jahwe, / Er ist uns Hilfe und Schild.',
        21: 'Ja, in ihm freuet sich unser Herz. / Seinem heiligen Namen vertrauen wir.',
        22: 'Deine Gnade, Jahwe, sei über uns, / Gleichwie wir auf dich harren!',
    },
    34: {
        1: 'Von David, als er sich vor Abimelech wahnsinnig stellte, / so daß dieser ihn von sich trieb und er wegging.',
        2: 'Allzeit will ich Jahwe preisen, / Sein Lob sei stets in meinem Mund.',
        3: 'Bei Jahwe soll mein Herz sich rühmen, / Daß Dulder es hören und sich freun.',
        4: 'Groß achtet mit mir Jahwe, / Laßt uns zusammen seinen Namen erhöhn!',
        5: 'Dringend suchte ich Jahwe, er gab mir Antwort: / Aus all meinen Ängsten befreite er mich.',
        6: 'Hell leuchtet das Aug, wenn man auf ihn blickt, / Und das Antlitz wird nicht erblassen.',
        7: 'Solch ein Dulder ist hier: der rief — / da erhörte ihn Jahwe / Und half ihm aus all seinen Nöten.',
        8: 'Ganz nah ist Jahwes Engel den Frommen allen / Und reißt sie aus jeder Gefahr.',
        9: 'Tastet und seht: wie gütig ist Jahwe! / Heil dem Manne, der zu ihm flieht!',
        10: 'Jahwe fürchtet, ihr Heiligen sein! / Denn die ihn fürchten, die trifft kein Mangel.',
        11: 'Karg leben und hungern wohl junge Leun; / Die aber Jahwe suchen, entbehren kein Gut.',
        12: 'Liebe Kinder, kommet, höret mir zu! / Jahwe zu fürchten, will ich euch lehren.',
        13: 'Möchtest du haben langdauerndes Leben, / Zahlreiche Tage, um Glück zu schaun?',
        14: 'Nun, dann bewahr deine Zunge vor Bösem / Und deine Lippen vor falschem Wort.',
        15: 'Sei fern vom Bösen und tue das Gute, / Suche Frieden und jage ihm nach!',
        16: 'Auf Gerechte schauen die Augen Jahwes, / Und seine Ohren hören ihr Schrein.',
        17: 'Pein bringt den Frevlern der Zornblick Jahwes: / Von der Erde vertilget er ihr Gedächtnis.',
        18: 'Zagend schreien die Frommen, und Jahwe hört: / Aus all ihren Leiden rettet er sie.',
        19: 'Kommt Jahwe denen nicht nah, / die zerbrochenen Herzens sind? / Und allen hilft er, deren Geist zerschlagen ist.',
        20: 'Reichlich muß der Gerechte leiden, / Aber aus allem befreit ihn Jahwe.',
        21: 'Schützend bewahrt er all seine Gebeine, / Daß ihrer nicht eins zerbrochen wird.',
        22: 'Töten wird den Frevler das Unheil, / Büßen müssen die Hasser des Frommen. Jahwe erlöst seiner Knechte Seele, / Und schuldlos bleiben, die zu ihm flehn.',
    },
    35: {
        1: 'Von David. / Bestreite, Jahwe, meine Bestreiter, / Bekriege, die mich bekriegen!',
        2: 'Ergreife Schild und Tartsche, / Steh auf, um mir zu helfen!',
        3: 'Zücke den Speer und die Axt wider meine Verfolger, / Sprich zu meiner Seele: "Ich helfe dir!"',
        4: 'Schande und Schmach mögen ernten, / Die mir nach dem Leben trachten; / Zurückweichen und erröten müssen, / Die auf mein Unglück sinnen!',
        5: 'Sie seien wie Spreu vor dem Winde, / Und Jahwes Engel stoße sie weg!',
        6: 'Ihr Weg sei finster und schlüpfrig, / Und Jahwes Engel verfolge sie!',
        7: 'Denn sie haben ihr Netz mir ohn Ursach gelegt, / Ohn Ursach mir eine Grube gegraben.',
        8: "Verderben treffe ihn, eh er's meint, / Ihn fange das Netz, das er heimlich gestellt! / Er falle hinein und verderbe!",
        9: 'Dann wird meine Seele in Jahwe sich freun, / Ob seiner Hilfe frohlocken.',
        10: 'Es sagen all meine Gebeine: "Wer gleicht dir, o Jahwe? / Du rettest den Armen aus des Stärkern Hand, / Den Armen und Dürftigen von seinem Räuber."',
        11: 'Falsche Zeugen erheben sich, / Sie fragen nach Dingen, die ich nicht weiß;',
        12: 'Sie vergelten mir Böses für Gutes. / Wie bin ich allein und verlassen!',
        13: 'Ich aber, waren sie krank, trug Trauerkleider, / Machte mich müde mit Fasten / Und betete gesenkten Haupts.',
        14: 'Als wär er mein Freund, mein Bruder, so (leidvoll) ging ich einher; / Wie um meine Mutter trauernd, so war ich gebeugt von Schmerz.',
        15: 'Nun aber bei meinem Sturze freuen sie sich und treten zusammen, / Es rotten sich wider mich Wichte, die ich nicht kannte; / Sie lästern und hören damit nicht auf.',
        16: 'Wie Ruchlose Possenreißer / Fletschen sie wider mich ihre Zähne.',
        17: 'O Herr, wie lange noch willst du es ansehn? / Schütze mein Leben vor ihrem Verderben, / Entreiß meine Seele den jungen Löwen!',
        18: 'Ich will dich preisen in großer Gemeinde, / Unter zahlreichem Volke dich rühmen.',
        19: 'Laß sich nicht über mich freun, die mir grundlos feind sind, / Laß nicht, die mich ohn Ursach hassen, mein hämisch spotten!',
        20: 'Denn sie reden nicht, was zum Frieden dient, / Nein, gegen die Stillen im Lande ersinnen sie Trug.',
        21: 'Sie reißen den Mund weit auf wider mich, / Sie rufen: "Ei, ei, nun sehen wir\'s ja!"',
        22: 'Du siehst es, Jahwe, drum schweige nicht! / O Herr, sei nicht ferne von mir!',
        23: 'Wach auf, wach auf und schaffe mir Recht! / Mein Gott, mein Herr, tritt du für mich ein!',
        24: 'Schaff Recht mir nach deiner Gerechtigkeit, o Jahwe, mein Gott! / Sie sollen ja nicht über mich frohlocken.',
        25: 'Sie sollen nicht denken: "Ei, nun ist\'s erreicht!" / Nicht glauben: "Jetzt haben wir ihn vernichtet."',
        26: 'Beschämt und enttäuscht müssen alle werden, / Die sich meines Unglücks freun. / Es müssen sich hüllen in Schande und Schmach, / Die sich stolz wider mich erheben.',
        27: 'Laß jubeln und jauchzen, die mir gönnen mein Recht! / Laß sie allzeit sprechen: "Jahwe ist groß, / Der das Heil seines Knechtes begehret!"',
        28: 'Meine Zunge soll deine Gerechtigkeit preisen, / Fort und fort deinen Ruhm verkünden.',
    },
    36: {
        1: 'Dem Sangmeister. Von dem Knechte Jahwes, von David.',
        2: 'Wie die Sünde zum Frevler redet, / daran muß ich denken in meinem Herzen. / Es fehlt ihm ja alle Scheu vor Gott.',
        3: 'Denn sie umgarnt ihn mit Schmeichelreden, / Damit sie erreiche, daß er sich verschulde und hasse.',
        4: 'Was er spricht, ist Unheil und Tücke; / Er steht davon ab, verständig zu handeln und gut.',
        5: 'Unheil sinnt er auf seinem Lager, / Betritt einen bösen Weg, / Schlechtes verwirft er nicht.',
        6: 'Jahwe, bis an den Himmel reicht deine Gnade, / Deine Treue bis zu den Wolken.',
        7: 'Deine Gerechtigkeit gleicht Gottes Bergen, / Deine Gerichte der Meerestiefe; / Menschen und Tieren hilfst du, o Jahwe.',
        8: 'Wie köstlich, Elohim, ist deine Gnade! / Die Menschen dürfen sich bergen in deiner Fittiche Schatten.',
        9: 'Sie laben sich an deines Hauses Fülle, / Und mit dem Strom deiner Wonne tränkest du sie.',
        10: 'Denn bei dir ist die Quelle des Lebens, / In deinem Lichte schauen wir das Licht.',
        11: 'Erhalt deine Gnade denen, die dich erkennen, / Und deine Gerechtigkeit den redlichen Herzen!',
        12: 'Nicht treffe mich der Hoffart Fuß, / Und der Frevler Hand verscheuche mich nicht! Dann fallen die Übeltäter, / Sie stürzen und kommen nicht wieder empor.',
    },
    37: {
        1: 'Von David. / Arge laß nicht zum Eifer dich reizen, / Alle die Frevler beneide nicht!',
        2: 'Denn wie Gras verschwinden sie eilend / Und verwelken wie grünes Kraut.',
        3: 'Baue auf Jahwe und handle gut, / Bleibe im Lande und pflege Treue!',
        4: 'So wirst du Wonne an Jahwe haben, / Der dir gewährt deines Herzens Wunsch.',
        5: "Gründe auf Jahwe dein Lebenslos, / Traue auf ihn, denn er macht's wohl!",
        6: 'Er läßt deine Unschuld wie Morgenlicht leuchten / Und dein Recht wie die Mittagshelle.',
        7: 'Duldergleich sei stille zu Jahwe und harre sein! / Entrüste dich nicht über den, der Glück hat, / Über den Mann, der Ränke verübt!',
        8: 'Halt dich vom Zorne zurück, laß fahren den Grimm! / Erhitze dich nicht, es führt nur zum Bösen!',
        9: 'Denn Frevler werden ausgerottet; / Die aber Jahwes harren, die erben das Land.',
        10: 'Wartest du nur ein Weilchen, so ist der Frevler nicht mehr. / Nach seiner Stätte siehst du dich um: er ist dahin!',
        11: 'Die Dulder werden das Land ererben / Und sich erfreuen der Fülle des Heils.',
        12: 'Saat des Unheils sinnet der Böse, / Fletscht seine Zähne gegen den Frommen.',
        13: 'Doch Adonái lachet sein, / Denn er siehet: es kommt sein Tag.',
        14: 'Gottlose zücken das Schwert und spannen den Bogen, / Um den Armen und Dürftigen zu fällen, / Um hinzumorden, die redlich wandeln.',
        15: 'Doch ihnen ins Herz wird dringen ihr Schwert, / Und ihre Bogen werden zerbrochen.',
        16: "Trägt der Gerechte auch wenig davon, / Besser ist's immer als vieler Frevler Güterfülle.",
        17: 'Denn der Frevler Arm wird zerbrochen, / Aber die Frommen stützt Jahwe.',
        18: 'Jahwe kennt der Redlichen Tage, / Und ihr Besitz wird ewig bestehn.',
        19: 'Nicht leiden sie Mangel in böser Zeit, / In den Tagen des Hungers werden sie satt.',
        20: 'Kläglich kommen die Frevler um; / Wie der Auen Pracht sind Jahwes Feinde: / Sie schwinden dahin wie der Rauch, sie schwinden.',
        21: 'Lehnt der Frevler, so zahlt er nicht, / Der Gerechte aber tut wohl und gibt.',
        22: 'Denn seine Gesegneten erben das Land, / Doch seine Verfluchten werden zunichte.',
        23: 'Menschen tun feste Schritte mit Jahwes Hilfe, / Wenn ihr Wandel ihm wohlgefällt.',
        24: 'Mögen sie wanken — sie stürzen nicht, / Denn Jahwe stützt ihre Hände.',
        25: 'Nie hab ich als Knabe noch später im Alter / Den Frommen verlassen gesehn / Und seine Kinder betteln um Brot.',
        26: 'Allezeit tut er wohl und leihet, / Und seine Nachkommen werden zum Segen.',
        27: 'Sei fern vom Bösen und tue das Gute, / So wirst du immerdar wohnen bleiben.',
        28: 'Jahwe liebt ja das Recht / Und verläßt seine Frommen nicht; er schützt sie auf immer. / Doch der Frevler Geschlecht wird ausgerottet.',
        29: 'Die Gerechten erben das Land / Und wohnen darin auf ewig.',
        30: 'Preis der Weisheit verkündet der Fromme, / Und seine Zunge redet, was recht.',
        31: 'Seines Gottes Gesetz ruht ihm im Herzen, / Und seine Schritte wanken nicht.',
        32: 'Zu verderben den Frommen, lauert der Frevler: / Er sucht ihn zu töten.',
        33: 'Doch Jahwe gibt ihn seiner Hand nicht preis, / Er spricht ihn nicht schuldig, wenn Menschen ihn richten.',
        34: 'Klammre dich an Jahwe, halt ein seinen Weg: / Er wird dich erhöhn, daß du erbest das Land. / Der Frevler Vernichtung siehst du mit an.',
        35: 'Reckenhaft kühn sah ich einen Frevler; / Er spreizte sich stolz wie ein grünender Baum.',
        36: 'Man ging vorüber: er war nicht mehr. / Als ich ihn suchte — er fand sich nicht.',
        37: 'Schau auf den Frommen, sieh den Redlichen an: / Nachkommen empfängt der Friedensmann.',
        38: 'Die Frevler jedoch werden alle vertilgt, / Der Bösen Geschlecht wird ausgerottet.',
        39: 'Treu schirmt Jahwe die Gerechten; / Er ist ihre Schutzwehr zur Zeit der Not.',
        40: 'Es hilft ihnen Jahwe und rettet sie; / Er rettet sie von den Frevlern und steht ihnen bei; / Denn sie trauen auf ihn.',
    },
    38: {
        1: 'Ein Psalm Davids. Zum Bekennen (der Sünde) (?).',
        2: 'Jahwe, strafe mich nicht in deinem Zorn / Und züchtige mich nicht in deinem Grimm!',
        3: 'Denn deine Pfeile haben mich getroffen, / Und deine Hand liegt schwer auf mir.',
        4: 'Nichts Gesundes ist an meinem Leib ob deines Grolls, / Nichts Heiles in meinem Gebein ob meiner Sünde.',
        5: 'Denn meine Schuld geht über mein Haupt, / Wie schwere Last ist sie mir zu schwer.',
        6: 'Es stinken, es eitern meine Wunden / Um meiner Torheit willen.',
        7: 'Ich bin gekrümmt, bin sehr gebeugt, / Den ganzen Tag geh ich traurig einher.',
        8: 'Denn meine Lenden sind voll Brand, / Nichts Heiles ist an meinem Leib.',
        9: 'Ohnmächtig bin ich, ganz zerschlagen, / Ich schrei vor dem Schmerz, der in mir tobt.',
        10: 'O Herr, du kennst all mein Verlangen, / Mein Seufzen ist dir nicht verborgen.',
        11: 'Mein Herz pocht laut, meine Kraft ist weg, / Und das Licht meiner Augen, auch das ist dahin!',
        12: 'Meine Lieben und Freunde stehn fern meiner Pein, / Weit weg treten meine Verwandten.',
        13: 'Es legen Schlingen, die mir nach dem Leben trachten; / Die mein Unglück wünschen, beschließen Verderben / Und haben allzeit Tücke im Sinn.',
        14: 'Ich aber höre es nicht, als wäre ich taub, / Ich bin wie ein Stummer, der seinen Mund nicht öffnet.',
        15: 'Ich bin wie ein Mann, der nicht hören kann, / In dessen Mund keine Widerrede.',
        16: 'Denn auf dich, o Jahwe, harr ich, / Du wirst mich erhören, o Herr, mein Gott.',
        17: 'Denn ich spreche: "Laß sie mein sich nicht freun, / Wenn mein Fuß wankt, nicht wider mich großtun."',
        18: 'Ich bin ja nahe dem Fallen, / Und mein Kummer verläßt mich nie.',
        19: 'Denn meine Missetat mache ich kund, / Ich härme mich ob meiner Sünde.',
        20: 'Meine Feinde aber strotzen von Lebenskraft, / Und zahlreich sind, die mich grundlos hassen.',
        21: 'Sie vergelten mir Gutes mit Bösem, / Sie feinden mich an, weil ich Gutes erstrebe.',
        22: 'Verlaß mich nicht, o Jahwe! / Mein Gott, sei nicht ferne von mir! Eile, mir beizustehn, / Herr, meine Hilfe!',
    },
    39: {
        1: 'Dem Sangmeister, nämlich Jedutun. Ein Psalm Davids.',
        2: 'Ich sprach: "Ich will meinen Wandel hüten, / Daß ich nicht sündige mit meiner Zunge. / Ich will meinem Mund einen Zaum anlegen, / Solange der Frevler vor mir ist."',
        3: 'Ich verstummte in stiller Ergebung; / Ich schwieg, obwohl alles Glückes bar. / Doch es wühlte mein Schmerz in mir.',
        4: 'Es glühte mein Herz in meiner Brust, / Ein inneres Feuer verzehrte mich, / Da mußte ich reden mit meiner Zunge:',
        5: '"Tu mir, Jahwe, mein Ende kund, / Und wie lang meine Tage währen, / Daß ich seh, wie vergänglich ich bin.',
        6: 'Nur handbreit machtest du meine Tage, / Meine Lebenszeit ist wie nichts vor dir. / Ein Hauch nur ist jeder Mensch, wie fest er auch steht! / Sela.',
        7: 'Als Schattenbild nur wandelt der Mensch. / Um ein Nichts erregt er sich wild: / Er sammelt und weiß nicht, wer es errafft."',
        8: 'Nun, Herr, wes soll ich denn harren? / Ich hoffe allein auf dich!',
        9: 'Von meinen Sünden errette mich, / Zum Spott des Gottlosen mache mich nicht!',
        10: 'Ich schweige, tue den Mund nicht auf; / Denn du, du hast es getan.',
        11: 'Nimm deine Plage weg von mir! / Deiner mächtigen Hand erliege ich.',
        12: 'Du züchtigst den Menschen, du strafst ihn ob seiner Schuld, / Daß seine Schönheit zergeht wie ein mottenfräßiges Kleid. Ein Hauch nur ist jeder Mensch! Sela.',
        13: 'Höre, o Jahwe, mein Gebet, vernimm mein Flehn! / Zu meinen Tränen schweige nicht! / Denn ein Gast nur bin ich bei dir, / Ein Pilgrim wie all meine Väter. Schau weg von mir, daß ich fröhlich werde, / Eh ich hinfahre und nicht mehr bin.',
    },
    40: {
        1: 'Dem Sangmeister. Ein Psalm Davids.',
        2: 'Voll Sehnsucht hab ich auf Jahwe geharrt: / Er neigte sich zu mir und hörte mein Schrein.',
        3: 'Er zog mich aus der verderblichen Grube, / Aus tiefem Schlamm / Und stellte meine Füße auf einen Fels, / Machte meine Schritte sicher.',
        4: "Er legte mir ein neues Lied in den Mund, / Einen Lobgesang für unsern Gott. / Viele schauen's und schauern / Und trauen auf Jahwe.",
        5: '"Heil dem, der sein Vertrauen auf Jahwe setzt / Und sich nicht wendet zu Stolzen und Lügenhaften!"',
        6: 'Viel hast du getan, o Jahwe, mein Gott, / An Wundern und Plänen zu unserm Heil / Dir ist nichts gleich! / Ich möchte sie kundtun, davon reden, / Aber sie sind unzählbar.',
        7: 'Schlachtopfer und Speisopfer willst du nicht, / Doch Ohren hast du mir gegraben. / Brandopfer und Sündopfer forderst du nicht.',
        8: 'Da sprach ich: "Sieh, ich komme / Mit der Rolle des Buchs, mir zur Weisung geschrieben.',
        9: 'Deinen Willen zu tun, mein Gott, begehr ich, / In meinem Herzen ist dein Gesetz."',
        10: 'Die Freudenbotschaft deines Heils verkünd ich in großer Gemeinde. / Sieh, meine Lippen verschließ ich nicht: / Jahwe, du weißt es.',
        11: 'Deine Gerechtigkeit verberg ich nicht in meinem Herzen, / Von deiner Wahrhaftigkeit und Hilfe rede ich, / Deine Huld und Treue verhehl ich nicht in der großen Gemeinde.',
        12: 'Du, Jahwe, wirst dein Erbarmen mir nicht entziehn, / Deine Huld und Treue werden mich allzeit schirmen.',
        13: 'Denn es umringen mich Leiden ohne Zahl, / Meine Sünden erfassen mich unübersehbar, / Zahlreicher als meines Hauptes Haar, / Und mein Mut entfällt mir.',
        14: 'Willige, Jahwe, mich zu retten, / Eile mir, Jahwe, zu Hilfe!',
        15: 'Beschämt und enttäuscht laß alle werden, / Die mir nach dem Leben trachten, es wegzuraffen! / Mit Schimpf laß alle entweichen, / Die da mein Unglück wollen!',
        16: 'Erstarren mögen ob ihrer Schande, / Die (schadenfroh) über mich rufen: "Ha, ha!"',
        17: 'Frohlocken laß aber und dein sich freun / Alle, die nach dir fragen. / Laß immerdar rufen: "Groß ist Jahwe!" / Alle, die dein Heil lieben! Bin ich auch elend und arm: / Adonái sorget für mich. / Mein Beistand und Retter bist du. / Mein Gott, verzieh deine Hilfe nicht!',
    },
    41: {
        1: 'Dem Sangmeister. Ein Psalm Davids.',
        2: 'Heil dem, der des Armen sich annimmt, / Am Tage des Unglücks wird Jahwe ihn retten.',
        3: 'Jahwe schirmt ihn, erhält ihn am Leben, / Daß man im Lande ihn glücklich preist. / Nicht gibst du ihn hin seiner Feinde Wut.',
        4: 'Jahwe wird ihn auf dem Siechbett stützen; / Seine Krankheit wandelst du zur Genesung.',
        5: 'Ich spreche: "Jahwe, sei mir gnädig, / Heile mich: ich habe gesündigt an dir!"',
        6: 'Meine Feinde wünschen mir Böses an: / "Wann stirbt er? Wann wird sein Name vergehn?"',
        7: 'Besucht mich einer, so redet er Lüge. / Sein Herz sammelt Bosheit an; / Dann geht er hinaus und macht es kund.',
        8: 'All meine Hasser zischeln gemeinsam wider mich, / Sie sinnen Unheil gegen mich aus:',
        9: '"Verderben ist über ihn ausgegossen; / Er hat sich gelegt, steht nicht wieder auf."',
        10: 'Selbst mein Freund, auf den ich vertraute, mein Tischgenosse / Hebt nun seine Ferse gegen mich.',
        11: 'Du aber, Jahwe, sei mir gnädig und richte mich auf, / Damit ich es ihnen vergelte!',
        12: 'So erkenne ich dann, daß du mich liebst, / Wenn mein Feind nicht über mich jubeln darf.',
        13: 'Mich aber hältst du aufrecht ob meiner Unschuld / Und stellst mich vor dein Antlitz auf ewig. Gepriesen sei Jahwe, Israels Gott, / Von Ewigkeit zu Ewigkeit! / Amen, Amen.',
    },
    42: {
        1: 'Dem Sangmeister. Eine Betrachtung(?) der Söhne Korahs.',
        2: 'Wie eine Hindin lechzt nach Wasserbächen, / So lechzt meine Seele, Elohim, nach dir.',
        3: 'Meine Seele dürstet nach Elohim, dem lebendigen Gott. / Wann werd ich kommen und vor Elohim erscheinen?',
        4: 'Meine Tränen sind meine Speise Tag und Nacht, / Weil man mich immer höhnisch fragt: / "Wo ist denn nun dein Gott?"',
        5: 'Voll Wehmut denk ich jetzt daran, / Wie ich einst wallte mit des Volkes Menge, / Wie ich sie leitete zum Hause Elohims: / Die Festversammlung, die laut jubelte und dankte.',
        6: 'Was bist du, meine Seele, denn so tief betrübt? / Was bist du so erregt in mir? / Harr nur auf Elohim! denn noch werd ich ihm danken: / Er ist ja meine Hilfe.',
        7: 'Mein Gott, in mir ist meine Seele tief betrübt. / Drum denk ich dein im Land des Jordans / und der Hermongipfel bei dem Mizarberge.',
        8: 'Eine Flut ruft der andern zu beim Rauschen der Wasserfälle. / All deine Wellen und Wogen fahren über mich!',
        9: 'Es schenkte mir Jahwe tagsüber seine Gnade, / Und in der Nachtzeit sang ich ihm mein Lied, / Ich betete zum Gott meines Lebens.',
        10: 'So sprech ich nun zu Gott, der mir ein Fels: / Warum hast du denn mein vergessen? / Warum soll ich betrübt einhergehen, / Wenn der Feind mich drängt?"',
        11: 'Es trifft mich wie ein Mordstoß, / wenn mich meine Dränger schmähen, / Wenn sie mich täglich höhnisch fragen: / "Wo ist nun dein Gott?" Was bist du, meine Seele, denn so tief betrübt? / Was bist du so erregt in mir? / Harr nur auf Elohim; denn noch werd ich ihm danken: / Er ist ja meine Hilfe und mein Gott.',
    },
    43: {
        1: 'Schaffe mir Recht, Elohim, und führe meine Sache gegen ein lieblos Volk, / Von falschen, frevelhaften Leuten rette mich!',
        2: 'Du bist ja Gott, mein Hort. Warum verwirfst du mich? / Warum soll ich betrübt einhergehn, / Wenn der Feind mich drängt?',
        3: 'O sende dein Licht und deine Wahrheit! Die sollen mich leiten / Und mich bringen zu deinem heilgen Berge und deinem Zelt.',
        4: 'Dann will ich eingehn zum Altar Elohims, zum Gott meiner Jubelfreude / Und auf der Zither dich preisen, Elohim, mein Gott.',
        5: 'Was bist du, meine Seele, denn so tief betrübt? / Was bist du so erregt in mir? / Harr nur auf Elohim; denn noch werd ich ihm danken: / Er ist ja meine Hilfe und mein Gott.',
    },
    44: {
        1: 'Dem Sangmeister. Eine Betrachtung (?) der Söhne Korahs.',
        2: 'Elohim, mit unsern Ohren haben wir gehört, / Unsre Väter haben uns erzählt, / Was du in ihren Tagen getan, / In den Tagen der Vorzeit:',
        3: 'Du hast mit deiner Hand die Heiden vertrieben und sie gepflanzt; / Du hast Völker zerschlagen, sie ausgebreitet.',
        4: 'Denn nicht durch ihr Schwert ward ihnen das Land, / Und nicht ihr Arm half ihnen zum Sieg, / Nein, deine Rechte, dein Arm, das Licht deines Angesichts. / Denn du hattest sie lieb.',
        5: 'Du, Elohim, du bist mein König, / Entbiete Hilfe für Jakob.',
        6: 'Mit dir zerstoßen wir unsre Dränger, / Zertreten die Feinde in deinem Namen.',
        7: 'Denn nicht vertrau ich auf meinen Bogen, / Mein Schwert verschafft mir nicht Hilfe.',
        8: 'Nein, du hilfst uns von unsern Drängern, / Und unsre Hasser verstörest du.',
        9: 'Allzeit rühmen wir uns Elohims, / Deinen Namen preisen wir ewig. Sela.',
        10: 'Und doch verwirfst du uns, bringst uns in Schmach, / Ziehst nicht mehr aus mit unsern Heeren.',
        11: 'Du lässest uns fliehn vor unserm Feind, / Und unsre Hasser plündern uns aus.',
        12: 'Du lässest uns wie Schafe verschlingen, / Und unter die Heiden zerstreuest du uns.',
        13: 'Um ein Spottgeld verkaufst du dein Volk / Und forderst für sie nicht hohen Preis.',
        14: 'Unsern Nachbarn machest du uns zur Schmach, / Zum Hohn und Gelächter ringsumher.',
        15: 'Du machst uns zum Spottlied unter den Heiden, / Und die Völker schütteln den Kopf über uns.',
        16: 'Allzeit denk ich an meine Schmach, / Und Scham bedeckt mein Angesicht,',
        17: 'Weil ich die Schmäher und Lästerer hören, / Die Feinde und Rachgierigen sehen muß.',
        18: 'All dies hat uns getroffen, obwohl wir dein nicht vergessen / Noch deinen Bund gebrochen haben.',
        19: 'Es ist unser Herz nicht abgefallen, / Unser Schritt nicht gewichen von deinem Pfad,',
        20: 'Daß du uns (nun zur Strafe) zerschlägst an der Schakalstätte / Und uns umhüllest mit Todesschatten.',
        21: 'Hätten wir des Namens unsers Gottes vergessen, / Unsre Hände gebreitet zum fremden Gott:',
        22: 'Würde Elohim das nicht durchschaun? / Er kennt ja des Herzens Geheimnis.',
        23: 'Nein, deinetwegen werden wir täglich gemordet, / Wie Schafe der Schlachtbank achtet man uns.',
        24: 'Wach auf! Warum schläfst du, Herr? / Erwache, verwirf nicht auf immer!',
        25: 'Warum verbirgst du dein Angesicht, / Denkst nicht unsers Elends und Druckes?',
        26: 'Denn in den Staub gebeugt ist unsre Seele, / Es klebt unser Leib am Boden. Auf! Hilf uns! / Errett uns um deiner Gnade willen!',
    },
    45: {
        1: 'Dem Sangmeister, nach (der Weise von:) "Lilien". Von den Söhnen Korahs. Eine Betrachtung(?). Ein liebliches Lied.',
        2: 'Es wallet mein Herz von lieblicher Rede. / Ich spreche: "Einem Könige gilt mein Lied!" / Meine Zunge gleicht eines Schnellschreibers Griffel.',
        3: 'Du bist der Schönste der Menschensöhne, / Anmut wohnet auf deinen Lippen. / Drum hat Elohim dich auf ewig gesegnet.',
        4: 'Gürte dein Schwert um die Hüfte, du Held, / Dazu deinen Glanz und Schmuck!',
        5: 'Ja, deinen Schmuck! Fahr siegreich einher / Zum Schutze der Wahrheit und leidenden Unschuld: / So läßt deine Rechte dich Wunder schaun.',
        6: 'Deine Pfeile sind scharf — Völker fallen vor dir zu Boden —, / Sie dringen den Feinden des Königs ins Herz.',
        7: 'Dein Thron, Elohim, währt immer und ewig, / Dein Königszepter, es ist gerecht.',
        8: 'Du liebest das Recht und hassest den Frevel; / Drum hat Elohim, dein Gott, dich gesalbt / Mit Freudenöl vor deinen Genossen.',
        9: 'Myrrhe, Aloe und Kassia sind alle deine Kleider; / Aus Elfenbeinpalästen erfreut dich Saitenspiel.',
        10: 'In deinem Prachtzug sind Königstöchter. / Die Gattin steht dir zur Rechten in Ofirgold.',
        11: 'Höre, Tochter, sieh her und neige dein Ohr! / Vergiß dein Volk und dein Vaterhaus!',
        12: 'Und begehrt deiner Schönheit der König / — Er ist ja der Herr —, so huldige ihm!',
        13: 'Du Tochter aus Tyrus, die Reichsten im Volk / Werden dir schmeicheln mit ihren Geschenken.',
        14: 'Ganz Pracht ist die Königstochter in ihrem Gemach, / Mit Gold durchwirkt ist ihr Gewand.',
        15: 'In bunten Kleidern wird sie zum König geleitet. / Ihr folgen Jungfraun, die ihr befreundet — / Sie werden dir zugebracht.',
        16: 'Man führt sie herbei mit Jubel und Jauchzen, / Sie ziehen ein in des Königs Palast.',
        17: 'An deiner Väter Statt werden deine Söhne treten; / Die wirst du zu Fürsten setzen im ganzen Land. Deines Namens will ich gedenken in jedem Geschlecht. / Drum werden dich Völker preisen immer und ewig.',
    },
    46: {
        1: 'Dem Sangmeister. Von den Söhnen Korahs. Ein Lied von Alamot.',
        2: 'Elohim ist uns Zuflucht und Schutz, / Ein Beistand in Nöten, reichlich bewährt.',
        3: 'Drum fürchten wir nichts, ob auch wanket die Erde, / Ob Berge stürzen mitten ins Meer,',
        4: 'Ob seine Wasser tosen und schäumen, / Von seinem Brausen die Berge erbeben. Sela.',
        5: 'Ein Strom ist da: seine Bäche erfreun die Stadt Elohims, / Des Höchsten heilige Wohnung.',
        6: 'Elohim weilt dort, sie wanket nicht / Elohim hilft ihr, wenn der Morgen naht.',
        7: 'Es toben Völker, es wanken Reiche. / Erschallt sein Donner, so zittert die Erde.',
        8: 'Jahwe der Heerscharen ist mit uns, / Unsre Burg ist der Gott Jakobs. Sela.',
        9: 'Kommt, schauet die Taten Jahwes: / Er flößt der Erde Entsetzen ein.',
        10: 'Er steuert dem Krieg bis ans Ende der Welt, / Zerbricht den Bogen, zerschlägt den Spieß, / Verbrennt die Wagen mit Feuer.',
        11: '"Laßt ab und erkennt: ich bin Elohim, / Groß unter den Völkern und groß auf Erden." Jahwe der Heerscharen ist mit uns, / Unsre Burg ist der Gott Jakobs. Sela.',
    },
    47: {
        1: 'Dem Sangmeister. Ein Psalm der Söhne Korahs.',
        2: 'Ihr Völker alle, klatscht in die Hände, / Jauchzt Elohim mit Jubelschall!',
        3: 'Denn Jahwe ist hoch, ist furchtbar, / Ein großer König in aller Welt.',
        4: 'Er beugte Völker unter uns / Und legte uns Leute zu Füßen.',
        5: 'Er wählte uns unser Erbe aus, / Die Herrlichkeit Jakobs, den er liebt. Sela.',
        6: 'Elohim steigt unter Jauchzen empor, / Jahwe beim Klange des Widderhorns.',
        7: 'Lobsingt Elohim, lobsinget! / Lobsingt unserm König, lobsinget!',
        8: 'Denn aller Welt König ist Elohim. / Singt ihm ein Huldigungslied!',
        9: 'Königlich herrscht Elohim über Völker, / Elohim sitzt auf seinem heiligen Thron. Der Völker Fürsten versammeln sich / Als Volk des Gottes Abrahams. / Denn der Erde Schilde sind Elohims. / Er ist gewaltig erhaben!',
    },
    48: {
        1: 'Ein Lied. Ein Psalm der Söhne Korahs.',
        2: 'Groß ist Jahwe und hoch zu preisen / In unsers Gottes Stadt, auf seinem heiligen Berge.',
        3: 'Lieblich erhebt sich der Zionsberg, die Wonne der ganzen Erde. / Ein Gottessitz ist da des großen Königs Stadt.',
        4: 'An ihren Palästen hat Elohim / Als sichre Schutzwehr sich kundgetan.',
        5: 'Denn sieh, die Könige fanden sich ein, / Sie zogen verbündet heran.',
        6: 'Doch als sie schauten, da staunten sie. / Sie wurden bestürzt und flohen voll Angst.',
        7: 'Beben ergriff sie daselbst, / Zittern gleich einer Gebärerin.',
        8: 'Wie Tarsisschiffe der Oststurm zerschellt, / (So wurden die Feinde vernichtet).',
        9: "Was wir gehört, wir haben's nun selbst / In Jahwes Heerscharen Stadt erlebt, / In unsers Gottes Stadt: / Elohim erhält sie auf ewig! Sela.",
        10: 'Wir haben, Elohim, deiner Gnade geharrt / Inmitten deines Tempels.',
        11: 'Wie dein Name, Elohim, so reicht auch dein Ruhm / Bis an die Enden der Erde. / Deine Rechte ist voller Gerechtigkeit.',
        12: 'So freuet sich denn der Zionsberg, / Laut jubeln die Töchter Judas / Um deiner Gerichte willen.',
        13: 'Geht rings um Zion, umwandelt es, / Zählt seine Türme!',
        14: 'Gebt acht auf seine Mauer, / Durchschreitet seine Paläste, / Damit ihr dem künftigen Geschlecht erzählt: "Dieser Gott ist unser Gott auf immer und ewig! / Er führt uns auch über den Tod hinaus."',
    },
    49: {
        1: 'Dem Sangmeister. Ein Psalm der Söhne Korahs.',
        2: 'Höret dies, all ihr Völker, / Merket auf, all ihr Bewohner der Welt,',
        3: 'Leutesöhne wie Herrensöhne, / Reich und arm miteinander!',
        4: 'Mein Mund soll Weisheit reden, / Meines Herzens Sinnen ist Einsicht.',
        5: 'Ich will mein Ohr einem Lehrspruch neigen, / Mein Rätsel erschließen bei Zitherklang.',
        6: 'Was soll ich mich fürchten in schlimmen Tagen, / Wenn mich meiner Feinde Frevel umringt?',
        7: 'Sie vertrauen auf ihr Vermögen, / Ihres großen Reichtums rühmen sie sich.',
        8: 'Und doch kann keiner den andern erlösen / Noch Gott ein Sühngeld für ihn zahlen.',
        9: 'Der Seele Sühngeld ist nicht zu erschwingen; / Es zu erlegen, bleibt ewig unmöglich.',
        10: 'So wird denn niemand für immer leben / noch dem Schicksal entgehn, die Gruft zu schaun.',
        11: 'Nein, der Reiche muß sehn: selbst Weise sterben, / Nicht minder als Toren und Narren vergehn. / Ihre Schätze müssen sie andern lassen.',
        12: 'Die Reichen, sie denken: ihre Häuser sind ewig, / Ihre Wohnungen währen für und für; / Drum nennen sie Länder mit ihrem Namen.',
        13: 'Doch wer in Reichtum prangt, bleibt nicht; / Er gleicht den Tieren, die man vertilgt.',
        14: 'So geht es den Leuten voll Selbstvertraun / Und allen, die ihnen Beifall zollen. Sela.',
        15: 'Wie Schafe sinken sie in die Gruft: sie weidet der Tod. / Doch ein Morgen kommt, wo die Frommen über sie herrschen. / Ihr Fels zerreißt ja das Totenreich: / Es bleibt ihre Wohnstatt nicht.',
        16: 'Fürwahr, Elohim wird meine Seele erlösen / Aus der Macht der Scheôl; denn er entrückt mich. Sela.',
        17: 'Fürchte dich nicht, wenn einer reich wird, / Wenn seines Hauses Glanz sich mehrt.',
        18: 'Denn beim Sterben nimmt er das alles nicht mit, / Nicht fährt ihm nach seine Herrlichkeit.',
        19: 'Wenn er sich im Leben auch glücklich preist, / Wenn man dich ob guter Tage auch rühmt —',
        20: 'Du gehest doch ein in der Väter Haus, / Die nimmer das Licht erblicken. Wer in Reichtum prangt und ist ohne Verstand, / Der gleicht den Tieren, die man vertilgt.',
    },
    50: {
        1: 'Ein Psalm Asafs. / El Elohim Jahwe: Er redet / Und ruft der Erde d vom Aufgang der Sonne bis zum Niedergang.',
        2: 'Aus Zion, der Schönheit Krone, / Strahlt Elohim hervor.',
        3: 'Unser Gott, er kommt und schweiget nicht. / Verzehrend Feuer geht vor ihm her, / Rings um ihn stürmt es gewaltig.',
        4: 'Er ruft die Himmel droben herbei. / Und die Erde, sein Volk zu richten:',
        5: '"Versammelt mir die Frommen, / Die den Bund mit mir im Opfer geschlossen!"',
        6: "Die Himmel künden seine Gerechtigkeit; / Denn Elohim — er ist's, der richtet! Sela.",
        7: '"Höre, mein Volk, o laß mich reden! / Israel, laß mich dich warnen! / Elohim, dein Gott, bin ich.',
        8: 'Nicht deiner Schlachtopfer wegen rüge ich dich — / Sind doch deine Brandopfer immer vor mir.',
        9: 'Nicht brauche ich Stiere aus deinem Hause / Noch Böcke aus deinen Hürden.',
        10: 'Denn mein ist alles Wild des Waldes, / Das viele Getier auf den Bergen.',
        11: 'Ich kenne jeden Vogel der Berge, / Und was auf den Feldern sich regt, ist mein.',
        12: "Sollte mich hungern, dir sagte ich's nicht. / Denn mein ist der Erdkreis und was ihn erfüllt.",
        13: 'Esse ich etwa der Stiere Fleisch / Und trink ich der Böcke Blut?',
        14: 'Opfere Elohim Dank / Und bezahle dem Höchsten deine Gelübde!',
        15: '"Rufe mich an am Tage der Not: / Dann will ich dich retten, daß du mich ehrest."',
        16: 'Aber zum Frevler spricht Elohim: / Wie? du zählst meine Satzungen auf / Und redest von meinem Bund?',
        17: 'Das wagst du und hasset doch Zucht / Und wirfst meine Worte hinter dich?',
        18: 'Siehst du einen Dieb, so gesellst du dich ihm, / Und mit Ehebrechern gehest du um.',
        19: 'Du lässest deinen Mund zum Bösen los, / Und deine Zunge spinnet Trug.',
        20: 'Mit andern verleumdest du deinen Bruder, / Deiner Mutter Sohn hängst du Schande an.',
        21: 'Das hast du getan, und ich schwieg dazu. / Da dachtest du denn: ich wäre wie du. / Aber ich will dich zur Rechenschaft ziehn, / Dir\'s unter die Augen stellen."',
        22: 'Merkt das wohl, die ihr Gottes vergeßt; / Sonst werd ich zerreißen, und niemand rettet.',
        23: 'Wer Dank opfert, der ehret mich recht, / Und er bahnet den Weg, / Auf dem ich ihm zeige das Heil Elohims.',
    },
    51: {
        1: 'Dem Sangmeister. Ein Psalm Davids.',
        2: 'Als der Prophet Nathan zu ihm kam, / nachdem er zu Batseba eingegangen war.',
        3: 'Sei mir gnädig, Elohim, nach deiner Huld, / In großer Erbarmung tilg meine Frevel!',
        4: 'Wasche mich völlig von meiner Schuld / Und von meiner Sünde mache mich rein!',
        5: 'Denn meine Frevel sind mir bewußt, / Und meine Sünde ist stets vor mir.',
        6: 'An dir allein habe ich gesündigt, / Und was dir mißfällt, hab ich verübt. / Denn du sollst recht behalten mit deinem Spruch, / Rein erscheinen mit deinem Urteil.',
        7: 'Ich bin ja in Schuld geboren, / In Sünde hat mich meine Mutter empfangen.',
        8: 'Doch da du Wahrheit im Herzen liebst, / So mach mir im Innern Weisheit kund!',
        9: 'Entsündige mich mit Ysop, so werd ich rein, / Wasche mich, so werd ich weißer als Schnee.',
        10: 'Sprich mir Wonne und Freude zu, / Daß deine Gebeine frohlocken, die du zerschlagen.',
        11: 'Verbirg dein Antlitz vor meinen Sünden, / Und all meine Frevel tilge aus!',
        12: 'Ein reines Herz schaff mir, Elohim, / Einen festen Geist erneure in mir!',
        13: 'Wirf mich nicht weg von deinem Antlitz, / Deinen Heiligen Geist nimm nicht von mir!',
        14: 'Erfreue mich wieder mit deinem Heil, / Mit willigem Geiste stütze mich!',
        15: 'Dann lehre ich Frevler deine Wege, / Und Sünder sollen sich zu dir kehren.',
        16: 'Von Blutschuld rette mich, Elohim, du Gott meines Heils! / So jauchzt meine Zunge ob deiner Gnade.',
        17: 'Adonái, tu mir die Lippen auf; / Dann wird mein Mund deinen Ruhm verkünden.',
        18: 'Schlachtopfer begehrst du ja nicht — sonst gäbe ich sie —; / Brandopfer gefallen dir nicht.',
        19: 'Elohims Schlachtopfer sind ein zerbrochener Geist. / Ein zerbrochen, zerschlagen Herz, Elohim, verschmähest du nicht! Tu wohl an Zion in deiner Gnade, / Baue die Mauern Jerusalems! Dann werden dir rechte Opfer gefallen: / Brandopfer, Ganzopfer, / Dann wird man Stiere opfern auf deinem Altar.',
    },
    52: {
        1: 'Dem Sangmeister. Eine Betrachtung (?) Davids.',
        2: 'Als der Edomiter Doeg kam und Saul meldete: "David hat sich ins Haus Ahimelechs begeben."',
        3: 'Was rühmst du dich der Bosheit, du Held?! / Gottes Gnade währt für und für.',
        4: 'Verderben sinnt seine Zunge / Gleich scharfem Messer, du Unheilstifter!',
        5: 'Böses liebst du mehr als Gutes, / Lüge redest du lieber als Wahrheit. Sela.',
        6: 'Du liebst nur verderbliche Reden, / Du Zunge voll Trug!',
        7: 'So wird denn auch Gott dich zertrümmern auf immer, / Er wird dich ergreifen, wegreißen aus deinem Gezelt, / Aus der Lebenden Land dich entwurzeln. Sela.',
        8: 'Die Gerechten werden das schauen und schauern, / Sie werden sein lachen und sprechen:',
        9: '"Seht doch den Mann! Er wählte sich nicht Elohim zum Schutz; / Auf des Reichtums Fülle verließ er sich, / Dünkte sich sicher in seinem Frevel." Ich aber bin wie ein grünender Ölbaum (gepflanzt) in Elohims Haus. / Ich traue der Gnade Elohims auf immer und ewig. Preisen will ich dich immerdar, weil du es vollbracht. / Harren will ich auf deinen Namen, / Denn er ist köstlich vor deinen Frommen.',
    },
    53: {
        1: 'Dem Sangmeister, nach Machalát. Eine Betrachtung (?) Davids.',
        2: 'Die Toren denken bei sich: "Es ist kein Gott." / Verderbt und abscheulich treiben sie Frevel; / Da ist keiner, der Gutes tut.',
        3: 'Elohim schaut vom Himmel herab auf die Menschenkinder, / Daß er sehe, ob jemand Einsicht habe / Und frage nach Gott.',
        4: 'Aber allesamt sind sie abgewichen, alle entartet; / Da ist keiner, der Gutes tut, / Auch nicht ein einziger.',
        5: '"Sind denn so unvernünftig die Übeltäter, / Die mein Volk verzehren, wie man Brot verzehrt, / Die nicht zu Elohim beten?"',
        6: 'Dann beben sie schaudernd, obwohl kein Grund zum Schaudern vorhanden ist. / Denn Elohim zerstreut deiner Feinde Gebeine. / Du machst sie zuschanden, denn Elohim hat sie verworfen. Ach, käme aus Zion für Israel Heil! / Wendet Elohim seines Volkes Los, / So wird Jakob sich freun und Israel jauchzen.',
    },
    54: {
        1: 'Dem Sangmeister, mit Saitenspielbegleitung. Eine Betrachtung (?) Davids.',
        2: 'Als die Sifiter gekommen waren und Saul gemeldet hatten: "David hält sich bei uns verborgen."',
        3: 'Elohim, hilf mir durch deinen Namen, / Durch seine Stärke schaffe mir Recht!',
        4: 'Elohim, höre doch mein Gebet, / Horch auf die Worte meines Mundes!',
        5: 'Denn Fremde erheben sich wider mich, / Und Grausame trachten mir nach dem Leben, / Sie haben Gott nicht vor Augen. Sela.',
        6: 'Wahrlich, mein Helfer ist Elohim, / Adonái ist meines Lebens Halt.',
        7: 'Das Böse muß fallen auf meine Feinde — / Nach deiner Treue vernichte sie! Dann bring ich dir freiwillige Opfer, / Deinem Namen, o Jahwe, dank ich, daß er so hold. Denn er hat mich errettet aus aller Not, / Und an meinen Feinden erfreut sich mein Auge.',
    },
    55: {
        1: 'Dem Sangmeister, mit Saitenspielbegleitung. Eine Betrachtung (?) Davids.',
        2: 'Vernimm, Elohim, mein Gebet, / Entzieh dich nicht meinem Flehn!',
        3: 'Horch auf mich und erhöre mich, / Ich sinne ruhlos und seufze.',
        4: 'Denn ich muß hören des Feindes Stimme und empfinde des Frevlers Druck. / Sie wälzen Unheil auf mich und stellen mir grimmig nach.',
        5: 'Mein Herz bebt mir in der Brust, / Und Schrecken des Todes fallen auf mich.',
        6: 'Furcht und Zittern dringt auf mich ein, / Entsetzen hat mich bedeckt.',
        7: 'Drum sag ich: "O, hätt ich doch Schwingen wie Tauben! / Weg wollt ich fliegen, einen Ruhplatz suchen.',
        8: 'Ja, weithin möcht ich flüchten / Und in der Wüste rasten. Sela.',
        9: 'Eine Freistatt würd ich mir suchen / Vor dem Toben des Sturms, vor dem Wetter.',
        10: 'Verwirr ihre Zungen, Adonái, zerteile sie! / Denn ich schaue Gewalttat und Streit in der Stadt.',
        11: 'Tag und Nacht gehn sie auf den Mauern umher, / Unheil und Elend ist drinnen.',
        12: 'Ja, Verderben ist drinnen; / Von ihrem Markte weicht nicht Bedrückung und Trug.',
        13: 'Denn nicht ein Feind schmäht mich: / Das würd ich ertragen; / Auch nicht mein Hasser tut groß wider mich: / Dann würd ich mich vor ihm verbergen.',
        14: "Nein, du bist's, den ich mir gleichgeschätzt, / Mein Freund und mein Vertrauter.",
        15: 'Wie pflegten wir traute Gemeinschaft, / Gingen einträchtig ins Haus Elohims!',
        16: 'Der Tod überrasche sie, / Mögen sie lebend zur Unterwelt fahren! / Denn in ihrer Wohnstatt, in ihrem Herzen ist Bosheit.',
        17: 'Ich aber rufe zu Elohim, / Und Jahwe wird mich erretten.',
        18: 'Des Abends, Morgens und Mittags klag ich und seufze: / So hört er mein Flehn.',
        19: 'Er wird mich erretten, in Frieden mich leiten, daß keiner mir beikommt; / Denn ihrer sind viele wider mich.',
        20: 'Gott wird hören und Antwort geben — / Er, der da thronet seit Urbeginn. Sela. / Denn sie besinnen sich nicht eines Bessern, / Elohim fürchten sie nicht.',
        21: 'Er legt seine Hand an seine Freunde, / Entweiht seinen Bund.',
        22: "Glatt wie Butter sind seine Worte, / Aber in seinem Herzen ist Krieg. / Seine Reden sind linder als Öl, / Und doch sind's gezückte Schwerter.",
        23: 'Wirf deine Bürde auf Jahwe! / Er wird dich versorgen; / Nimmer läßt er den Gerechten wanken. Doch du, Elohim, wirst sie in die unterste Grube stürzen. / Die da mit Mord und Trug umgehn, / Sollen nicht ihres Lebens Hälfte erreichen. / Ich aber traue auf dich!',
    },
    56: {
        1: 'Dem Sangmeister. Nach (der Melodie des Liedes:) "O stumme Taube in der Ferne"(?). Ein Gedicht(?) Davids. / Als ihn die Philister in Gat ergriffen.',
        2: 'Sei mir gnädig, Elohim, denn Menschen treten mich nieder; / Allzeit befehden und drängen sie mich.',
        3: 'Meine Laurer quälen mich fort und fort, / Denn in Stolz befehden mich viele.',
        4: 'Will Furcht mich befallen, / So trau ich auf dich.',
        5: 'Elohim stärkt mich, sein Wort zu rühmen. / Elohim vertrau ich, ich fürchte mich nicht. / Was kann mir ein Sterblicher tun?',
        6: 'Meine Worte verdrehen sie immerfort, / Nur Böses denken sie wider mich.',
        7: 'Sie rotten sich, senden Laurer aus: / Die spüren mir nach auf Schritt und Tritt; / Denn sie trachten mir nach dem Leben.',
        8: 'Doch umsonst! Ich entrinne —. / Im Zorn, Elohim, wirf Leute danieder!',
        9: 'Meine Flüchtlingstage hast du gezählt. / Sammle meine Tränen in deinen Schlauch! / Stehen sie nicht in deinem Buch?',
        10: 'Einst weichen meine Feinde zurück; / Denn es kommt ein Tag, da ich rufe. / Dies weiß ich, daß Elohim hilft.',
        11: 'Elohim stärkt mich, das Wort zu rühmen, / Jahwe stärkt mich, das Wort zu rühmen.',
        12: 'Elohim vertrau ich, ich fürchte mich nicht. / Was können mir Menschen tun?',
        13: 'Dir, Elohim, erfüll ich meine Gelübde, / Dankopfer will ich dir bringen. Denn du hast mein Leben vom Tode errettet, / Ja, meine Füße vom Gleiten, / Damit ich wandeln kann vor Elohim / Im Lichte der Lebendigen.',
    },
    57: {
        1: 'Dem Sangmeister, nach (der Melodie des Liedes:) "Verderbe nicht!" / Ein Gedicht (?) Davids. Als er vor Saul in die Höhle floh.',
        2: 'Sei mir gnädig, Elohim, sei mir gnädig! / Denn meine Seele sucht Zuflucht bei dir. / In deiner Flügel Schatten bin ich geborgen, / Bis das Verderben vorüber ist.',
        3: "Ich rufe zu Elohim, dem Höchsten, / Zu El, der's für mich hinausführt.",
        4: 'Er sendet vom Himmel (sein Heil) und hilft mir. / Wenn mich mein Verfolger zum Kampf reizt, — Sela — / Dann sendet Elohim seine Huld und Treu.',
        5: 'Ich muß unter Löwen weilen, / Unter Leuten ruhn, die Flammen sprühn, / Ihre Zähne sind Spieß und Pfeile, / Ihre Zungen ein scharfes Schwert.',
        6: 'Elohim, erheb dich über die Himmel, / Deine Herrlichkeit über alle Welt!',
        7: 'Sie hatten meinen Füßen ein Netz gestellt, / So daß meine Seele in Angst sich wand. / Sie höhlten vor mir eine Grube aus — / Und fallen nun selbst hinein. Sela.',
        8: 'Mein Herz ist getrost, Elohim, mein Herz ist getrost; / Ich will singen und spielen.',
        9: 'Wach auf, mein Herz! / Wach auf, du Harfe und Zither! / Wecken will ich das Morgenrot.',
        10: 'Unter Völkern, Adonái, will ich dich preisen, / Dir singen unter den Leuten.',
        11: 'Denn groß bis zum Himmel ist deine Gnade, / Bis zu den Wolken reicht deine Treu. Elohim, erheb dich über die Himmel, / Deine Herrlichkeit über alle Welt!',
    },
    58: {
        1: 'Dem Sangmeister, nach (der Melodie des Liedes:) "Verderbe nicht!" (?). / Ein Gedicht (?) Davids.',
        2: 'Redet ihr wirklich Gerechtigkeit, / Richtet ihr redlich, ihr Menschenkinder?',
        3: 'Nein, im Herzen sinnet ihr Frevel, / Für eurer Hände Gewalttat macht ihr im Lande Bahn.',
        4: 'Von Geburt an weichen die Frevler ab, / Die Lügenredner irren von Kindheit an?',
        5: 'Gift haben sie wie Schlangengift, / Wie eine taube Natter, die ihr Ohr verstopft,',
        6: 'Die nicht hört auf der Zauberer Stimme, / Auf die Stimme der klugen Beschwörer.',
        7: 'Elohim, zerbrich ihre Zähne in ihrem Mund, / Reiß aus, o Jahwe, der Löwen Gebiß!',
        8: 'Sie sollen zerfließen, wie Wasser verläuft. / Schießt er seine Pfeile, so seien sie stumpf.',
        9: 'Sie sollen der Schnecke gleichen, die kriechend zerfließt, / Eines Weibes Fehlgeburt, die die Sonne nicht sieht.',
        10: "Eh eure Töpfe die Dornen merken — / Sei roh oder gar das Fleisch: der Sturm treibt's weg.",
        11: 'Der Gerechte frohlockt, wenn er Rache geschaut, / Er badet den Fuß in der Frevler Blut. Dann sagt man: "Ja wahrlich, der Fromme hat Frucht; / Ja, es gibt einen Gott, der da richtet auf Erden!"',
    },
    59: {
        1: 'Dem Sangmeister, nach (der Weise des Liedes:) "Verderbe nicht!" (?). / Ein Gedicht (?) Davids, als Saul hinsandte und sie das Haus bewachten, um ihn zu töten.',
        2: 'Errette mich, mein Gott, von meinen Feinden, / Vor meinen Widersachern schütze mich!',
        3: 'Rette mich von den Übeltätern / Und hilf mir gegen die Mörder!',
        4: 'Denn fürwahr, sie lauern mir auf. / Es rotten sich Grausame wider mich, / doch bin ich, o Jahwe, schuldlos daran.',
        5: 'Aber trotz meiner Unschuld stürmen sie an und rüsten sich. / Auf, hilf mir, sieh drein!',
        6: 'Du, Jahwe Elohim der Heerscharen (Herr), Gott Israels, / Wach auf, alle Heiden zu strafen! / Verschone keinen der freveln Verräter! Sela.',
        7: 'Jeden Abend kehren sie wieder, knurren wie Hunde, / Durchstreifen die Stadt.',
        8: 'Fürwahr, sie geifern mit ihrem Munde, / Auf ihren Lippen sind Schwerter. / Denn (sie denken:) "Wer hört es?"',
        9: 'Du aber, Jahwe, lachest ihrer, / Du spottest aller Heiden.',
        10: 'Mein Hort, dein will ich harren; / Denn Elohim ist mein Schutz.',
        11: 'Mein Gott kommt mir mit seiner Gnade entgegen, / An meinen Laurern läßt Elohim meine Lust mich sehn.',
        12: 'Töte sie nicht, damit es mein Volk nicht vergesse; / Treib sie umher durch deine Macht und stürze sie nieder, / Du, unser Schild, Adonái!',
        13: 'Es sündigt ihr Mund in jedem Wort ihrer Lippen / — Sie sollen sich fangen in ihrem Hochmut! —, / Ihr Reden ist nichts als Fluchen und Lügen.',
        14: 'Vertilg sie im Grimm, vertilge sie, daß sie nicht mehr seien! / Dann wird man erkennen, daß Elohim in Jakob herrscht / Bis an die Enden der Erde. Sela.',
        15: 'Jeden Abend kehren sie wieder, knurren wie Hunde, / Durchstreifen die Stadt.',
        16: 'Sie irren umher und suchen nach Speise. / Wenn sie nicht satt werden, murren sie.',
        17: 'Ich aber will singen von deiner Macht / Und jauchzen am Morgen ob deiner Huld. / Denn du bist mein Schutz, / Eine Zuflucht am Tage der Not. Mein Hort, dir will ich singen. / Denn Elohim ist mein Schutz, mein gnädiger Gott.',
    },
    60: {
        1: 'Dem Sangmeister, nach (der Weise des Liedes:) "Eine Lilie ist das Zeugnis", ein Gedicht (?) Davids, zum Lehren.',
        2: 'Als er mit den Syrern Mesopothamiens und den Syrern von Zoba stritt, / und als Joab zurückkehrte und 12000 Edomiter im Salztal schlug.',
        3: 'Elohim, du hast uns verworfen, zersprengt; / Du hast uns gezürnt: erheb uns nun wieder!',
        4: 'Erschüttert hast du das Land, es zerrissen; / Heile seine Brüche, denn es wankt!',
        5: 'Du ließest dein Volk gar Schweres erleben, / Du hast uns getränkt mit Taumelwein.',
        6: 'Nun hast du deinen Frommen ein Panier geschenkt, / Um das sie sich scharen sollen / Für die gerechte Sache. Sela.',
        7: 'Damit deine Lieben gerettet werden, / So hilf denn mit deiner Rechten und hör uns!',
        8: 'Elohim hat mir verheißen bei seinem heiligen Namen: / Frohlocken soll ich, austeilen Sichem / Und vermessen das Tal Sukkot.',
        9: 'Mein ist Gilead und mein Manasse, / Efraim schützt mein Haupt als Helm, / Juda ist mein Herrscherstab.',
        10: 'Moab ist mein Waschbecken, / Auf Edom werf ich meinen Schuh. / Schrei laut über mich o Philisterstadt!"',
        11: 'Wer bringt mich hinein in die feste Stadt? / Wer führt mich hin nach Edom?',
        12: 'Du, Elohim, du hast uns verworfen; / Du zogst nicht aus, Elohim, mit unsern Heeren. O schaff uns Beistand gegen den Feind! / Denn nichtig ist Menschenhilfe. Mit Elohim verrichten wir Heldentaten. / Er wird unsre Feinde zertreten.',
    },
    61: {
        1: 'Dem Sangmeister, auf Saitenspiel. Von David.',
        2: 'Hör, Elohim, mein lautes Flehn, / Merke auf mein Gebet!',
        3: 'Vom Ende des Landes ruf ich zu dir in meines Herzens Schmachten. / Auf einen Fels, der mir zu hoch ist, leite mich!',
        4: 'Du bist ja stets meine Zuflucht gewesen, / Ein starker Turm vor dem Feinde.',
        5: 'Laß mich ewig weilen in deinem Gezelt, / Im Schutz deiner Flügel Bergung finden! Sela.',
        6: 'Denn du, Elohim, hast meine Gelübde gehört, / Du hast den Frommen ihr Erbe gegeben.',
        7: 'Den König laß lange leben, / Laß seine Jahre für immer währen!',
        8: 'Er throne ewig vor Elohim! / Deine Huld und Treue laß ihn behüten! Dann will ich stets deinen Namen preisen, / Dir meine Gelübde täglich bezahlen.',
    },
    62: {
        1: 'Dem Sangmeister Jedutun zum Vortrag übergeben. Ein Psalm Davids.',
        2: 'Ja, Elohims harrt still meine Seele, / Von ihm kommt mein Heil.',
        3: 'Ja, er ist mein Fels und mein Heil, / Meine Burg — ich werde nicht wanken!',
        4: 'Wie lange stürmt ihr noch ein auf einen einzelnen Mann, / Sucht alle ihn niederzuwerfen? Aber ihr seid / Wie eine sinkende Wand, eine stürzende Mauer!',
        5: 'Ja, von seiner Höhe beschließen sie ihn zu stürzen. / Drum haben sie Lust an der Lüge. / Sie segnen mit ihrem Munde, / Aber im Herzen fluchen sie. Sela.',
        6: 'Ja, Elohims harr ich still, meine Seele, / Denn meine Hoffnung kommt von ihm.',
        7: 'Ja, er ist mein Fels und mein Heil, / Meine Burg — ich werde nicht wanken!',
        8: 'Auf Elohim ruhn meine Hilfe und Ehre; / Mein starker Fels, meine Zuflucht ist in Elohim.',
        9: 'Traut ihm, ihr Leute, zu aller Zeit! / Schüttet vor ihm eure Herzen aus! / Elohim ist unsre Zuflucht. Sela.',
        10: 'Nur ein Hauch sind Leutesöhne. / Lüge sind Herrensöhne; / Auf der Waage schnellten sie sicher empor. / Allzumal sind sie ein Hauch.',
        11: 'Vertraut nicht auf erpreßtes Gut, / Laßt euch nicht blenden durch Raub! / Wächst das Vermögen, so achtet nicht drauf!',
        12: 'Einmal, zweimal hat Elohim geredet, was ich gehört: / Elohims ist die Macht. "Aber bei dir, Adonái, ist auch die Gnade." / Denn du vergiltst einem jeden nach seinem Tun.',
    },
    63: {
        1: 'Ein Psalm Davids, als er in der Wüste Juda war.',
        2: 'Elohim, mein Gott bist du; dich suche ich. / Es dürstet nach dir meine Seele; / es schmachtet nach dir mein Leib / Im dürren Lande — da ist er ermattet aus Wassermangel.',
        3: 'So hab ich einst nach dir im Heiligtum geschaut, / Um deine Macht und Herrlichkeit zu sehn.',
        4: 'Denn deine Gnade ist besser als Leben; / Meine Lippen sollen dich loben.',
        5: 'So will ich dich preisen mein Leben lang, / In deinem Namen die Hände erheben.',
        6: 'Dann bin ich satt wie von Mark und Fett. / Und mit jubelnden Lippen lobsingt mein Mund,',
        7: 'Wenn ich dein gedenke auf meinem Lager, / In den Nachtwachen über dich sinne.',
        8: 'Denn du bist mein Beistand gewesen, / Im Schatten deiner Flügel juble ich.',
        9: 'Meine Seel bleibt treu bei dir, / Mich hält deine Rechte fest.',
        10: 'Doch sie, die mein Leben mir rauben wollen — / In die Tiefen der Erde sollen sie fahren!',
        11: 'Man wird sie dem Schwert übergeben, / Sie müssen der Schakale Beute sein. Doch der König wird in Elohim sich freun. / Es rühmt sich jeder, der bei ihm schwört. / Denn der Lügner Mund muß verstummen.',
    },
    64: {
        1: 'Dem Sangmeister. Ein Psalm Davids.',
        2: 'Hör, Elohim, mein klagendes Rufen, / Vor dem schrecklichen Feinde bewahre mein Leben!',
        3: 'Schütze mich vor der Frevler Rotte, / Vor dem lärmenden Haufen der Übeltäter!',
        4: 'Sie schärfen ihre Zunge wie Schwerter, / Spannen als Pfeile verwundende Reden.',
        5: 'Sie schießen heimlich den Frommen, / Treffen ihn plötzlich ohne Scheu.',
        6: 'Sie nehmen sich fest das Böse vor; / Sie beschließen, Schlingen zu legen, / Und fragen: "Wer wird sie sehn?"',
        7: 'Sie erdenken Frevel: "Wir haben\'s vollendet, der Plan ist ersonnen!" / Eines jeden Herz ist ein Abgrund.',
        8: 'Aber da trifft sie Gott mit dem Pfeil: / Plötzlich sind ihre Wunden da!',
        9: 'Ihre eigne Zunge bringt sie zu Fall. / Die auf sie sehen, schütteln den Kopf.',
        10: 'Da fürchten sich alle, / Verkünden das Tun Elohims / Und betrachten sein Werk. Der Gerechte freut sich in Jahwe und fliehet zu ihm. / Sein rühmen sich alle redlichen Herzen.',
    },
    65: {
        1: 'Dem Sangmeister, ein Psalm Davids. Ein Lied.',
        2: 'Dir gebührt, Elohim, in Zion ein Lobgesang, / Dir soll man Gelübde bezahlen.',
        3: 'Du erhörest Gebete; / Drum kommen alle Menschen zu dir.',
        4: 'Sind meine Sünden mir unerträglich — / Du wirst unsre Frevel vergeben.',
        5: 'Heil dem, den du erwählst und nahen lässest, / Daß er weile in deinen Höfen! / Laß uns deines Hauses Segen genießen, / Deines heiligen Tempels Segen!',
        6: 'In Huld erhörst du uns furchtbar, Gott unsers Heils. / Dir vertraun alle Enden der Erde und fernen Meere.',
        7: 'Er festigt die Berge durch seine Kraft, / Er ist umgürtet mit Stärke.',
        8: 'Er stillet das Brausen des Meeres, seiner Wellen Gedröhn / Und das Tosen der Völker.',
        9: 'Drum zittern die fernsten Erdbewohner vor deinen Zeichen. / Ost und West erfüllst du mit Jubel.',
        10: 'Du hast des Landes gedacht, ihm Fülle verliehn, / Es mit Reichtum begabt. / Der Bach Elohims war mit Wasser gefüllt. / Du hast den Menschen Getreide geschenkt, / Hast das Land so fruchtbar gemacht.',
        11: 'Des Erdreichs Furchen hast du getränkt, seine Schollen erweicht, / Es durch Regen gelockert / Und sein Gewächs gesegnet.',
        12: 'Du hast das Jahr deiner Güte gekrönt, / Und deine Geleise triefen von Fett.',
        13: 'Es triefen die Auen der Steppe, / Mit Jubel die Hügel sich gürten. Es sind die Fluren mit Herden bedeckt, / Die Täler mit Korn gehüllt — / Alles jauchzet und singt!',
    },
    66: {
        1: 'Dem Sangmeister. Ein Lied. Ein Psalm. / Jauchzt Elohim, alle Lande,',
        2: 'Besingt seines Namens Ehre, / Preiset ihn herrlich!',
        3: 'Sprecht zu Elohim: "Wie hehr sind deine Werke! / Ob deiner großen Macht schmeicheln dir deine Feinde.',
        4: 'Alle Welt muß dir sich beugen und lobsingen, / Lobsingen deinem Namen!" Sela.',
        5: 'Kommt, schauet die Taten Elohims! / Hehr waltet er unter den Menschenkindern.',
        6: 'Er wandelte Meer in trocknes Land, / Daß man den Strom zu Fuß durchzog. / Drum wollen wir uns sein freun.',
        7: 'Ewig herrscht er in seiner Macht. / Seine Augen schauen die Völker an: / Die Empörer dürfen sich nicht erheben. Sela.',
        8: 'Preiset, ihr Völker, unsern Gott, / Laßt laut sein Lob erschallen!',
        9: 'Er hat uns am Leben erhalten / Und unsern Fuß nicht wanken lassen.',
        10: 'Denn du hast uns geprüft, Elohim, / Hast uns wie Silber geläutert:',
        11: 'Du hast uns ins Gefängnis geführt, / Auf unsre Lenden Last gelegt.',
        12: 'Du hast uns Menschen zu Herren gesetzt; / Wir sind in Feuer und Wasser geraten — / Aber du hast uns hinausgeführt, / Daß wir reiche Fülle genießen.',
        13: 'Drum komm ich mit Brandopfern in dein Haus, / Will dir meine Gelübde bezahlen,',
        14: 'Die meine Lippen kundgetan, / Die mein Mund geredet in meiner Not.',
        15: 'Als Brandopfer bring ich dir feiste Schafe / Zugleich mit der Widder Opferrauch, / Ich opfre Rinder samt Böcken. Sela.',
        16: 'Kommt her, hört zu, ihr Gottesfürchtigen alle! / Erzählen will ich, was er mir getan.',
        17: 'Zu ihm rief ich mit meinem Munde — / Und Lobpreis war auf meiner Zunge.',
        18: 'Hegte ich Böses in meinem Herzen, / Adonái würde nicht hören.',
        19: 'Aber Elohim hat mich erhört, / Er hat gemerkt auf mein lautes Flehn.',
        20: 'Gepriesen sei Elohim! Er hat mein Gebet nicht abgewiesen, / Seine Gnade mir nicht entzogen.',
    },
    67: {
        1: 'Dem Sangmeister, mit Saitenspielbegleitung. Ein Psalm, ein Lied.',
        2: 'Elohim sei uns gnädig und segne uns, / Lasse bei uns sein Antlitz leuchten! Sela.',
        3: 'So erkennt man auf Erden deinen Weg, / Dein Heil unter allen Völkern.',
        4: 'Völker sollen dich preisen, Elohim, / Es sollen dich preisen die Völker alle.',
        5: 'Die Leute freun sich und frohlocken, / Daß du die Völker recht regierst / Und die Leute auf Erden leitest. Sela.',
        6: 'Völker sollen dich preisen, Elohim, / Es sollen dich preisen die Völker alle.',
        7: 'Das Land hat seinen Ertrag geschenkt, / Elohim, unser Gott — er hat uns gesegnet. Elohim wird uns auch ferner segnen, / Und fürchten werden ihn alle Enden der Erde.',
    },
    68: {
        1: 'Dem Sangmeister. Von David. Ein Psalm. Ein Lied.',
        2: 'Elohim steht auf: seine Feinde zerstieben, / Und seine Hasser fliehen vor ihm.',
        3: 'Wie Rauch verweht, verwehest du sie. / Wie Wachs vor Feuer zerschmilzt, / So müssen die Frevler vor Gott vergehn.',
        4: 'Doch die Gerechten sollen sich freun, sie sollen frohlocken vor Elohim / Und sich ergötzen in Wonne.',
        5: 'Singt Elohim, spielt seinem Namen, / Preist ihn, der auf Wolken einherfährt! / Jah ist sein Name: jauchzet vor ihm!',
        6: 'Ein Vater der Waisen und Anwalt der Witwen / Ist Elohim in seiner heiligen Wohnstatt.',
        7: 'Verlassen gibt Elohim ein Heim, / Er führt Gefangene aus zum Glück. / Doch die Abtrünnigen bleiben im dürren Land.',
        8: 'Elohim, als du vor deinem Volk herzogst, / Als du durch die Wüste schrittst, — Sela. —',
        9: 'Da bebte die Erde, / Auch die Himmel troffen vor Elohim; / Der Sinai da — (er bebte) vor Elohim, / Israels Gott.',
        10: 'Mit reichlichem Segen besprengst du, Elohim, dein Erbe; / Und war es ermattet, hast du es erquickt.',
        11: 'Deine Schar fand Wohnung darin. / Gütig hast du den Armen versorgt, Elohim.',
        12: 'Adonái ließ mächtigen Ruf erschallen. / Siegkünderinnen gab es in großer Zahl.',
        13: 'Mit ihren Scharen flohen die Könige, flohen, / Und die Hausfrau verteilte die Beute.',
        14: 'Wenn ihr zwischen den Hürden lagt, / Waren der Taube Flügel mit Silber bezogen / Und ihre Schwingen mit gelblichem Gold.',
        15: 'Als der Allmächtige Könige dort zerstreute, / Fiel Schnee auf Zalmon.',
        16: 'Ein Berg Elohims ist Basans Gebirge, / Reich an Gipfeln ist Basans Gebirge.',
        17: 'Was blickt ihr so scheel, ihr Berge, ihr Gipfel, / Auf jenen Berg, den sich Elohim zum Wohnsitz erkoren? / Ja, Jahwe wird ewig dort thronen.',
        18: 'Der Wagen Elohims sind Zehntausende, tausend und abertausend, / Adonái weilt unter ihnen, / Der Sinai ist im Heiligtum.',
        19: 'Du bist zur Höhe emporgestiegen, du hast Gefangne weggeführt, / Hast Gaben an Menschen empfangen, / Auch Widerspenstige sollen wohnen bei Jah Elohim.',
        20: 'Gepriesen sei Adonái! / Er trägt uns Tag für Tag; / Er, Gott, ist unsre Hilfe. Sela.',
        21: 'Er, Gott, ist uns ein Gott, der rettet: / Jahwe Adonái hat Ausgangswege auch für den Tod.',
        22: 'Ja, Elohim zerschellt seiner Feinde Haupt. / Den Haarscheitel des, der stolz einhergeht in seiner Sündenschuld.',
        23: 'Gesprochen hat Adonái: "Aus Basan bring ich (dich) heim, / Bring (dich) heim aus Meerestiefen,',
        24: 'Damit dein Fuß sich bade in Blut, / Deiner Hunde Zunge ihr Teil an den Feinden habe."',
        25: 'Man wird deinen Prachtzug sehn, Elohim, / Meines Gottes, meines Königs Zug ins Heiligtum hinein:',
        26: 'Sänger schreiten voran, dann folgen Saitenspieler / Inmitten Pauken schlagender Jungfraun:',
        27: '"In Chören preist Elohim, / Preist Adonái, ihr aus Israels Born!"',
        28: 'Da ist Benjamin der Kleine mit ihrem Herrscher: / Den Fürsten Judas in ihrem Purpur. / Da sind Sebulons Fürsten, Naftalis Fürsten.',
        29: 'Verordnet hat dein Gott, daß du so mächtig seist. / Stärke drum, Elohim, was du uns bereitet!',
        30: 'Von deinem Tempel aus (walte du) über Jerusalem: / Dir sollen Könige Gaben bringen.',
        31: 'Bedrohe das Tier des Schilfs, der Stiere Schar mit den Völkerkälbern, / Damit sie sich niederwerfen mit Silberstücken! / Zerstreue die Völker, die Kriege lieben!',
        32: 'Aus Ägypten werden Gesandte kommen, / Kusch eilt her und bringt Elohim seine Gaben.',
        33: 'Ihr Reiche der Erde, singt Elohim, / Preist Adonái mit Saitenspiel! Sela.',
        34: 'Preist ihn, der da fährt durch die Himmel, die Himmel der Urzeit! / Er läßt seine Stimme erschallen, seine mächtige Stimme.',
        35: 'Gebt Elohim die Ehre! / Über Israel thront seine Hoheit, / In den Wolken ist seine Macht! Hehr bist du, Elohim, von deinen Heiligtümern aus. / Israels Gott — er gibt seinem Volke Macht und Kraft. / Gepriesen sei Elohim!',
    },
    69: {
        1: 'Dem Sangmeister, nach (der Weise von:) "Lilien". Von David.',
        2: 'Hilf mir, Elohim, / Denn die Wasser bedrohen mein Leben!',
        3: 'Versunken bin ich in tiefen Morast und kann nicht stehn; / Ich bin geraten in Wasserstrudel, es hat mich die Flut überströmt.',
        4: 'Ich bin müde vom Schrein, meine Kehle ist heiser; / Erloschen sind meine Augen, während ich harre auf meinen Gott.',
        5: 'Zahlreicher als meines Hauptes Haare sind, die mich grundlos hassen. / Mächtig sind, die mich zu vernichten suchen, / Die mich mit Unrecht befeinden. / Was ich nicht geraubt, das soll ich erstatten!',
        6: 'Elohim, du kennst meine Torheit, / Und mein Verschulden ist dir nicht verborgen.',
        7: 'Laß nicht in mir zuschanden werden, die auf dich harren, / Adonái Jahwe der Heerscharen (Herr)! / Laß nicht um meinetwillen in Schimpf geraten, / Die dich, Gott Israels, suchen!',
        8: 'Denn meinetwegen habe ich Schmach ertragen, / Hat Schande mein Antlitz bedeckt.',
        9: 'Fremd bin ich meinen Brüdern geworden / Und unbekannt meiner Mutter Söhnen.',
        10: 'Denn der Eifer um dein Haus hat mich verzehrt, / Und die Lästerungen derer, die dich schmähen, sind auf mich gefallen.',
        11: 'Wenn ich weinte bei meinem Fasten, / So ward ich deshalb verhöhnt.',
        12: 'Und zog ich an ein härenes Kleid, / So trieben sie ihren Spott mit mir.',
        13: 'Die im Tore sitzen, schwatzen von mir, / Die Lieder der Zecher verhöhnen mich.',
        14: 'Ich aber, Jahwe, bete zu dir; nimm du es gnädig auf! / Antworte mir, Elohim, nach deiner großen Güte, / Nach deiner Treue, die Hilfe schenkt!',
        15: 'Entreiß mich dem Schlamm, daß ich nicht versinke! / Von meinen Feinden errette mich, / Zieh mich aus den Wassertiefen!',
        16: 'Laß mich die Fluten nicht überströmen, / Laß den Strudel mich nicht verschlingen, / Nicht schließe der Brunnen sich über mir!',
        17: 'Erhöre mich, Jahwe; denn deine Huld ist köstlich; / Nach deinem großen Erbarmen kehr dich zu mir!',
        18: 'Verbirg dein Antlitz nicht vor deinem Knechte! / Denn mir ist angst; antworte mir eilends!',
        19: 'O nahe du meiner Seele, erlöse sie, / Um meiner Feinde willen mache mich frei!',
        20: 'Du weißt ja, daß Schmach und Schande und Schimpf mein Teil gewesen; / All meine Dränger sind dir bekannt.',
        21: 'Die Schmach hat mein Herz gebrochen: ich sieche dahin. / Ich dachte, Mitleid zu finden, doch nein! / Ich hoffte auf Tröster und fand sie nicht.',
        22: 'Vielmehr ward mir Gift in die Speise gemischt, / Mit Essig tränkte man mich in meinem Durst.',
        23: 'Ihr Tisch soll ihnen zur Schlinge werden, / Zum Fallstrick, während sie sorglos sind.',
        24: 'Ihre Augen sollen finster werden und nicht mehr sehn. / Ihre Hüften laß immerdar wanken!',
        25: 'Gieß deinen Grimm auf sie aus, / Und deine Zornglut treffe sie!',
        26: 'Ihr Lager soll wüste werden, / In ihren Zelten sei kein Bewohner!',
        27: 'Denn den du geschlagen, verfolgen sie / Und erzählen von deiner Durchbohrten Schmerz.',
        28: 'Mehre du ihre Sündenschuld / Und laß sie dein Heil nicht erlangen!',
        29: 'Tilge sie aus dem Lebensbuch / Und mit den Frommen schreib sie nicht auf!',
        30: 'Doch ich bin gebeugt und schmerzbeladen, / Deine Hilfe, Elohim, sie wird mich schützen.',
        31: 'Dann will ich den Namen Gottes im Liede rühmen / Und ihn mit Danken erheben.',
        32: 'Das wird Jahwe besser gefallen als Rinder, / Als Stiere mit Hörnern und Klauen.',
        33: 'Sehen das Dulder, so freuen sie sich. / Die ihr Gott sucht, euer Herz lebe auf!',
        34: 'Denn Jahwe merkt auf die Armen, / Seine Gefangnen verachtet er nicht.',
        35: 'Es sollen ihn loben Himmel und Erde, / Die Meere und alles, was drinnen sich regt.',
        36: 'Denn Elohim wird Zion helfen / Und bauen die Städte Judas, / Daß man dort wohne und sie besitze. Seiner Knechte Nachkommen werden sie erben; / Und die seinen Namen lieben, / Sollen darin ihre Wohnung haben.',
    },
    70: {
        1: 'Dem Sangmeister, von David. Zum Bekennen (?).',
        2: 'Eile, Elohim, mich zu retten, / Eile mir, Jahwe, zu Hilfe!',
        3: 'Beschämt und enttäuscht laß alle werden, / Die mir nach dem Leben trachten. / Mit Schimpf laß alle entweichen, / Die da mein Unglück wollen.',
        4: 'Zurückwenden sollen sich ob ihrer Schande, / Die (schadenfroh) über mich rufen: "Ha, ha!"',
        5: 'Frohlocken laß aber und dein sich freun / Alle, die nach dir fragen. / Laß immerdar rufen: "Groß ist Elohim!" / Alle, die dein Heil lieben! Bin ich auch elend und arm — / Elohim, eile zu mir! / Mein Helfer und Retter bist du. / Jahwe, verzieh deine Hilfe nicht!',
    },
    71: {
        1: 'Bei dir, o Jahwe, hab ich Zuflucht gesucht, / Laß mich nimmer zuschanden werden!',
        2: 'In deiner Treue rette mich und mache mich frei, / Neige dein Ohr zu mir und schaffe mir Heil!',
        3: 'Sei mir ein schützender Fels, zu dem ich beständig fliehen kann! / Du hast ja beschlossen, mir Heil zu erweisen; / Denn mein Fels, meine Burg bist du.',
        4: 'Mein Gott, errette mich aus des Frevlers Hand, / Aus der Faust des Schurken und Drängers!',
        5: 'Du bist ja meine Hoffnung, Adonái Jahwe, / Auf den ich vertraue von Kindheit an.',
        6: 'Du bist meine Stütze seit meiner Geburt, / Aus dem Mutterschoß hast du mich gelöst. / Dir gilt mein Loblied beständig.',
        7: 'Ein Wunder bin ich für viele, / Meine starke Zuflucht aber bist du.',
        8: 'Mein Mund soll sich füllen mit deinem Lob, / Dich soll er immerdar rühmen.',
        9: 'Verwirf mich nicht, wenn das Alter kommt; / Schwindet die Kraft mir, verlaß mich nicht!',
        10: 'Schon reden ja meine Feinde von mir, / Und die mein Leben belauern beraten zusammen.',
        11: 'Sie sprechen: "Gott hat ihn verlassen, / Verfolgt und greift ihn! Es rettet ihn keiner."',
        12: 'Elohim, sei du nicht ferne von mir; / Mein Gott, eile mir zu Hilfe!',
        13: 'Zuschanden werden, hinschwinden laß meine Widersacher! / In Schimpf und Schande laß alle sich hüllen, / Die da mein Unglück suchen!',
        14: 'Ich aber will (dein) beständig harren / Und all dein Lob vermehren.',
        15: 'Mein Mund soll deine Gerechtigkeit künden, / Allzeit dein Heil; denn ich kann sie nicht zählen.',
        16: 'Kundmachen will ich die mächtigen Taten Adonái Jahwes, / Will preisen deine Gerechtigkeit allein.',
        17: 'Elohim, du hast mich gelehrt von Jugend auf, / Und deine Wunder verkünd ich bis jetzt.',
        18: 'So verlaß mich auch nicht, Elohim, wenn das Alter kommt mit dem Silberhaar, / Bis ich deinen Namen der Nachwelt verkünde / Und allen Kommenden die Kraft!',
        19: 'Deine Gerechtigkeit, Elohim, reicht bis zur Wolkenhöhe, / Der du so Großes getan. / Elohim, wer ist dir gleich?',
        20: 'Du hast uns erleben lassen viel Not und Leid, / Aber du wirst uns auch wieder erfreuen mit Lebensglück / Und aus der Erde Tiefen uns wieder erheben.',
        21: 'Du wirst meine Hoheit mehren / Und mich wiederum trösten.',
        22: 'Auch ich will dich preisen mit Harfenklang / Für deine Treue, mein Gott; / Auf der Zither will ich dir spielen, / Du Heiliger Israels.',
        23: 'Meine Lippen jauchzen, wenn ich dir spiele, / Und meine Seele, die du erlöst.',
        24: 'Auch meine Zunge soll allzeit künden deine Gerechtigkeit; / Denn beschämt, enttäuscht sind sie, die mein Unglück suchen.',
    },
    72: {
        1: 'Von Salomo. / Elohim, gib dem Könige Macht zu richten / Und laß den Königssohn sie üben in deiner Gerechtigkeit!',
        2: "Mög er dein Volk gerecht regieren / Und deine Armen, wie sich's gebührt!",
        3: 'Laß Frieden tragen die Berge dem Volk, / Und Gerechtigkeit kleide deine Hügel!',
        4: 'Er schaffe Recht den Armen im Volk, / Er helfe den dürftigen Leuten / Und zermalme alle Bedrücker!',
        5: 'Er bleibe, solange die Sonne scheint, / Solange der Mond zu sehn, von Geschlecht zu Geschlecht.',
        6: 'Er sei wie Regen, der Wiesen benetzt, / Wie reiche Güsse, die Felder befeuchten.',
        7: 'In seinen Tagen soll blühen das Recht / Und Friede in Fülle, bis nimmer der Mond.',
        8: 'Er herrsche von Meer zu Meer, / Vom Strom bis ans Ende der Erde.',
        9: 'Die Wüstenbewohner knien vor ihm, / Seine Feinde werden den Boden küssen.',
        10: 'Von Tarsis und von den Inseln entrichten die Könige Gaben, / Von Scheba und Seba bringen die Könige Zins herbei.',
        11: 'Huldigen sollen ihm alle Könige, / Alle Völker ihm dienen.',
        12: 'Denn er rettet den Armen, der Hilfe erfleht, / Den Dürftigen, der keinen Beistand hat.',
        13: 'Er erbarmt sich des Schwachen und Armen, / Und der Elenden Leben errettet er.',
        14: 'Von Druck und Gewalttat macht er sie frei, / Ihr Blut ist teuer in seinen Augen.',
        15: 'So leben sie denn; ja, er wird sie mit Gold aus Scheba beschenken. / Drum werden sie stetig auch für ihn beten / Und allzeit ihm Segen wünschen.',
        16: 'Getreide in Fülle sei im Land, sogar auf den Gipfeln der Berge; / Wie der Libanon woge und rausche die Frucht. / Wie der Erde Kräuter so zahlreich / Mögen die Städtebewohner erblühn.',
        17: 'Sein Name bleibe auf ewig! / Solange die Sonne scheint, möge sein Name bestehn! / Es mögen sich alle segnen mit ihm, / Alle Völker ihn glücklich preisen!',
        18: 'Gepriesen sei Jahwe Elohim, Israels Gott, / Der Wunder vollbringt allein!',
        19: 'Und gepriesen sei ewig sein herrlicher Name! / Sein Ruhm erfülle die ganze Erde! / Amen. Amen.',
    },
    73: {
        1: 'Ein Psalm Asafs. / Ja, gütig ist Gott gegen Israel, / Gegen die, die reines Herzens sind.',
        2: 'Doch meine Füße wären beinah gestrauchelt, / Meine Tritte fast ausgeglitten.',
        3: 'Denn ich ward neidisch auf die Prahler, / Als ich das Glück der Frevler sah.',
        4: 'Sie kennen ja keine Schmerzen, / Und von Gesundheit strotzt ihr Leib.',
        5: 'Nicht sind sie in Unglück wie Sterbliche sonst, / Sie leiden nicht Plage wie andre Leute.',
        6: 'Drum ist auch Hoffart ihr Halsschmuck, / Unrecht umhüllt sie als ihr Gewand.',
        7: 'Ihr Auge tritt mühsam hervor aus dem Fett, / Ihr Herz ist voll stolzer Gedanken.',
        8: 'Sie höhnen und sprechen boshaft von Gewalt, / Sie reden von oben herab.',
        9: 'In den Himmel setzen sie ihren Mund, / Ihre Zunge ergeht sich auf Erden.',
        10: 'Drum fallen ihnen die Leute zu, / Die schlürfen Wasser in Fülle ein.',
        11: 'Sie sprechen: "Wie sollte Gott etwas wissen? / Wohnt denn bei dem Höchsten Kenntnis?',
        12: 'Diese Leute leben zwar ohne Gott, / Doch haben sie, ewig ungestört, / Reichtum und Macht erlangt.',
        13: "Umsonst ist's, daß ich mein Herz hab reingehalten / Und meine Hände in Unschuld gewaschen.",
        14: 'Ich war doch geplagt den ganzen Tag / Und ward alle Morgen aufs neue gestraft."',
        15: 'Hätt ich gedacht: So will ich auch reden, / Ich hätte verleugnet deiner Kinder Geschlecht.',
        16: 'So sann ich denn nach, dies Rätsel zu lösen; / Doch allzu schwierig war es für mich;',
        17: 'Bis ich in Gottes Heiligtum ging / Und auf ihr (trauriges) Ende merkte.',
        18: 'Ja, auf schlüpfrigen Boden stellst du sie, / Du stürzest sie ins Verderben.',
        19: 'Wie sind sie im Nu zunichte geworden, / Geschwunden, vergangen durch Schreckensgerichte!',
        20: 'Wie ein Traum verfliegt, sobald man erwacht: / So wirst du, Adonái, ihr Bild verschmähn, / Wenn du dich aufmachst (zu richten).',
        21: 'Würde (nun wieder) mein Herz erbittert, / Und fühlt ich es stechen in meinen Nieren:',
        22: 'Dann wär ich ein Narr und wüßte nichts, / Ich wäre sogar wie ein Tier vor dir.',
        23: 'Aber ich bleibe nun stets bei dir, / Du hast ja erfaßt meine rechte Hand.',
        24: 'Nach deinem Ratschluß wirst du mich leiten / Und nimmst mich endlich mit Ehren auf.',
        25: 'Wen hätt ich im Himmel (ohne dich)? / Und bist du mein, so begehr ich nichts weiter auf Erden.',
        26: 'Ist auch mein Leib geschwunden, und schlägt mein Herz nicht mehr: / Meines Herzens Hort und mein Besitz / Bleibt doch Elohim auf ewig!',
        27: 'Denn die von dir weichen, die kommen um; / Du vertilgst, die dich treulos verlassen.',
        28: 'Mir aber ist köstlich die Nähe Elohims. / Auf Adonái Jahwe ruht mein Vertraun: / So will ich verkündigen all dein Tun.',
    },
    74: {
        1: 'Eine Betrachtung (?) Asafs. / Warum, Elohim, hast du uns für immer verworfen? / Warum raucht denn dein Zorn / Gegen die Schafe, die du weidest?',
        2: 'Gedenke doch deiner Gemeinde, die du vor alters erworben, / Die du dir erlöst zum Besitzesstamm! / Des Zionsberges gedenke, auf dem du wohnst!',
        3: 'Tritt heran zu den ewigen Trümmern! / Der Feind hat alles zerstört im Heiligtum.',
        4: 'Deine Gegner haben gebrüllt an deiner Versammlungsstätte; / Sie stellten ihre Zeichen als Zeichen auf.',
        5: 'Es war, als schwängen Holzhauer die Äxte / Hoch in dem Dickicht des Waldes.',
        6: 'Und dann: auf sein Schnitzwerk insgesamt / Hieben sie ein mit Beil und Barten.',
        7: 'Sie steckten dein Heiligtum in Brand; / Deines Namens Wohnung entweihten sie / Und machten dem Boden sie gleich.',
        8: 'Sie dachten: "Wir wollen sie alle bezwingen." / Sie verbrannten alle Gottesstätten im Lande.',
        9: 'Unsre Zeichen sehn wir nimmer; es ist kein Prophet mehr da, / Und niemand ist bei uns, der wüßte, / Wie lange dies Elend noch währen wird.',
        10: 'Bis wann, Elohim, soll der Dränger noch höhnen? / Soll der Feind deinen Namen auf immer schmähn?',
        11: 'Warum ziehst du zurück deine Hand, deine Rechte? / Zieh sie aus dem Busen — vertilge!',
        12: 'Gott ist doch mein König von alters her, / Der Rettungstaten auf Erden vollbracht.',
        13: 'Du hast das Meer gespalten durch deine Macht, / Hast der Drachen Köpfe im Wasser zerschellt.',
        14: 'Leviatans Häupter hast du zerschmettert, / Du gabst sie zum Fraße den Wüstentieren.',
        15: 'Du ließest sprudeln Quelle und Bach, / Du ließest versiegen beständige Ströme.',
        16: 'Dein ist der Tag, dein auch die Nacht. / Leuchte und Sonne hast du bereitet.',
        17: 'Du hast alle Grenzen der Erde gesetzt, / Sommer und Winter hast du gebildet.',
        18: 'Gedenke: der Feind hat Jahwe geschmäht, / Ein gottloses Volk deinen Namen gehöhnt.',
        19: 'Gib nicht dem Tiere preis deiner Turteltaube Seele, / Deiner Armen Leben vergiß nicht für immer!',
        20: 'Schau auf den Bund! / Denn des Landes Verstecke sind angefüllt, / Und dort wird Gewalttat getrieben.',
        21: 'Nicht unerhört laß Niedergeschlagene gehn, / Laß deinen Namen Arme und Dürftige preisen!',
        22: 'Auf, Elohim! Ficht aus deinen Streit! / Gedenke des: die Gottlosen höhnen dich fort und fort!',
        23: 'Vergiß der Feinde Schmährufe nicht, / Deiner Gegner Toben, das stetig steigt!',
    },
    75: {
        1: 'Dem Sangmeister, nach (der Weise von:) "Verderbe nicht!" / Ein Psalm Asafs; ein Lied.',
        2: 'Wir danken dir, Elohim, wir danken; / Denn deine Hilfe ist nahe, und deine Wunder erzählt man.',
        3: 'Denn "Ich nehme die rechte Stunde wahr / Dann will ich in Gerechtigkeit richten.',
        4: 'Mag auch die Erde vor Furcht erbeben mit allen, die darauf wohnen: / Ich halte doch selbst ihre Säulen fest. Sela.',
        5: "Den Törichten sag ich: 'Seid nicht töricht!' / Den Frevlern: 'Hebt euer Horn nicht hoch!'",
        6: 'Hebt nicht euer Horn zur Himmelshöhe, / Redet nicht stolz mit gerecktem Haupt!"',
        7: 'Denn nicht von Osten, nicht von Westen, / Nicht von der Wüste her kommt Hilfe —',
        8: 'Nein, nur Elohim schafft Recht: / Diesen erniedrigt, jenen erhöht er.',
        9: 'Ein Becher ist ja in Jahwes Hand: / Er schäumt von Wein, ist reichlich gemischt. / Draus schenkt er ein; ja selbst seine Hefen / Müssen schlürfen und trinken alle Frevler auf Erden.',
        10: 'Ich aber will ewiglich jauchzen, / Dem Gott Jakobs will ich lobsingen. "Alle Hörner der Frevler will ich zerbrechen — / Hoch raget das Horn der Gerechten."',
    },
    76: {
        1: 'Dem Sangmeister, mit Saitenspielbegleitung. / Ein Psalm Asafs; ein Lied.',
        2: 'Wohlbekannt in Juda ist Elohim, / In Israel ist sein Name groß.',
        3: 'Ist doch in Salem sein Zelt / Und seine Wohnung in Zion.',
        4: 'Dort zerbrach er des Bogens Blitze, / Schild und Schwert und alle Waffen. Sela.',
        5: 'Von Licht umflossen bist du, herrlich kommst du / Von den Bergen der Beute her:',
        6: 'Entwaffnet wurden die Tapfern, sie sanken in Todesschlaf, / Und allen Helden versagte der Arm.',
        7: 'Vor deinem Drohen, Gott Jakobs, / Wurden Roß und Reiter betäubt.',
        8: 'Du bist furchtbar, ja du! / Wer besteht vor dir, wenn dein Zorn sich erhebt?',
        9: 'Vom Himmel herab hast du Gericht verkündet: / Die Erde erschrak und wurde still,',
        10: 'Als sich Elohim zum Gericht erhob, / Um allen Duldern des Landes zu helfen. Sela.',
        11: 'Die mit Wut Verfolgten werden dich preisen; / Die von der Wut Verschonten werden dir Feste feiern.',
        12: 'Tut Jahwe, eurem Gott, Gelübde und tragt sie ab! / Ihr alle ringsum, bringt dem Erhabnen Geschenke dar! Er bricht der Gewaltigen Trotz, / Flößt der Erde Königen Schrecken ein.',
    },
    77: {
        1: 'Dem Sangmeister Jedutun zum Vortrag übergeben. Ein Psalm Asafs.',
        2: 'Laut will ich schrein zu Elohim; / Laut ruf ich zu Elohim, daß er mich höre.',
        3: 'Zur Zeit meiner Not sucht ich Adonái. / Meine Hand hat sich zu ihm ausgestreckt / Und ist nicht erschlafft; / Meine Seele will sich nicht trösten lassen.',
        4: 'Gedenk ich Elohims, so muß ich seufzen; / Sinne ich nach, so verzagt mein Geist. Sela.',
        5: 'Du hast meine Augen wach gehalten; / Ich war zerschlagen und konnte nicht reden.',
        6: 'Da gedachte ich denn der alten Zeit, / Der längst entschwundenen Jahre.',
        7: 'Dacht ich des Nachts an mein Saitenspiel, / So klagte ich tief, / Und grübelnd fragte mein Geist:',
        8: '"Wird denn Adonái auf ewig verstoßen / Und nimmer wieder gnädig sein?',
        9: "Ist denn seine Huld auf immer dahin, / Ist's mit der Verheißung für allzeit aus?",
        10: 'Hat Gott vergessen, gnädig zu sein, / Oder sein Erbarmen in Zorn verschlossen?" Sela.',
        11: 'Da dacht ich denn: "Mein Leiden ist dies, / Daß die Rechte des Höchsten sich hat geändert."',
        12: 'Ich gedenke der Taten Jahs, / Ja, ich gedenke, wie du / So wunderbar seit der Vorzeit gewaltet.',
        13: 'Ich will sinnen über all dein Tun / Und dein herrliches Wirken erwägen.',
        14: 'Elohim, dein Weg ist erhaben! / Wo ist ein Gott, groß wie Elohim?',
        15: 'Du bist der Gott, der Wunder tut, / Unter den Völkern hast du deine Macht offenbart.',
        16: 'Du hast mit Kraft dein Volk erlöst, / Die Söhne Jakobs und Josefs. Sela.',
        17: 'Die Wasser sahen dich, Elohim, / Die Wasser sahen dich und bebten, / Auch die Tiefen erzitterten.',
        18: 'Die Wolken ergossen Wasser, / Der Donner krachte aus dem Gewölk, / Und deine Pfeile flogen umher.',
        19: 'Dein Donner dröhnte im Wirbelwind; / Blitze erhellten das Erdenrund, / Es wankte und bebte die Erde.',
        20: 'Im Meer ging dein Weg dahin / Und dein Pfad durch mächtige Wasser. / Doch deine Spuren sah man nicht. Wie Schafe hast du dein Volk geleitet / Durch Moses und Aarons Hand.',
    },
    78: {
        1: 'Eine Betrachtung(?) Asafs. / Vernimm, mein Volk, meine Lehre, / Neigt euer Ohr meines Mundes Reden!',
        2: 'Meinen Mund will ich öffnen zu Sprüchen, / Will aus der Vorzeit Rätsel verkünden.',
        3: 'Was wir gehört und erfahren, / Was uns unsre Väter erzählt:',
        4: 'Wollen wir unsern Kindern nicht verhehlen, / Indem wir der Nachwelt erzählen / Jahwes Ruhmestaten und Macht / Und seine Wunder, die er getan.',
        5: "Er stellte ein Zeugnis in Jakob auf / Und gab ein Gesetz in Israel. / Unsern Vätern befahl er's an, / Daß sie ihre Kinder es lehrten.",
        6: 'Denn die Nachkommen sollen es kennenlernen: / Kinder, die noch sollen geboren werden, / Die sollen auch selbst auftreten / Und ihren Kindern davon erzählen,',
        7: 'Damit sie auf Gott ihr Vertrauen setzen, / Nicht vergessen der Taten Gottes / Und seine Gebote halten.',
        8: 'Denn sie sollen nicht werden wie ihre Väter, / Ein störrig, widerspenstig Geschlecht, / Ein Geschlecht mit schwankendem Sinn, / Das nicht treu hielt an seinem Gott.',
        9: 'Efraims Söhne, gerüstete Bogenschützen, / Kehrten um am Tage der Schlacht.',
        10: 'Sie hielten nicht den Bund Elohims / Und wollten nicht wandeln nach seinem Gesetz.',
        11: 'Sie vergaßen seiner großen Taten, / Seiner Wunder, die sie geschaut.',
        12: 'Vor ihren Vätern hatte er Wunder getan / In Ägyptenland, in Zoans Gefild.',
        13: 'Er teilte das Meer und führte sie durch / Und türmte die Wasser wie einen Damm.',
        14: 'Er leitete sie durch die Wolke bei Tag / Und die ganze Nacht mit feurigem Licht.',
        15: 'Er spaltete Felsen in der Wüste / Und tränkte sie reich mit Meeresflut.',
        16: 'Er brachte Bäche hervor aus dem Fels, / Ließ Wasser wie Ströme fließen.',
        17: 'Doch sündigten sie weiter gegen ihn, / Widerstrebten dem Höchsten im dürren Lande.',
        18: 'In ihrem Herzen versuchten sie Gott / Und forderten Speise für ihr Gelüst.',
        19: 'Sie redeten so wider Elohim: / Kann Gott einen Tisch in der Wüste decken?',
        20: 'Er hat wohl den Fels geschlagen, daß Wasser floß / Und Bäche ergiebig strömten: / Doch vermag er auch Brot zu geben / Oder Fleisch zu verschaffen seinem Volk?"',
        21: 'Als Jahwe das hörte, ergrimmte er, / Und Feuer entbrannte in Jakob, / Auch Zorn stieg auf wider Israel.',
        22: 'Denn sie glaubten nicht an Elohim, / Auf seine Hilfe vertrauten sie nicht.',
        23: 'Dennoch gebot er den Wolken droben, / Und des Himmels Türen öffnete er:',
        24: 'Er ließ Man auf sie regnen zur Speise / Und gab ihnen Himmelsbrot.',
        25: 'Engelspeise aßen sie alle, / Zehrung sandte er ihnen in Fülle.',
        26: 'Er ließ den Ostwind am Himmel wehn, / Führte durch seine Macht den Südwind herbei.',
        27: 'Er ließ Fleisch auf sie regnen wie Staub / Und beschwingte Vögel wie Sand am Meer.',
        28: 'In ihr Lager ließ er sie fallen, / Rings um ihre Gezelte her.',
        29: 'Da aßen sie, wurden übersatt / Und ihr Gelüst befriedigte er.',
        30: 'Aber noch war ihre Lust nicht gestillt, / Noch war die Speise in ihrem Mund:',
        31: 'Da stieg Elohims Zorn wider sie auf — / Er streckte ihre Starken zu Boden, / Schlug nieder die Jünglinge Israels.',
        32: 'Trotz alledem sündigten sie aber fort / Und glaubten an seine Wunder nicht.',
        33: 'Drum ließ er ihre Tage schwinden in Nichts / Und ihre Jahre in jäher Hast.',
        34: 'Wenn er sie tötete, suchten sie ihn, / Kehrten um und fragten nach Gott,',
        35: 'Gedachten, wie Elohim ihr Fels / Und Gott der Höchste ihr Retter sei.',
        36: 'Doch heuchelten sie ihm mit ihrem Mund, / Mit ihrer Zunge logen sie ihm.',
        37: 'Ihr Herz war ihm nicht treu, / Sie hielten nicht fest an seinem Bund.',
        38: 'Doch er war barmherzig, vergab die Schuld / Und vertilgte sie nicht. / Oft hielt er seinen Zorn zurück, / Ließ nicht seinen ganzen Grimm ergehn,',
        39: 'Sondern dachte daran: sie sind nur Fleisch, / Ein Hauch, der vergeht und nicht wiederkehrt.',
        40: 'Wie oft widerstrebten sie ihm in der Wüste, / Betrübten sie ihn in der Öde!',
        41: 'Immer wieder versuchten sie Gott, / Den Heiligen Israels kränkten sie.',
        42: 'Sie gedachten nicht seiner Hand, / Auch nicht des Tages, da er sie erlöste von ihrem Dränger:',
        43: 'Als er in Ägypten Zeichen tat, / Seine Wunder in Zoans Gefild.',
        44: 'Er wandelte ihre Ströme in Blut, / Daß sie ihr Wasser nicht trinken konnten.',
        45: 'Er sandte ihnen Bremsen, die sie fraßen, / Und Frösche, die sie verderbten.',
        46: 'Er gab ihr Gewächs den Nagern preis, / Den Heuschrecken ihrer Felder Ertrag.',
        47: 'Ihre Weinstöcke schlug er mit Hagel, / Ihre Maulbeerbäume mit Schlossen.',
        48: 'Dem Hagel lieferte er aus ihr Vieh / Und ihre Herden den Blitzen.',
        49: 'Er sandte gegen sie seines Zornes Glut / Mit Ingrimm, Wüten und Angst: / Eine Schar verderbender Engel.',
        50: 'Er ließ seinem Zorne freien Lauf, / Bewahrte sie nicht vor dem Tode, / Sondern gab der Pest ihr Leben preis.',
        51: 'Er schlug alle Erstgeburt in Ägypten, / Die erste Manneskraft in Hams Gezelt.',
        52: 'Sein Volk aber ließ er wie Schafe ziehn / Und leitete sie in der Wüste wie eine Herde.',
        53: 'Er führte sie sicher, daß sie nicht zagten; / Ihre Feinde aber bedeckte das Meer.',
        54: 'Er brachte sie in sein heilig Gebiet, / Auf den Berg, den seine Rechte erworben.',
        55: 'Völker trieb er vor ihnen aus, / Gab ihnen ihr Land zum Erbbesitz, / Und in ihren Zelten ließ er Israels Stämme wohnen.',
        56: 'Doch sie versuchten und reizten Elohim den Höchsten, / Und seine Gebote hielten sie nicht.',
        57: 'Sondern wie ihre Väter wichen sie treulos ab, / Versagten wie ein trüglicher Bogen.',
        58: 'Sie erzürnten ihn durch ihre Höhn, / Durch ihre Bilder reizten sie ihn.',
        59: 'Das hörte Elohim und zürnte: / Er verwarf Israel ganz und gar.',
        60: 'Er verließ die Wohnung in Silo, / Das Zelt, das er unter Menschen errichtet.',
        61: 'Er ließ seine Macht gefangennehmen / Und gab seinen Ruhm in des Feindes Hand.',
        62: 'Er gab sein Volk dem Schwerte preis, / Und über sein Erbe zürnte er.',
        63: 'Ihre Jünglinge fraß das Feuer, / Ihren Jungfraun ward kein Hochzeitslied.',
        64: 'Ihre Priester fielen durchs Schwert, / Und ihre Witwen weinten nicht.',
        65: 'Da erwachte Adonái wie vom Schlaf, / Wie ein Held, dessen Mut der Wein gestärkt.',
        66: 'Er schlug seine Feinde zurück, / Tat ihnen ewige Schande an.',
        67: 'Josefs Zelt verwarf er zwar, / Und Efraims Stamm erwählte er nicht.',
        68: 'Sondern Judas Stamm erkor er, / Den Zionsberg, den er liebgewonnen.',
        69: 'Er baute hochragend sein Heiligtum, / Wie die Erde, die er auf ewig gegründet.',
        70: 'Er erwählte sich David, seinen Knecht, / Nahm ihn von den Hürden der Schafe.',
        71: 'Von den säugenden Schafen holte er ihn, / Daß er weide Jakob, sein Volk, / Und sein Erbteil Israel.',
        72: 'Er weidete sie auch mit lauterm Sinn / Und führte sie klug mit seiner Hand.',
    },
    79: {
        1: 'Ein Psalm Asafs. / Elohim, es sind Heiden in dein Erbe gedrungen, / Die haben deinen heiligen Tempel entweiht, / In Trümmer verwandelt Jerusalem.',
        2: 'Sie haben deiner Knechte Leichen / Des Himmels Vögeln zum Fraß gegeben. / Deiner Frommen Fleisch des Landes Getier.',
        3: 'Sie haben ihr Blut vergossen wie Wasser / Rings um Jerusalem her, und niemand begrub (die Toten).',
        4: 'Wir sind unsern Nachbarn zur Schmach geworden, / Ein Spott und Gelächter für unsre Umgebung.',
        5: 'Wie lange, Jahwe, wirst du noch zürnen, / Wird dein Eifer wie Feuer brennen?',
        6: 'Gieß deine Zornglut über die Heiden, die dich nicht erkannt, / Über die Reiche, die deinen Namen nicht angerufen.',
        7: 'Denn sie haben Jakob verzehrt / Und seinen Wohnsitz verwüstet.',
        8: 'Rechne uns nicht der Vorfahren Sünden zu! / Eilends komm uns dein Erbarmen entgegen! / Denn wir sind sehr gebeugt.',
        9: 'Hilf uns, Gott, du Quell unsers Heils. / Um deines Namens Ehre willen! / Rett uns, bedeck unsre Missetaten / Um deines Namens willen!',
        10: 'Warum sollen die Heiden sagen: / "Wo ist nun ihr Gott?" / Kund werde an den Heiden vor unsern Augen / Die Rache für deiner Knechte Blut, das sie vergossen!',
        11: 'Der Gefangenen Seufzen komme vor dich! / Mit deinem starken Arm / Erhalte die Kinder des Todes am Leben!',
        12: 'Und vergilt unsern Nachbarn siebenfach in ihren Busen / Ihr Schmähn, womit sie dich, Adonái, geschmäht!',
        13: 'Wir aber, dein Volk, deiner Weide Schafe, / Wir wollen dir ewig danken, / Von Geschlecht zu Geschlecht deinen Ruhm verkünden.',
    },
    80: {
        1: 'Dem Sangmeister, nach (der Weise von:) "(Wie) Lilien ist das Zeugnis." / Ein Psalm Asafs.',
        2: 'Israels Hirt, horch auf, / Der du Josef führtest wie Schafe! / Der du thronest auf den Keruben, / Erscheine im Lichtglanz!',
        3: 'Efraim, Benjamin und Manasse siegreich führend / Biete auf deine Macht / Und komm uns zu Hilfe!',
        4: 'Elohim, stell uns wieder her! / Laß leuchten dein Antlitz, so wird uns geholfen!',
        5: 'Jahwe Elohim Zebaôt, / Wie lange währet dein Zorn / Trotz des Gebetes deines Volks?!',
        6: 'Du hast es mit Tränenbrot gespeist / Und es mit Tränen reichlich getränkt.',
        7: 'Unsre Nachbarn streiten sich unsertwegen, / Und unsre Feinde verspotten uns.',
        8: 'Elohim Zebaôt, stell uns wieder her! / Laß leuchten dein Antlitz, so wird uns geholfen!',
        9: 'Einen Weinstock hast du aus Ägypten geholt, / Hast Völker vertrieben und ihn gepflanzt.',
        10: 'Du hast vor ihm Raum geschafft: / So schlug er Wurzeln und füllte das Land.',
        11: 'Es deckten sich Berge mit seinem Schatten, / Mit seinen Reben die Zedern Gottes.',
        12: 'Seine Ranken sandte er bis ans Meer / Und seine Zweige bis an den Strom.',
        13: 'Warum hast du denn seinen Zaun zerbrochen, / Daß ihn jeder zerpflückt, der vorübergeht?',
        14: 'Der Eber des Waldes frißt ihn ab, / Das Getier des Feldes macht ihn kahl.',
        15: 'Elohim Zebaôt, o schau doch wieder vom Himmel und sieh — / Sorge für diesen Weinstock:',
        16: 'Für den Sprößling, den deine Rechte gepflanzt, / Für den Sohn, den du dir erzogen!',
        17: 'Wie ist er mit Feuer verbrannt. / Vor deinem Zornblick laß sie vergehn!',
        18: 'Deine Hand sei über dem Mann deiner Rechten, / Dem Menschensohn, den du dir erzogen:',
        19: 'So werden wir nimmer von dir weichen. / Laß uns am Leben, so rufen wir an deinen Namen. Jahwe Elohim Zebaôt, stell uns wieder her! / Laß leuchten dein Antlitz, so wird uns geholfen!',
    },
    81: {
        1: 'Dem Sangmeister, auf der Gittit. Von Asaf.',
        2: '(Der levitische Sängerchor:) / Laßt Jubel erschallen Elohim, unserm Hort, / Jauchzet dem Gotte Jakobs!',
        3: 'Stimmt an Gesang, laßt tönen die Pauke, / Die liebliche Zither und Harfe!',
        4: 'Blaset am Neumond das Widderhorn, / Beim Vollmond, für unsern Feiertag!',
        5: 'Denn so ist es Satzung für Israel, / Eine Vorschrift des Gottes Jakobs.',
        6: "Als Gebot hat er's für Josef bestimmt, / Da er auszog wider Ägyptenland. / (Eine Einzelstimme:) / Eine Sprache, mir fremd, vernehm ich:",
        7: '"Seinen Nacken hab ich von der Bürde befreit, / Seine Hände wurden des Lastkorbs ledig.',
        8: 'Du riefst in der Not, ich riß dich heraus, / Erhörte dich aus Gewittergewölk, / Prüfte dich an Meribas Wassern. Sela.',
        9: 'Höre, mein Volk, ich will dich warnen! / Israel, möchtest du mir gehorchen!',
        10: 'Nicht sei unter dir ein fremder Gott; / Bete nicht an einen Gott des Auslands!',
        11: 'Ich, Jahwe, bin dein Gott, / Der dich geführt aus Ägyptenland: / Tu deinen Mund weit auf, / Damit ich ihn fülle!',
        12: 'Aber mein Volk gehorchte mir nicht, / Israel war mir nicht zu Willen.',
        13: 'Da stieß ich sie weg, weil ihr Herz so verstockt, / Daß sie folgten den eignen Gedanken.',
        14: 'O daß doch mein Volk mir gehorchte, / Daß Israel ginge auf meinen Wegen!',
        15: 'Wie leicht könnt ich da ihre Feinde beugen, / Meine Hand gegen ihre Dränger kehren.',
        16: 'Ihnen müßten schmeicheln, die Jahwe hassen, / Und ewig würde währen ihr Glück. Mit dem besten Weizen würd ich sie speisen, / Mit Honig aus Felsen dich sättigen."',
    },
    82: {
        1: 'Ein Psalm Asafs. / Elohim tritt auf in der Gottesgemeinde, / Unter den "Göttern" hält er Gericht:',
        2: '"Wie lange wollt ihr ungerecht richten / Und Partei für die Frevler nehmen? Sela.',
        3: 'Des Geringen, der Waise nehmt euch an, / Dem Gedrückten und Dürftigen schaffet Recht!',
        4: 'Befreit den Geringen und Armen, / Aus der Frevler Händen errettet ihn!',
        5: "Doch sie erkennen's nicht, sehen's nicht ein, / Sie gehen verblendet dahin — / Drum wanken auch alle Grundfesten des Landes.",
        6: "Ich hab zwar gesagt: 'Götter seid ihr / Und Söhne des Höchsten ihr alle.'",
        7: 'Doch wahrlich, wie Menschen werdet ihr sterben, / Fallen wie einer der Fürsten."',
        8: 'Auf, Elohim, richte die Erde! / Denn alle Völker sind dein Besitz.',
    },
    83: {
        1: 'Ein Lied. Ein Psalm Asafs.',
        2: 'Elohim, schaue nicht ruhig zu, / Schweige doch nicht und raste nicht, Gott!',
        3: 'Denn sieh, deine Feinde toben, / Und deine Hasser erheben das Haupt.',
        4: 'Wider dein Volk ersinnen sie listigen Anschlag, / Beraten sich gegen die, die du bewahrst.',
        5: '"Auf", sagen sie, "laßt uns als Volk sie vernichten, / Daß Israels Name für immer verschwinde!"',
        6: 'Denn einmütig haben sie sich beraten, / Wider dich einen Bund geschlossen:',
        7: 'Edoms Zelte, die Ismaeliter, / Moab und die Hagriter,',
        8: 'Gebâl und Ammon und Amalek, / Die Philister samt denen zu Tyrus.',
        9: 'Auch Assur hat sich zu ihnen gesellt, / Es leiht seinen Arm den Söhnen Lots. Sela.',
        10: 'Tu ihnen so wie Midian, / Wie Sisera, wie Jabin am Bache Kison!',
        11: 'Sie wurden bei Endor vertilgt, / Wurden Dünger auf Ackerland.',
        12: 'Ihre Edlen mache wie Oreb und Seeb, / wie Sébach und Zalmúnna all ihre Fürsten,',
        13: 'Weil sie gesprochen: "Wir wollen für uns / Einnehmen die Auen Gottes."',
        14: 'Mein Gott, mache sie wie Laub, / Wie Stoppeln, die der Wind wegtreibt,',
        15: 'Wie Feuer, das einen Wald verbrennt, / Wie die Flamme, die Berge entzündet!',
        16: 'Verfolge sie so mit deinem Sturm, / Und mit deiner Windsbraut schrecke sie!',
        17: 'Mach ihr Antlitz voll Schmach, / Damit sie nach deinem Namen fragen, o Jahwe!',
        18: 'Sie sollen zuschanden werden, erschrecken für immer, / Erröten vor Scham und vergehen! Dann laß sie erkennen, daß du, des Name Jahwe heißt, / Allein der Höchste bist auf der ganzen Erde.',
    },
    84: {
        1: 'Dem Sangmeister, auf der Gittit. Ein Psalm der Söhne Korahs.',
        2: 'Wie lieblich ist deine Wohnung, / Jahwe, der Heerscharen Herr!',
        3: 'Meine Seele hat sich schon immer gesehnt, ja geschmachtet / Nach den Vorhöfen Jahwes. / Mein Herz und mein Leib / Jubeln entgegen dem lebendigen Gott.',
        4: 'Auch der Sperling findet ein Haus / Und die Schwalbe ein Nest, wo sie ihre Jungen birgt: / Deine Altäre, Jahwe, der Heerscharen Herr, / Mein König und mein Gott.',
        5: 'Heil den Bewohnern deines Hauses: / Sie loben dich immerdar! Sela.',
        6: 'Heil denen, die in dir ihre Stärke finden, / Während sie Pläne im Herzen bewegen!',
        7: 'Wandern sie durch ein dürres Tal: / Sie machen es zum Quell; / Auch hüllt es Frühregen in Segen.',
        8: 'Sie schreiten von Kraft zu Kraft: / So zeigt sich El Elohim, / Der da wohnet in Zion.',
        9: 'Jahwe Elohim Zebaôt, / Erhöre doch mein Gebet, / Merke darauf, Gott Jakobs! Sela.',
        10: 'Du, unser Schild, sieh drein, Elohim, / Schau gnädig an das Antlitz deines Gesalbten!',
        11: 'Denn ein Tag in deinen Vorhöfen ist besser als tausend andre. / Lieber will ich in meines Gottes Haus an der Schwelle stehn / Als in den Zelten des Frevlers wohnen.',
        12: 'Denn Zinne und Schild ist Jahwe Elohim. / Gunst und Ehre wird Jahwe geben; / Nicht läßt er Gutes mangeln / Denen, die schuldlos wandeln. Jahwe, der Heerscharen Herr, / Heil dem Menschen, der dir vertraut!',
    },
    85: {
        1: 'Dem Sangmeister. Ein Psalm der Söhne Korahs.',
        2: 'Du hast zwar, Jahwe, dein Land begnadigt, / Jakobs Gefangne zurückgeführt;',
        3: 'Du hast deines Volkes Schuld vergeben, / All seine Sünde zugedeckt; Sela.',
        4: 'Hast all deinen Grimm zurückgezogen, / Von deiner Zornglut abgelassen:',
        5: 'So stell uns nun aber auch wieder her, du Gott unsers Heils, / Gib auf deinen Unmut gegen uns!',
        6: 'Willst du denn ewig über uns zürnen, / Deinen Grimm hinziehn von Geschlecht zu Geschlecht?',
        7: 'Willst du uns denn nicht wieder beleben, / Daß sich dein Volk erfreue an dir?',
        8: 'Laß, Jahwe, uns deine Gnade schaun, / Und deine Hilfe schenke uns!',
        9: 'Ich will lauschen auf das, was El Jahwe nun reden wird! — / Wahrlich, Frieden verheißt er seinem Volk und seinen Getreuen / Und warnt sie, nicht wieder in Torheit zu fallen.',
        10: 'Gewiß, nah ist den Frommen sein Heil, / Daß Herrlichkeit wohne in unserm Land,',
        11: 'Daß Huld und Treue einander begegnen, / Gerechtigkeit und Friede sich küssen.',
        12: 'Treue wird aus der Erde sprossen, / Und Gerechtigkeit schaut vom Himmel herab.',
        13: 'Jahwe wird auch das Gute spenden, / Und unser Land gibt seinen Ertrag. Gerechtigkeit wird vor ihm schreiten / Und ihn begleiten auf seinen Tritten.',
    },
    86: {
        1: 'Ein Gebet Davids. / Neige, Jahwe, dein Ohr, erhöre mich, / Denn ich bin elend und arm!',
        2: 'Behüte mein Leben, denn ich bin fromm. / Hilf du, mein Gott, deinem Knechte, / Der sich auf dich verläßt!',
        3: 'Sei du, Adonái, mir gnädig, / Denn zu dir ruf ich den ganzen Tag!',
        4: 'Deines Knechtes Seele erfreue, / Denn zu dir, Adonái, erheb ich mein Herz.',
        5: 'Denn du, Adonái, bist gütig, verzeihest gern, / Bist reich an Gnade für alle, die zu dir rufen.',
        6: 'Vernimm doch, Jahwe, mein Beten; / Horch auf mein lautes Flehn!',
        7: 'Bin ich in Not, so ruf ich dich an, / Weil du mich erhörst.',
        8: 'Dir, Adonái, gleicht keiner unter den Göttern, / Und deinen Werken kommt nichts gleich,',
        9: 'Alle Völker, die du gemacht, sie müssen kommen, / Vor dir, Adonái, sich bücken / Und deinen Namen ehren.',
        10: 'Denn du bist groß und wundertätig, / du, du allein bist Gott.',
        11: 'Lehre mich, Jahwe, deinen Weg! / Dir treu und ergeben: so möchte ich wandeln. / Richte mein Herz auf das Eine: / Deinen Namen zu fürchten.',
        12: 'Danken will ich dir, Adonái, mein Gott, von ganzem Herzen — / Und deinen Namen für immer ehren.',
        13: 'Denn deine Huld gegen mich war reich: / Aus größter Todesgefahr hast du mich errettet.',
        14: 'Elohim, es haben sich Frevler erhoben wider mich, / Und eine Rotte von Schreckensmännern trachtet mir nach dem Leben; / Sie haben dich nicht vor Augen.',
        15: 'Aber du, Adonái, bist ein barmherziger, gnädiger Gott, / Langmütig und reich an Huld und Treu.',
        16: 'Wende dich zu mir und sei mir gnädig, / Verleih deinen Schutz deinem Knecht / Und hilf doch dem Sohn deiner Magd!',
        17: 'Tu ein Zeichen an mir zum Guten, / Daß meine Hasser voll Scham es sehn, / Weil du mir geholfen, o Jahwe, und mich getröstet.',
    },
    87: {
        1: 'Ein Psalmlied der Söhne Korahs. / Er hat es gegründet auf heiligen Bergen.',
        2: 'Zions Tore liebt Jahwe mehr / Als alle Wohnungen Jakobs.',
        3: 'Herrliches ist über dich verheißen, / O du Stadt Elohims. Sela.',
        4: '"Ich nenne Rahab und Babel als meine Bekenner. / Ja, von Philistäa und Tyrus samt Kusch sag ich: / [\'Diese sind dort geborn.\'"',
        5: 'Aber von Zion wird\'s heißen: / "Jeder ist da geboren, / Und er selbst, der Höchste, erhält es."',
        6: 'Jahwe wird verzeichnen die Völker: / "Diese sind dort geboren!" Sela.',
        7: 'Und singend und tanzend ruft man laut: / "All meine Quellen sind in dir!"',
    },
    88: {
        1: 'Ein Psalm der Söhne Korahs. Dem Sangmeister, nach schwermütiger Weise mit gedämpfter Stimme vorzutragen (?): eine Betrachtung (?) Hemans, des Esrahiters.',
        2: 'Jahwe, du Gott meines Heils, / Tagsüber hab ich schon immer geschrien, / Des Nachts liege ich vor dir.',
        3: 'Mein Gebet möge vor dich kommen! / Neige dein Ohr meinem lauten Flehn!',
        4: 'Denn mit Leiden bin ich gesättigt, / Und mein Leben ist nahe dem Totenreich.',
        5: 'Man zählt mich schon denen zu, die in die Grube hinunterfahren; / Ich bin wie ein Mann ohne Lebenskraft.',
        6: 'Unter den Toten ist mein Lager; / Ich gleiche Erschlagnen, die im Grabe ruhn, / Deren du nicht mehr gedenkst — / Sie sind ja getrennt von deiner Hand.',
        7: 'Du hast mich gelegt in die unterste Grube, / In dichte Finsternis und in die Tiefen.',
        8: 'Auf mir lastet dein Grimm; / All deine Wogen drücken mich nieder. Sela.',
        9: 'Meine Freunde hast du von mir entfernt, / Du hast mich ihnen zum Abscheu gemacht. / Ich bin eingeschlossen, kann nicht hinaus.',
        10: 'Mein Auge verschmachtet vor Elend. / Ich rufe dich, Jahwe, tagtäglich an, / Breite zu dir meine Hände aus:',
        11: 'Tust du denn für die Toten Wunder? / Erheben sich Schatten, um dir zu danken? Sela.',
        12: 'Erzählt man im Grabe von deiner Güte, / Von deiner Treue im Totenreich?',
        13: 'Wird in der Finsternis dein Wunderwalten kund / Und deine Gerechtigkeit im Land des Vergessens?"',
        14: 'Ich aber schreie, o Jahwe, zu dir, / Schon morgens begrüßt dich mein Gebet:',
        15: '"Warum denn, Jahwe, verwirfst du mich, / Verhüllest vor mir dein Angesicht?"',
        16: 'Ich bin ja so elend: hinsterbend von Jugend auf. / Das schreckliche Los, das du mir bestimmt, / Ich hab es ertragen — nun bin ich erschöpft!',
        17: 'Deine Zornesgluten gehn über mich; / Es vernichten mich deine Schrecken.',
        18: 'Wie Wasser umgeben sie mich allezeit, / Umringen mich allzumal. Du hast alle Lieben von mir entfernt, / Mir bleibt als Freund nur — die Finsternis!',
    },
    89: {
        1: 'Eine Betrachtung (?) Etans, des Esrahiters.',
        2: 'Jahwes Gnaden will ich ewig besingen, / Für und für deine Treue verkünden.',
        3: 'Denn ich sage: Der Gnadenbau währet für immer, / Am Himmel befestigst du deine Treu.',
        4: '"Ich schloß einen Bund mit meinem Erwählten, / Hab meinem Knechte David geschworen:',
        5: 'Auf ewig laß ich deinen Samen bestehn, / Deinen Thron will ich baun für alle Geschlechter." Sela.',
        6: 'Da priesen die Himmel, o Jahwe, dein Wunder, / Deine Treu in der Heilgen Versammlung.',
        7: 'Denn wer in den Wolken ist Jahwe ähnlich, / Wer gleicht ihm unter den Gottessöhnen?',
        8: 'Man fürchtet Gott sehr in der Heiligen Rat; / Es scheuen ihn alle, die um ihn sind.',
        9: 'Jahwe, der Heerscharen Gott, wer ist wie du? / Jah, du bist stark, / Und deine Treue ist um dich her.',
        10: 'Du bändigst des Meeres Stolz; / Wenn sich seine Wogen türmen — du stillest sie.',
        11: 'Du hast ja Rahab zermalmt wie einen Durchbohrten, / Mit deinem starken Arm hast du deine Feinde zerstreut.',
        12: 'Dein ist der Himmel, dein auch die Erde; / Die Welt und was sie füllet — du hast sie gegründet.',
        13: 'Norden und Süden — du hast sie geschaffen. / Tabor und Hermon jauchzen ob deines Namens.',
        14: 'Dein ist ein Arm mit Heldenkraft. / Mächtig ist deine Hand, deine Rechte erhaben.',
        15: 'Gerechtigkeit und Recht sind deines Thrones Stützen, / Gnade und Treue gehn vor dir her.',
        16: 'Heil dem Volke, das Jubel kennt, / Das im Licht deines Angesichts wandelt, o Jahwe!',
        17: 'Ob deines Namens werden sie allzeit jubeln, / Und durch deine Treue stehen sie aufrecht da.',
        18: 'Denn du gibst die Kraft, die sie schmückt, / Durch deine Huld machst du uns mächtig.',
        19: 'Denn von Jahwe kommt unser Schutz, / Und der Heilige Israels schirmt unsern König.',
        20: 'Damals hast du im Gesicht gesprochen zu deinen Vertrauten: / Ich habe einem Helden Beistand geliehn, / Einen Jüngling erhöht aus dem Volk.',
        21: 'Meinen Knecht David hab ich gefunden, / Mit meinem heilgen Öl ihn gesalbt.',
        22: 'Meine Hand soll ihn stützen, / Auch mein Arm ihn stärken.',
        23: 'Kein Feind darf ihn unversehns überfallen, / Kein Frevler ihn drücken.',
        24: 'Seine Dränger will ich vor ihm zerschmettern, / Und, die ihn hassen, schlagen.',
        25: 'Ihn aber soll meine Treue und Gnade begleiten, / Und durch meinen Namen wird groß seine Macht.',
        26: 'Seine Hand will ich legen aufs Meer / Und auf die Ströme seine Rechte.',
        27: "Er wird zu mir sprechen: 'Mein Vater bist du, / Mein Gott und der Hort, der mir hilft.'",
        28: 'Und ich will ihn machen zum Erstgebornen, / Zum höchsten der Könige auf Erden.',
        29: 'Auf ewig will ich ihm meine Huld bewahren, / Und es bleibt mein Bund ihm getreu.',
        30: 'Seine Nachkommen will ich für immer erhalten, / Seinen Thron, solange der Himmel währt.',
        31: 'Verlassen seine Söhne mein Gesetz, / Und wandeln sie nicht nach meinen Rechten,',
        32: 'Entweihen sie meine Satzungen, / Und halten sie meine Gebote nicht:',
        33: 'So straf ich zwar mit dem Stab ihre Vergehn / Und ihre Verschuldung mit Schlägen;',
        34: 'Meine Huld aber werd ich ihm nicht entziehn / Und meine Treue nicht brechen.',
        35: 'Ich will meinen Bund nicht entweihn / Und meiner Lippen Versprechen nicht ändern.',
        36: 'Eins hab ich geschworen bei meiner Heiligkeit: / David werd ich wahrlich nicht lügen.',
        37: 'Seine Nachkommen sollen ewig bleiben, / Sein Thron vor mir stehn so lang wie die Sonne,',
        38: 'Wie der Mond, der für immer bleibt / Als ein dauernder Zeuge in dem Gewölk." Sela.',
        39: 'Und dennoch hast du verschmäht und verworfen! / Du hast über deinen Gesalbten gezürnt,',
        40: 'Hast aufgehoben den Bund mit deinem Knecht, / Seine Krone entweiht und zu Boden geworfen.',
        41: 'Du hast all seine Mauern zerrissen, / Seine Festen in Trümmer gelegt.',
        42: 'Alle, die des Weges zogen, haben ihn geplündert, / Er ist seinen Nachbarn zum Hohn geworden.',
        43: 'Seiner Dränger Macht hast du erhöht, / Hast all seine Feinde mit Freude erfüllt.',
        44: 'Auch hast du zurückgedrängt sein scharfes Schwert / Und ihm im Kriege nicht Sieg verliehn.',
        45: 'Du hast seinen Glanz zerstört / Und seinen Thron zu Boden gestürzt.',
        46: 'Du hast die Zeit seiner Jugend verkürzt, / Ihn mit Schande bedeckt. Sela.',
        47: 'Wie lange, Jahwe, willst du dich verbergen? Etwa für immer? / Soll denn dein Grimm wie Feuer brennen?',
        48: 'Gedenke, wie kurz mein Leben ist, / Wie vergänglich du schufst alle Menschenkinder!',
        49: 'Wer bliebe am Leben und stürbe nicht, / Wer könnte entrinnen des Todes Macht? Sela.',
        50: 'Wo sind, Adonái, deine frühern Gnaden, / Die du David geschworen in deiner Treu?',
        51: 'Gedenk, Adonái, deiner Knechte Schmach! / Gedenke, daß ich in meinem Busen / Trage die vielen Völker alle!',
        52: 'Gedenke, Jahwe, wie deine Feinde gelästert haben, / Wie sie gelästert / Deines Gesalbten Fersen! Gepriesen sei Jahwe in Ewigkeit! / Amen. Amen.',
    },
    90: {
        1: 'Ein Gebet Moses, des Mannes Gottes. / Adonái, du bist uns Zuflucht gewesen in allen Geschlechtern.',
        2: 'Eh Berge entstanden, / Eh Erd und Weltkreis geschaffen wurden, / Warst du schon da, o Gott; / Ja, von Ewigkeit bist du und bleibst in Ewigkeit.',
        3: 'Du wandeltest die Sterblichen in Staub / Und sprachst: "Kehrt wieder, ihr Menschenkinder!"',
        4: 'Denn in deinen Augen sind tausend Jahre / Wie der gestrige Tag, wenn er entschwindet, / Wie eine Wache in der Nacht.',
        5: 'Du hast sie weggeschwemmt wie Morgenschlaf. / Sie glichen dem sprossenden Gras:',
        6: "Am Morgen blüht es und sprosset neu, / Am Abend schneidet man's, und es verdorrt.",
        7: 'Denn geschwunden sind wir durch deinen Zorn, / Hinweggeschreckt durch deinen Grimm.',
        8: 'Du hast unsre Sünde vor dich gestellt, / Unser heimlich Tun in das helle Licht, / Das von deinem Antlitz strahlet.',
        9: 'So sind all unsre Tage dahingefahren durch deinen Zorn, / Unsre Jahre haben wir zugebracht / Wie einen flüchtigen Gedanken.',
        10: "Unsre Lebenszeit — bei ihnen währet sie siebzig Jahr, / Und haben sie starke Lebenskraft, so sind es achtzig Jahr. / Und was sie mit Stolz erfüllte, das war nur Mühsal und Unglück. / Denn schnell ist's enteilt — wir flogen!",
        11: 'Doch wer erkennt deines Zornes Gewalt / Und deinen Grimm, indem man dich fürchtet?',
        12: 'So lehr uns denn unsre Tage zählen, / Damit wir gewinnen ein weises Herz!',
        13: 'Wende dich, Jahwe (von deinem Zorn)! / Wie lange noch (soll er währen)? / Erbarme dich deiner Knechte!',
        14: 'Füll uns am Morgen mit deiner Gnade, / So wollen wir all unsre Lebenstage / Jubeln und fröhlich sein!',
        15: 'Erfreu uns so lange, wie du uns gebeugt, / So viel Jahre wir Unglück geschaut!',
        16: 'Deinen Knechten erscheine dein herrliches Tun / Und deine Hoheit ihren Kindern!',
        17: 'Jahwes, unsers Gottes, Huld walte über uns, / Ja, fördre das Werk unsrer Hände!',
    },
    91: {
        1: 'Erste Stimme: / Unter dem Schutze des Höchsten wohnend, / In des Allmächtigen Schatten weilend —',
        2: 'Sprech ich zu Jahwe: "Meine Zuflucht und Burg, / Mein Gott, auf den ich vertraue!"',
        3: 'Zweite Stimme: / Denn er wird dich erretten von des Voglers Strick, / Von der verderblichen Pest.',
        4: 'Mit seiner Schwinge decket er dich, / Unter seinen Flügeln bist du geborgen. / Schild und Panzer ist seine Treu.',
        5: 'Du hast nicht zu fürchten die Schrecken der Nacht, / Den Pfeil, der am Tage daherfliegt,',
        6: 'Auch nicht die Pest, die im Dunkeln schleicht, / Noch die Seuche, die wütet am Mittag.',
        7: 'Wenn tausend an deiner Seite fallen / Und zehntausend zu deiner Rechten: / Du wirst nicht getroffen.',
        8: 'Nur mit deinen Augen schauest du hin / Und wirst sehn die Vergeltung der Frevler.',
        9: 'Erste Stimme: / Ja, du, o Jahwe, bist meine Zuversicht. / Zweite Stimme: / Den Höchsten hast du zur Zuflucht erwählt.',
        10: 'Nicht wird dir ein Unglück begegnen, / Keine Plage wird deinem Zelte nahn.',
        11: 'Denn seine Engel wird er dir entbieten, / Dich zu behüten auf all deinen Wegen.',
        12: 'Sie werden dich auf den Händen tragen, / Damit sich dein Fuß nicht stoße am Stein.',
        13: 'Über Löwen und Ottern wirst du schreiten, / Zertreten Jungleuen und Schlangen.',
        14: 'Dritte Stimme (die im Namen Gottes redet): / Weil er mich liebt, will ich ihn befrein. / Ich will ihn schützen, weil er meinen Namen kennt.',
        15: 'Er ruft mich an, ich erhör ihn. / Ich werde mit ihm in Drangsal sein; / Ich reiß ihn heraus und bring ihn zu Ehren.',
        16: 'Mit langem Leben sättige ich ihn / Und will ihn schauen lassen mein Heil.',
    },
    92: {
        1: 'Ein Psalm. Ein Lied für den Sabbattag.',
        2: 'Köstlich ist es, Jahwe zu danken / Und deinem Namen, o Höchster, zu spielen,',
        3: 'Am Morgen deine Huld zu verkünden / Und deine Treu in den Nächten,',
        4: 'Zum Zehnsait und zur Harfe, / Zum rauschenden Spiel auf der Zither.',
        5: 'Denn du, Jahwe, hast mich erfreut durch dein Walten, / Deiner Hände Werke lassen mich jauchzen.',
        6: 'Wie herrlich, Jahwe, sind deine Taten, / Wie tief sind deine Gedanken!',
        7: 'Nur ein geistloser Mensch erkennt das nicht, / Nur ein Törichter sieht es nicht ein.',
        8: 'Sprießen die Frevler auch auf wie Gras, / Blühen auch alle die Übeltäter — / Vernichtet werden sie doch auf immer!',
        9: 'Du aber, Jahwe, bist ewig erhaben!',
        10: 'Denn sieh, deine Feinde, Jahwe, / Sieh, deine Feinde müssen vergehn, / Sich zerstreun alle Übeltäter.',
        11: 'Mir aber hast du die Kraft des Büffels gegeben, / Ich bin übergossen mit frischem Öl.',
        12: 'Mit Lust hat mein Aug meine Laurer geschaut, / Meiner Feinde Vernichtung vernahm mit Freude mein Ohr.',
        13: 'Der Gerechte wird sprossen wie eine Palme, / Wie eine Zeder des Libanons wachsen.',
        14: 'Gepflanzt im Hause Jahwes, / Blühn sie in unsers Gottes Höfen.',
        15: 'Sie tragen noch Frucht im Greisenalter, / Saftvoll werden sie sein und frisch, Um zu verkünden: Gerecht ist Jahwe, / Mein Fels, an dem sich kein Tadel findet.',
    },
    93: {
        1: 'Jahwe herrscht nun als König, er hat sich mit Hoheit umkleidet, / Jahwe hat sich umkleidet, mit Macht sich gegürtet. / So steht nun der Erdkreis fest und wanket nicht.',
        2: 'Fest steht dein Thron von alters her, / Seit Ewigkeit bist du!',
        3: 'Zwar haben Ströme, Jahwe, erhoben, / Ströme haben erhoben ihr Brausen; / Auch ferner noch werden Ströme ihr Tosen erheben:',
        4: 'Doch größer als vieler mächtiger Wasser Gebraus, / Als des Meeres brandende Wogen / Ist Jahwe droben in Himmelshöhn!',
        5: 'Was du verordnet, ist unverbrüchlich. / Deinem Hause ziemt Heiligkeit, / Jahwe, für ewige Zeiten.',
    },
    94: {
        1: 'Gott, der du Vergeltung übst, o Jahwe, / Gott, der du Vergeltung übst, erscheine im Lichtglanz!',
        2: 'Erhebe dich, Richter der Erde, / Vergilt den Stolzen nach ihrem Tun!',
        3: 'Wie lange, Jahwe, sollen die Frevler, / Wie lange sollen die Frevler jauchzen?',
        4: 'Sie stoßen trotzige Reden aus, / Alle Übeltäter prahlen.',
        5: 'Dein Volk, o Jahwe, zertreten sie, / Und sie bedrücken dein Erbe.',
        6: 'Witwen und Fremdlinge würgen sie, / Und sie morden die Waisen.',
        7: 'Dabei denken sie noch: "Jah siehet es nicht." / Und: "Der Gott Jakobs beachtet es nicht."',
        8: 'Merkt doch auf, ihr Toren im Volk, / Und ihr Narren — wann werdet ihr klug?',
        9: 'Der das Ohr gepflanzt — er sollte nicht hören? / Oder der das Auge gebildet, sollte nicht sehn?',
        10: 'Der Völker erziehet, sollte nicht strafen — / Er, der die Menschen Erkenntnis lehrt?',
        11: 'Jahwe kennt der Menschen Gedanken, / Er weiß: Sie sind nichts als leerer Wahn.',
        12: 'Heil dem, den du zurechtweist, Jah, / Den du aus deinem Gesetze belehrst,',
        13: 'Daß er ruhig bleibe in Unglückstagen, / Wenn dem Frevler die Grube gegraben wird.',
        14: 'Denn nicht verstoßen wird Jahwe sein Volk / Und sein Erbe nimmer verlassen.',
        15: 'Denn das Recht wird zuletzt doch gerecht gehandhabt, / Und alle Redlichen werden das freudig begrüßen.',
        16: 'Wer wird mir beistehn gegen die Frevler, / Wer tritt für mich ein wider Übeltäter?',
        17: 'Wäre nicht Jahwe mein Helfer gewesen — / Ich läge beinahe in Todesstille.',
        18: 'Wenn ich dachte: "Es wankt mein Fuß", / So sützte mich, Jahwe, deine Hand.',
        19: 'Wenn die Sorgen sich türmten in meinem Herzen, / Hast du mich mit deinem Troste erquickt.',
        20: 'Hat Gemeinschaft mit dir der verderbliche Stuhl, / Der Unheil schmiedet "nach dem Gesetz"?',
        21: 'Sie bedrohten schon oft des Gerechten Leben / Und sprachen Unschuldige schuldig.',
        22: 'Doch Jahwe ward mir zur festen Burg, / Mein Gott zum schützenden Fels.',
        23: 'Ihren Frevel hast du ihnen heimgezahlt. / Ob ihrer Bosheit vernichtet er sie, / Es vernichtet sie Jahwe, unser Gott.',
    },
    95: {
        1: 'Auf, laßt uns Jahwe frohlocken, / Entgegenjauchzen dem Fels unsers Heils!',
        2: 'Laßt uns mit Dank vor sein Antlitz treten, / In Lobgesängen ihm jubeln!',
        3: 'Denn ein großer Gott ist Jahwe, / Ein großer König über alle Götter.',
        4: 'In seiner Hand sind der Erde Tiefen, / Und sein sind die Gipfel der Berge.',
        5: 'Sein ist das Meer, er hat es geschaffen, / Auch das Festland haben seine Hände gebildet.',
        6: 'Kommt, laßt uns anbeten und niederfallen, / Knien vor Jahwe, der uns erschaffen!',
        7: 'Denn er ist unser Gott, / Und wir sind das Volk, das er weidet, / Die Herde, die er leitet mit seiner Hand, / Wenn ihr heut seiner Stimme gehorcht.',
        8: '"Verstockt doch nicht euer Herz, wie bei Merîba, / Wie am Tage von Massa in der Wüste,',
        9: 'Wo eure Väter mich versuchten, / Mich prüften, obwohl sie mein Tun gesehn.',
        10: "Vierzig Jahre war mir dies Geschlecht zuwider. / Ich sprach: 'Ein irrendes Volk sind sie, / Das meine Wege nicht erkannt.'",
        11: 'Drum schwur ich in meinem Zorn: / \'Wahrlich, sie sollen nicht kommen / Zu der Ruhstatt, die ich ihnen verheißen.\'"',
    },
    96: {
        1: 'Singet Jahwe ein neues Lied, / Singt Jahwe, all ihr Erdbewohner!',
        2: 'Singt Jahwe, preist seinen Namen, / Verkündet tagtäglich sein Heil!',
        3: 'Erzählt auch unter den Heiden von seiner Herrlichkeit, / Unter allen Völkern von seinen Wundertaten!',
        4: 'Denn groß ist Jahwe und hoch zu preisen, / Mehr zu fürchten als alle Götter.',
        5: 'Denn alle Götter der Völker sind nichtig, / Aber Jahwe hat die Himmel geschaffen.',
        6: 'Glanz und Pracht gehn vor ihm her, / Macht und Schmuck erfüllen sein Heiligtum.',
        7: 'Bringt Jahwe, ihr Völkergeschlechter, / Bringt Jahwe Ehre und Preis!',
        8: 'Bringt Jahwe dar seines Namens Ruhm, / Nehmt Opfergaben und kommt in seine Vorhöfe!',
        9: 'Werft euch nieder vor Jahwe in heiligem Schmuck, / Erbebt vor ihm, alle Lande!',
        10: 'Ruft unter den Heiden: "Jahwe herrscht nun als König! / Auch wird der Erdkreis feststehn ohne Wanken; / Er wird die Völker gerecht regieren."',
        11: 'Drum mögen sich freuen die Himmel, / Die Erde frohlocke, / Es brause das Meer und was darin wohnt!',
        12: 'Das Gefilde jauchze und was darauf lebt! / Dann sollen auch jubeln alle Bäume im Wald',
        13: 'Vor der Nähe Jahwes, wenn er nun kommt, / Wenn er kommt, um die Erde zu richten. / Richten wird er die Welt gerecht / Und die Völker nach seiner Treue.',
    },
    97: {
        1: 'Jahwe herrscht nun als König: drob jauchze die Erde, / Es mögen sich auch viele Inseln freun!',
        2: 'Gewölk und Dunkel sind um ihn her, / Recht und Gerechtigkeit sind seines Thrones Stützen.',
        3: 'Feuer geht vor ihm her / Und verzehrt ringsum seine Feinde.',
        4: 'Seine Blitze erhellen den Erdkreis, / Die Erde sieht es und bebt vor Angst.',
        5: 'Wie Wachs sind Berge vor Jahwe zerschmolzen, / Vor dem Herrn der ganzen Erde.',
        6: 'Die Himmel haben sein Recht verkündet, / Seine Herrlichkeit schauen die Völker alle.',
        7: 'Beschämt sollen stehn alle Bilderdiener, / Die sich der nichtigen Götzen rühmen: / Ihm haben ja alle Götter gehuldigt.',
        8: 'Mit Freunden hat es Zion vernommen, / Und Judas Töchter haben frohlockt / Ob deiner Gerichte, o Jahwe.',
        9: 'Denn du, o Jahwe, bist der Höchste in aller Welt, / Bist hoch erhaben über alle Götter.',
        10: 'Die Jahwe lieben, hassen das Böse. / Er, der seiner Frommen Seelen behütet, / Wird sie aus der Frevler Hand erretten.',
        11: 'Licht erstrahlt dem Gerechten / Und Freude den Redlichgesinnten.',
        12: 'Drum freuet euch Jahwes, ihr Gerechten, / Und preiset sein heilig Gedächtnis!',
    },
    98: {
        1: 'Ein Psalm. / Singet Jahwe ein neues Lied, / Denn Wunderbares hat er vollbracht: / Seine Rechte hat ihm geholfen / Und sein heiliger Arm.',
        2: 'So hat Jahwe gezeigt, daß er rettet, / Vor den Augen der Völker hat er sein Heil enthüllt.',
        3: 'Er hat gedacht seiner Huld und Treu gegen Israels Haus; / Alle Enden der Erde / Haben unsers Gottes Hilfe geschaut.',
        4: 'Jauchzt Jahwe zu, alle Lande, / Freut euch, jubelt und spielt!',
        5: 'Spielt mit der Zither Jahwe zu Ehren, / Mit der Zither und lautem Gesang!',
        6: 'Mit Trompeten und Schofarklang / Jauchzet vor Jahwe, dem König!',
        7: 'Es tose das Meer mit allem, was drinnen, / Der Erdkreis mit seinen Bewohnern!',
        8: 'Die Ströme sollen frohlocken, / Jauchzen sollen die Berge alle',
        9: "Vor Jahwes Nähe, wenn er nun kommt, / Um die Erde zu richten. / Richten wird er die Welt gerecht / Und die Völker, wie sich's gebührt.",
    },
    99: {
        1: 'Jahwe herrscht nun als König: da zittern die Völker, / Er thront auf Keruben: da wanket die Welt.',
        2: 'Jahwe ist groß in Zion, / Erhaben ist er über alle Völker.',
        3: 'Preisen soll man deinen Namen: / "Groß und ehrfurchtgebietend, / Ja, heilig ist er!"',
        4: 'Ein König ist stark, wenn er liebt das Recht: / Du hast nun bestimmt, was sich gebührt; / Du hast in Jakob verordnet / Recht und Gerechtigkeit.',
        5: 'Preiset Jahwe, unsern Gott, / Fallt nieder vor seinem Fußschemel: / "Heilig ist er!"',
        6: 'Mose und Aaron zählten zu seinen Priestern, / Und Samuel war unter seinen Betern: / Sie riefen zu Jahwe — er hörte sie.',
        7: 'In der Wolkensäule sprach er zu ihnen; / Seine Gebote bewahrten sie / Und jedes Gesetz, das er ihnen gegeben.',
        8: 'Jahwe, unser Gott, du hast sie erhört. / Ein verzeihender Gott bist du ihnen gewesen, / Doch ihr Vergehen hast du gestraft.',
        9: 'Preiset Jahwe, unsern Gott! / Fallt nieder vor seinem heiligen Berg, / Denn heilig ist Jahwe, unser Gott!',
    },
    100: {
        1: 'Ein Psalm zum Dankopfer. / (Der Chor der Festgemeinde:) / Jauchzt Jahwe zu, alle Erdbewohner!',
        2: 'Dienet Jahwe mit Freuden, / Erscheint vor ihm mit Jubel!',
        3: 'Erkennet: Jahwe ist Gott! / Er hat uns gemacht, und wir sind sein: / Sein Volk, das er weidet als Herde.',
        4: '(Der Chor der levitischen Sänger:) / Zieht in seine Tore mit Danken ein, / In seine Vorhöfe mit Lobgesang! / Dankt ihm, preist seinen Namen!',
        5: 'Denn gütig ist Jahwe, ewig währt seine Gnade / Und seine Treu von Geschlecht zu Geschlecht.',
    },
    101: {
        1: 'Ein Psalm Davids. / Von Huld und Recht will ich singen, / Dir, Jahwe, will ich spielen.',
        2: 'Achten will ich auf frommen Wandel — / Wann wirst du zu mir kommen? / Einhergehn will ich in meines Herzens Unschuld / In meinem Hause.',
        3: 'Nicht will ich sinnen / Auf ruchlos Tun. / Der Abtrünnigen Werke hasse ich: / Nicht sollen sie mir ankleben.',
        4: 'Ein falsches Herz soll mir fernbleiben, / Von Frevlern will ich nichts wissen.',
        5: 'Wer seinen Nächsten heimlich verleumdet, / Den will ich zum Schweigen bringen.',
        6: 'Meine Augen suchen die Treuen im Lande: / Die sollen bei mir wohnen. / Wer auf frommem Wege wandelt, / Der soll mein Diener sein.',
        7: 'Nicht soll in meinem Hause einer weilen, / Der Trug verübt. / Wer Lügen redet, / Der kann vor meinen Augen nicht bestehn.',
        8: 'Jeden Morgen will ich unschädlich machen / Alle Frevler des Landes, / Um aus Jahwes Stadt zu vertilgen / Alle Übeltäter.',
    },
    102: {
        1: 'Das Gebet eines Elenden, wenn er verzagt ist / und seine Klage vor Jahwe ergießt.',
        2: 'Jahwe, höre doch mein Gebet, / Laß meinen Notschrei zu dir dringen!',
        3: 'Verbirg dein Antlitz nicht vor mir, / Wenn ich in Bedrängnis bin! / O neige dein Ohr zu mir, / Wenn ich zu dir rufe. / Erhöre mich eilend!',
        4: 'Denn meine Tage sind wie ein Rauch vergangen, / Mein Gebein ist durchglüht wie ein Herd.',
        5: 'Mein Herz ist wie Gras, vom Glutwind getroffen: es ist verdorrt; / Denn ich habe sogar vergessen, mein Brot zu genießen.',
        6: 'Vor lautem Jammern / Klebt mein Gebein mir am Fleisch.',
        7: 'Ich gleiche dem Pelikan in der Wüste, / Ich bin wie ein Käuzlein in Trümmerstätten.',
        8: 'Nachts bin ich schlaflos wie ein Vogel, / Der einsam sitzt auf dem Dach.',
        9: 'Allzeit schmähen mich meine Feinde; / Die wider mich rasen, schwören bei mir.',
        10: 'Denn Asche hab ich als Brot gegessen / Und mein Getränk mit Tränen gemischt.',
        11: 'Dein Grimm und Zorn hat das bewirkt: / Du hast mich vom Boden gehoben, dann niedergeschleudert.',
        12: 'Meine Tage sind wie ein langer Schatten, / Und ich selbst verdorre wie Gras.',
        13: 'Du aber, Jahwe, wirst ewig thronen, / Dein Gedächtnis währt in allen Geschlechtern.',
        14: "Du wirst dich erheben, dich Zions erbarmen. / Denn Zeit ist's, ihm Gnade zu schenken: die Stunde ist da.",
        15: 'Denn deine Knechte lieben seine Steine, / Und sein Schutt erfüllt sie mit Jammer.',
        16: 'Dann werden die Heiden Jahwes Namen fürchten / Und alle Könige der Erde deine Herrlichkeit,',
        17: 'Wenn Jahwe Zion hat neugebaut, / In seinem Glanze erschienen ist.',
        18: 'Er hat ja der Heimatlosen Gebet erhört / Und nicht verachtet ihr Flehen.',
        19: 'Dies soll verzeichnet werden für spätre Geschlechter. / Ein Volk, das erst noch ins Dasein tritt, / Soll Jah lobpreisen.',
        20: 'Denn er hat herabgeschaut von seiner heiligen Höhe, / Jahwe hat vom Himmel zur Erde geblickt,',
        21: 'Um der Gefangnen Seufzen zu hören, / Die dem Tode Verfallnen freizumachen,',
        22: 'Damit man in Zion von Jahwes Namen erzähle, / Von seinem Ruhm in Jerusalem,',
        23: 'Wenn die Völker alle zusammenkommen / Und die Königreiche, um Jahwe zu dienen.',
        24: 'Auf dem Wege hat er meine Kraft gebrochen, / Er hat meine Tage verkürzt.',
        25: 'Nun ruf ich: "Mein Gott, raffe mich nicht weg / In der Hälfte meiner Tage!" / Deine Jahre währen ja / Bis in die fernsten Geschlechter.',
        26: 'Vorzeiten hast du die Erde gegründet, / Und die Himmel sind deiner Hände Werk.',
        27: 'Sie werden vergehn, du aber bleibst. / Sie alle veralten wie ein Kleid. / Du wirst sie wechseln wie ein Gewand, / Und sie werden verschwinden.',
        28: 'Du aber bleibst immer derselbe, / Und deine Jahre werden nicht enden. Deiner Knechte Kinder werden in Ruhe wohnen, / Und ihre Nachkommen werden vor dir bestehn.',
    },
    103: {
        1: 'Von David. / Preise Jahwe, o meine Seele, / Und all mein Innres seinen heiligen Namen!',
        2: 'Preise Jahwe, o meine Seele, / Und vergiß nicht all seiner Segenstaten!',
        3: 'Er vergibt dir all deine Missetat, / Schafft all deiner Krankheit Heilung.',
        4: 'Er erlöset dein Leben vom Tode, / Krönt dich mit Huld und Erbarmen.',
        5: 'Er sättigt dein Alter mit Gutem, / So daß deine Jugend sich wieder erneut / Wie eines Adlers Gefieder.',
        6: 'Heilstaten vollführet Jahwe, / Recht schafft er allen Bedrückten.',
        7: 'Mose tat er seine Wege kund, / Israels Söhnen sein herrliches Tun.',
        8: 'Barmherzig und gnädig ist Jahwe, / Langmütig und reich an Huld.',
        9: 'Er hat nicht für immer gehadert / Und nicht auf ewig gezürnt.',
        10: 'Nicht nach unsern Sünden hat er uns gelohnt, / Uns nicht vergolten nach unsern Vergehn.',
        11: 'Sondern so hoch der Himmel ist über der Erde, / So mächtig war seine Huld bei den Frommen.',
        12: 'So weit der Osten vom Westen ist, / Hat er unsre Frevel von uns entfernt.',
        13: 'Wie sich ein Vater der Kinder erbarmt, / Hat Jahwe sich stets erbarmt seiner Frommen.',
        14: 'Er weiß ja, wie schwach wir sind, / Er gedenket daran: wir sind Staub.',
        15: 'Eines Sterblichen Tage sind wie Gras, / Wie des Feldes Blume, so blüht er.',
        16: 'Fährt über sie ein Windstoß, so ist sie dahin, / Und es kennt sie nicht mehr ihre Stätte.',
        17: 'Doch Jahwes Gnade erzeigt sich auf ewig an seinen Frommen, / Seine Treue erfahren in jedem Geschlecht',
        18: 'Alle, die seinen Bund bewahren / Und seiner Gebote gedenken, sie zu erfüllen.',
        19: 'Jahwe hat seinen Thron im Himmel errichtet, / Sein Königtum herrscht über alles.',
        20: 'Preist Jahwe, ihr seine Engel, / Ihr Helden an Kraft, die ihr sein Gebot vollführt, / Indem ihr dem Ruf seines Wortes gehorcht!',
        21: 'Preist Jahwe, ihr seine Heere alle, / Seine Diener, die ihr seinen Willen vollstreckt!',
        22: 'Preist Jahwe, ihr seine Werke all, / An jedem Ort seines Herrschaftsgebiets! / Preise Jahwe auch meine Seele!',
    },
    104: {
        1: 'Preise Jahwe, o meine Seele! / Jahwe, mein Gott, du bist sehr groß: / Mit Hoheit und Pracht hast du dich gekleidet,',
        2: 'In Licht dich gehüllt wie in ein Gewand. / Wie ein Zelttuch hat er die Himmel gespannt.',
        3: 'Im Wasser hat er seine Söller gewölbt. / Wolken macht er zu seinem Wagen. / Auf des Windes Flügeln fährt er einher.',
        4: 'Winde macht er zu seinen Boten, / Zu seinen Dienern Feuerflammen.',
        5: 'Die Erde hat er auf Pfeiler gegründet, / So daß sie nicht wanket immer und ewig.',
        6: 'Die Urflut hat er darüber gedeckt wie ein Kleid, / Selbst über den Bergen standen Wasser.',
        7: 'Vor deinem Machtruf entflohen sie, / Vor deinem gewaltigen Donner eilten sie ängstlich hinweg',
        8: '- Während Berge sich hoben und Täler sich senkten — / An den Ort, den du ihnen bestimmt.',
        9: 'Eine Grenze hast du ihnen gesetzt, die dürfen sie nicht überschreiten. / Sie dürfen nicht wiederkehren, daß sie die Erde bedecken.',
        10: 'Du sendest Quellen in Bäche aus, / Die zwischen den Bergen fließen.',
        11: 'Sie tränken alles Getier des Gefilds; / Auch Wildesel stillen ihren Durst.',
        12: 'An den Bächen wohnen des Himmels Vögel, / Und aus den Zweigen ertönt ihr Lied.',
        13: 'Er tränkt die Berge aus seinen Söllern. / Von dem, was dein Regen wachsen läßt, wird das Erdreich gesättigt.',
        14: 'Gras lässest du sprossen für das Vieh / Und Kraut zum Nutzen des Menschen: / So bringst du Brot aus der Erde hervor.',
        15: 'Und der Wein soll erfreun des Sterblichen Herz, / Sein Antlitz soll glänzen vom Öl, / Und das Brot soll erquicken des Sterblichen Herz.',
        16: 'Jahwes Bäume trinken sich satt: / Libanons Zedern, die er gepflanzt.',
        17: 'Dort nisten Vögel, / Vor allen der Storch, der sein Nest auf Zypressen hat.',
        18: 'Die Berge dagegen, die hohen, sind der Steinböcke Sitz. / In den Felsen finden die Klippdachse Schutz.',
        19: 'Er schuf den Mond, die Zeiten zu messen, / Dazu auch die Sonne, die ihren Untergang kennt.',
        20: 'Läßt du Finsternis kommen, so wird es Nacht. / Da regt sich alles Getier des Waldes:',
        21: 'Die jungen Löwen vor allen, die da brüllen nach Raub / Und von Gott ihre Nahrung fordern.',
        22: 'Die Sonne geht auf: da schleichen sie weg / Und legen sich nieder in ihren Höhlen.',
        23: 'Der Mensch geht an sein Tagewerk, / An seine Arbeit bis auf den Abend.',
        24: 'Jahwe, wie sind deiner Werke so viel! / Sie alle hast du mit Weisheit vollbracht. / Voll ist die Erde von deinen Gütern.',
        25: 'Da ist das Meer — so groß und so weit! / Drin ist ein zahllos Gewimmel: / Kleine Tiere und große.',
        26: 'Dort ziehen auch Schiffe dahin. / Und der Leviatan ist da, den du geschaffen, / Daß er sich tummle in den Fluten.',
        27: 'Sie alle schauen zu dir empor, / Daß du ihnen Speise gebest zu rechter Zeit.',
        28: 'Wenn du ihnen gibst, so sammeln sie ein; / Öffnest du deine Hand, so werden sie satt von Gutem.',
        29: 'Verbirgst du dein Antlitz, so erschrecken sie; / Nimmst du weg ihren Odem: sie müssen verscheiden / Und kehren zurück in ihren Staub.',
        30: 'Deinen Lebensodem sendest du aus, und sie werden geschaffen: / So erneust du das Antlitz der Erde.',
        31: 'Jahwes Herrlichkeit währe auf ewig! / Es freue sich Jahwe seiner Werke!',
        32: 'Blickt er die Erde an, so erzittert sie; / Berührt er die Berge, so rauchen sie.',
        33: 'Ich will Jahwe singen mein Leben lang, / Meinem Gotte spielen, solange ich bin.',
        34: 'Mög ihm auch mein Sinnen gefallen! / Ich will mich Jahwes freun.',
        35: 'Mögen die Sünder vom Erdboden schwinden / Und die Gottlosen nicht mehr sein! / Meine Seele, preise du Jahwe! / Lobet Jah!',
    },
    105: {
        1: 'Danket Jahwe, ruft seinen Namen an, / Macht seine großen Taten inmitten der Völker kund!',
        2: 'Singt ihm, spielt ihm, / Redet von all seinen Wundern!',
        3: 'Rühmt euch seines heiligen Namens! / Es freue sich deren Herz, die Jahwe suchen.',
        4: 'Fraget nach Jahwe und seiner Macht, / Suchet sein Antlitz beständig!',
        5: 'Gedenkt seiner Wunder, die er getan, / Seiner Zeichen und der Urteile seines Munds,',
        6: 'Ihr Nachkommen Abrahams, seines Knechts, / Ihr Söhne Jakobs, seine Erwählten!',
        7: 'Er, Jahwe, ist unser Gott; / Er waltet gerecht über alle Lande.',
        8: 'Er gedenkt seines Bundes auf ewig, / Des Wortes, das er geboten für tausend Geschlechter,',
        9: 'Des Bundes, den er geschlossen mit Abraham, / Seines Eides an Isaak.',
        10: 'Er hat ihn für Jakob verheißend bestätigt, / Für Israel als ewigen Bund.',
        11: 'Indem er sagte: "Dir will ich geben Kanaans Land / Als euer erblich Besitztum."',
        12: 'Damals waren sie klein an Zahl, / Ein Häuflein nur, und Gäste im Land.',
        13: 'So wanderten sie von Volk zu Volk, / Von einem Reiche zum andern Volk.',
        14: 'Er ließ sie dabei von niemand bedrücken, / Ja, Könige strafte er ihretwegen:',
        15: '"Tastet meine Gesalbten nicht an, / Und meinen Propheten tut kein Leid!"',
        16: 'Dann rief er Hungersnot gegen das Land, / Nahm jegliche Nahrung hinweg.',
        17: 'Er sandte vor ihnen her einen Mann: / Josef ward als Sklave verkauft.',
        18: 'Seine Füße wurden gefesselt, / In Eisen legte man ihn,',
        19: 'Bis sich sein Wort erfüllte, / Jahwes Spruch ihn geläutert hatte.',
        20: 'Da sandte der König und ließ ihn los, / Der Völkerbeherrscher gab ihn frei.',
        21: 'Er setzte ihn seinem Hause zum Herrn, / Zum Gebieter über all seinen Besitz;',
        22: 'Er sollte seine Fürsten an sich fesseln, / Seine Ältesten sollte er Weisheit lehren.',
        23: 'Dann kam Israel nach Ägypten, / Und Jakob ward Gast im Lande Hams.',
        24: 'Gott ließ sein Volk sehr zahlreich werden / Und machte es stärker als seine Bedränger.',
        25: 'Es wandelte sich nämlich ihr Herz, sein Volk zu hassen, / Arglist zu üben an seinen Knechten.',
        26: 'Da sandte Gott Mose, seinen Knecht, / Und Aaron, den er sich erkoren.',
        27: 'Die taten Zeichen bei ihnen durch seine Macht / Und Wunderdinge im Lande Hams.',
        28: 'Er sandte Finsternis — es ward dunkel; / Denn widerstrebten sie nicht seinen Worten?',
        29: 'Er verwandelte ihre Gewässer in Blut / Und ließ dadurch ihre Fische sterben.',
        30: 'Es wimmelte auch ihr Land von Fröschen: / Die drangen sogar in der Könige Kammern.',
        31: 'Er sprach, da kamen Bremsen, / Stechmücken in all ihr Gebiet.',
        32: 'Er gab ihnen Hagel als Regen, / Ließ Feuer lohen in ihrem Land.',
        33: 'Er schlug ihren Weinstock und Feigenbaum, / Zerbrach alle Bäume ihres Gebiets.',
        34: 'Er sprach, da kamen Heuschrecken / Und Hüpfer ohne Zahl.',
        35: 'Die fraßen alles Kraut in ihrem Land, / Sie verzehrten die Frucht ihrer Felder.',
        36: 'Alle Erstgeburt schlug er in ihrem Land, / Die Erstlinge all ihrer Manneskraft.',
        37: 'Da ließ er sein Volk mit Silber und Gold ausziehn, / Und es strauchelte keiner in seinen Stämmen.',
        38: 'Die Ägypter freuten sich ihres Auszugs, / Denn Graun vor ihnen war auf sie gefallen.',
        39: 'Er spannte Gewölk als Decke aus, / Und Feuer gab ihnen zur Nachtzeit Licht.',
        40: 'Er bat: da ließ Gott Wachteln kommen / Und sättigte sie mit Himmelsbrot.',
        41: 'Einen Fels tat er auf: da floß Wasser heraus; / Es rann wie ein Strom durch die Steppe.',
        42: 'Denn er dachte seines heiligen Worts / Und Abrahams, seines Knechts.',
        43: 'Drum ließ er sein Volk mit Freuden ausziehn, / Seine Auserwählten mit Jubel.',
        44: 'Er gab ihnen Länder der Heiden; / Was Völker erworben, das erbten sie.',
        45: 'Denn sie sollten seine Gesetze befolgen / Und seinen Lehren gehorsam sein. / Lobt Jah!',
    },
    106: {
        1: 'Lobet Jah! / Danket Jahwe, denn er ist gütig; / Ewig währet ja seine Huld.',
        2: 'Wer kann gebührend von Jahwes Taten reden / Und all seinen Ruhm erschöpfend verkünden?',
        3: 'Heil denen, die das Gesetz befolgen, / Die Gerechtigkeit üben zu jeder Zeit!',
        4: 'Gedenke mein, o Jahwe! / Auch mir schenk die Huld, die dein Volk erfährt! / Auch mich sieh an, wenn du ihm hilfst!',
        5: 'Dann schau ich mit Lust deiner Erwählten Glück, / Dann teil ich die Freude deines Volks / Und darf mich rühmen mit deinem Erbe.',
        6: 'Wir haben gesündigt gleich unsern Vätern, / Haben gottlos gehandelt, gefrevelt.',
        7: 'Unsre Väter in Ägypten achteten nicht deiner Wunder, / Gedachten nicht deiner Gnadenfülle, / Sondern waren widerspenstig am Meer, am Schilfmeer.',
        8: 'Er aber rettete sie um seines Namens willen, / Um seine Macht zu beweisen.',
        9: 'Er schalt das Schilfmeer, da ward es trocken. / In den Fluten ließ er sie ziehn wie auf blachem Feld.',
        10: 'So befreite er sie aus des Hassers Hand / Und erlöste sie aus des Feindes Gewalt.',
        11: 'Die Wasser bedeckten ihre Bedränger: / Nicht einer von ihnen blieb übrig.',
        12: 'Da vertrauten sie auf seine Worte, / Sie sangen seinen Ruhm.',
        13: 'Doch schnell vergaßen sie seine Taten, / Warteten nicht, daß sein Rat sich erfülle.',
        14: 'Sondern lüstern wurden sie in der Wüste / Und versuchten Gott in der Öde.',
        15: 'Da erfüllte er wohl ihr Verlangen, / Aber dann sandte er ihnen Krankheit zu.',
        16: 'Sie waren auch neidisch auf Mose im Lager, / Auf Aaron, Jahwes Geweihten.',
        17: 'Da tat sich die Erde auf: sie verschlang Datan / Und bedeckte die Rotte Abirams.',
        18: 'Feuer ergriff ihre Rotte, / Die Flamme verzehrte die Frevler.',
        19: 'Sie machten ein Kalb am Horeb / Und beteten dann dies Gußbild an.',
        20: 'Ihres Gottes Herrlichkeit gaben sie hin / Für das Bild eines Stieres, der Gras frißt.',
        21: 'Sie hatten Gott, ihren Retter, vergessen, / Der Großes getan in Ägypten,',
        22: 'Wunder im Lande Hams, / Erstaunliche Dinge am Schilfmeer.',
        23: 'Er wollte sie schon vertilgen: / Doch da trat Mose, sein Auserwählter, vor ihm in den Riß, / Um seine Zornglut abzuwenden, / Daß er sie nicht verderbe.',
        24: 'Sie verschmähten das köstliche Land, / Sie trauten seiner Verheißung nicht,',
        25: 'Sondern murrten in ihren Zelten, / Gehorchten nicht Jahwes Stimme.',
        26: 'Da hub er auf seine Hand und schwur, / Sie niederzuschlagen in der Wüste,',
        27: 'Ihre Nachkommen unter die Völker zu werfen, / Sie zu zerstreuen in die Länder.',
        28: 'Sie hängten sich an den Baal Peôr / Und aßen Opfer für Tote.',
        29: 'So reizten sie ihn mit ihrem Tun. / Da riß unter ihnen ein Sterben ein.',
        30: 'Nun aber trat Pinehas auf und hielt Gericht: / Da ward der Plage Einhalt getan.',
        31: 'Das ward ihm gerechnet zur Gerechtigkeit / Für alle Geschlechter, für immer.',
        32: "Sie erzürnten ihn weiter am Haderwasser, / Und übel ging's Mose um ihretwillen.",
        33: 'Denn sie hatten seinem Geist widerstrebt, / So daß ihm unbedachte Worte entfuhren.',
        34: 'Sie vertilgten auch nicht die Völker, / Wie ihnen Jahwe geboten hatte.',
        35: 'Sondern sie ließen sich ein mit den Heiden / Und nahmen an ihrem Treiben teil:',
        36: 'Sie dienten ihren Götzen, / Die wurden ihnen zum Fallstrick.',
        37: 'Sie opferten ihre Söhne / Und ihre Töchter den bösen Geistern.',
        38: 'So vergossen sie schuldlos Blut, / Das Blut ihrer Söhne und Töchter, / Die sie opferten Kanaans Götzen, / Daß das Land durch Blutschuld entweiht ward.',
        39: 'So wurden sie unrein durch ihr Tun / Und fielen von Gott durch ihr Treiben ab.',
        40: 'Da entbrannte Jahwes Zorn wider sein Volk, / Er fühlte Abscheu gegen sein Erbe.',
        41: 'Drum gab er sie in der Heiden Hand, / Daß ihre Hasser über sie herrschten.',
        42: 'Ihre Feinde bedrängten sie, / Sie mußten sich beugen ihrer Gewalt.',
        43: 'Oftmals zwar befreite er sie, / Doch in Eigensinn lehnten sie sich auf: / Drum gingen sie unter in ihrer Schuld.',
        44: 'Er aber sah gnädig auf ihre Not, / Als er ihr lautes Schrein vernahm.',
        45: 'Da gedachte er ihnen an seinen Bund / Und hatte Mitleid in großer Huld.',
        46: 'Er ließ sie Erbarmen finden / Bei allen, die sie ins Elend geführt.',
        47: 'Hilf uns, Jahwe, unser Gott, / Und sammle uns aus den Heiden! / Dann wollen wir danken deinem heiligen Namen, / Uns glücklich preisen, dich zu loben.',
        48: 'Gepriesen sei Jahwe, Israels Gott, / Von Ewigkeit zu Ewigkeit! / Und alles Volk spreche: / "Ja wahrlich! Lobt Jah!"',
    },
    107: {
        1: '"Danket Jahwe, denn er ist gütig; / Ewig währt ja seine Huld!"',
        2: 'So sollen sprechen Jahwes Erlöste, / Die er erlöst hat aus Feindeshand,',
        3: 'Und die er gesammelt aus vielen Landen: / Von Ost und West, von Nord und Süd.',
        4: 'Sie irrten vom Weg in der Wüste und Öde, / Eine Stadt als Wohnsitz fanden sie nicht.',
        5: 'Sie litten Hunger und Durst: / Ihre Seele verzagte in ihnen.',
        6: 'Da schrien sie zu Jahwe in ihrer Not: / Der riß sie heraus aus ihren Ängsten.',
        7: 'Er führte sie auf ebnem Weg, / Daß sie kamen in eine wohnliche Stadt.',
        8: 'Nun sollen sie Jahwe danken für seine Huld / Und für seine Wunder zum Segen der Menschen.',
        9: 'Er hat ja die lechzende Seele gesättigt / Und die hungrige Seele mit Gutem gefüllt.',
        10: 'Sie wohnten in Dunkel und Todesschatten, / Gefangen in Elend und Eisenbanden.',
        11: 'Denn sie hatten Jahwes Worten getrotzt / Und den Rat des Höchsten verachtet.',
        12: 'Drum beugte er auch durch Mühsal ihr Herz: / Nun sanken sie hin ohne Helfer.',
        13: 'Da schrien sie zu Jahwe in ihrer Not: / Der machte sie frei aus ihren Ängsten.',
        14: 'Er ließ sie aus Dunkel und Todesschatten, / Und ihre Fesseln zersprengte er.',
        15: 'Nun sollen sie Jahwe danken für seine Huld / Und für seine Wunder zum Segen der Menschen.',
        16: 'Denn er hat zerbrochen Türen von Erz / Und eiserne Riegel zerschlagen.',
        17: 'Gottlose mußten ob sündigen Wandels / Und ob Übertretungen leiden:',
        18: 'Jegliche Speise verabscheuten sie, / Und sie waren schon nahe den Pforten des Todes.',
        19: 'Da schrien sie zu Jahwe in ihrer Not / Der machte sie frei aus ihren Ängsten.',
        20: 'Er sandte sein Wort und heilte sie / Und ließ sie entrinnen aus ihren Gruben.',
        21: 'Nun sollen sie Jahwe danken für seine Huld / Und für seine Wunder zum Segen der Menschen.',
        22: 'Sie sollen bringen Opfer des Danks, / Seine Taten erzählen mit Jubel.',
        23: 'Die mit Schiffen das Meer befuhren, / Ihren Handel trieben in großen Gewässern,',
        24: 'Sie haben Jahwes Werk geschaut / Und seine Wunder im Meeresstrudel.',
        25: 'Auf sein Wort brauste ein Sturmwind daher, / Der türmte empor die Wogen des Meers.',
        26: 'Sie stiegen himmelan, bald fuhren sie in die Tiefe: / Ihre Seel verging in Weh.',
        27: 'Sie schwankten und wankten wie Trunkne, / Und all ihre Weisheit war dahin.',
        28: 'Da schrien sie zu Jahwe in ihrer Not, / Der führte sie aus ihren Ängsten.',
        29: 'Er dämpfte den Sturm zum Säuseln, / Und stille schwiegen des Meeres Wogen.',
        30: 'Da wurden sie froh, daß es ruhig geworden; / Er führte sie dann zum ersehnten Hafen.',
        31: 'Nun sollen sie Jahwe danken für seine Huld / Und für seine Wunder zum Segen der Menschen.',
        32: 'Ja sie sollen ihn preisen in der Gemeinde / Und im Ältestenrate ihn loben.',
        33: 'Er machte auch Ströme zur Wüste / Und Wasserquellen zu dürrem Land,',
        34: 'Fruchtbares Feld zur salzigen Steppe / Wegen der Bosheit seiner Bewohner.',
        35: 'Er wandelte Wüsten in Wasserteiche / Und dürres Land in Wasserquellen.',
        36: 'Dort machte er Hungrige seßhaft: / Sie bauten sich eine Wohnstadt.',
        37: 'Sie besäten Äcker, pflanzten Weingärten / Und gewannen Ertrag an Frucht.',
        38: 'Gott segnete sie: sie mehrten sich sehr, / Auch ihr Vieh ließ sich nicht vermindern.',
        39: 'Doch manchmal nahmen sie ab und sanken dahin / Durch den Druck von Unglück und Kummer.',
        40: 'Aber er, "der auf Fürsten Verachtung gießt / Und in wegloser Öde sie irren läßt" —',
        41: 'Er hob die Armen aus Elend hervor / Und mehrte ihre Sippen wie Herden.',
        42: 'Redliche sollen das sehn mit Freuden, / Doch alle Frevler müssen verstummen.',
        43: 'Wer weise ist, der beachte dies / Und verstehe die Gnaden Jahwes!',
    },
    108: {
        1: 'Ein Psalmlied Davids.',
        2: 'Mein Herz ist getrost, Elohim. / Ich will singen und spielen, / Ja, das soll meine Seele!',
        3: 'Wach auf, du Harfe und Zither! / Wecken will ich das Morgenrot.',
        4: 'Unter Völkern, Adonái, will ich dich preisen, / Dir singen unter den Leuten.',
        5: 'Denn groß bis über die Himmel hinaus ist deine Gnade, / Bis zu den Wolken reicht deine Treu.',
        6: 'Elohim, erheb dich über die Himmel, / Deine Herrlichkeit über alle Welt!',
        7: 'Damit deine Lieben gerettet werden, / So hilf denn mit deiner Rechten und hör uns!',
        8: 'Elohim hat mir verheißen bei seinem heiligen Namen: / Frohlocken soll ich, austeilen Sichem / Und vermessen das Tal Sukkot.',
        9: 'Mein ist Gilead und mein Manasse, / Efraim schützt mein Haupt als Helm, / Juda ist mein Herrscherstab.',
        10: 'Moab ist mein Waschbecken, / Auf Edom werf ich meinen Schuh. / Über Philistäa werd ich (als Sieger) jauchzen."',
        11: 'Wer bringt mich hinein in die feste Stadt? / Wer führt mich hin nach Edom?',
        12: 'Du, Elohim, du hast uns verworfen; / Du zogst nicht aus, Elohim, mit unsern Heeren.',
        13: 'O schaff uns Beistand gegen den Feind! / Denn nichtig ist Menschenhilfe. Mit Elohim verrichten wir Heldentaten. / Er wird unsre Feinde zertreten.',
    },
    109: {
        1: 'Dem Sangmeister. Ein Psalm Davids. / Gott, dem mein Loblied gilt, schweige doch nicht!',
        2: 'Denn der Frevler und Lügner Mund / Hat sich wider mich aufgetan, / Zu mir geredet mit falscher Zunge.',
        3: 'Mich haben Worte des Hasses umschwirrt / Und grundlos gegen mich Krieg geführt:',
        4: 'Mit Feindschaft lohnten sie meine Liebe — / Doch ich habe stets für sie gebetet.',
        5: 'Sie haben mir Böses für Gutes erwiesen / Und für meine Liebe Haß.',
        6: 'Bestell einen Frevler wider ihn, / Ein Verkläger steh ihm zur Rechten!',
        7: 'Kommt er vor Gericht, so werd er als schuldig verurteilt, / Sein Gebet sogar — es werde zur Sünde!',
        8: 'Seiner Tage sollen nur wenig sein, / Sein Amt soll ein andrer empfangen.',
        9: 'Seine Kinder sollen Waisen werden / Und sein Weib eine Witwe.',
        10: 'Seine Kinder sollen als Bettler unstet wandern, / (Brot) suchen fern von den Trümmern (des Vaterhauses).',
        11: 'Sein Gläubiger lege auf seinen Besitz Beschlag, / Und Fremde sollen ihm seine Habe rauben.',
        12: 'Nicht einer bewahre ihm Liebe, / Niemand erbarme sich seiner Waisen!',
        13: 'Sein Nachwuchs sei zum Vertilgen bestimmt, / Schon im andern Geschlecht erlösche sein Name!',
        14: 'Seiner Väter Schuld möge Jahwe gedenken, / Ungetilgt bleibe seiner Mutter Sünde!',
        15: 'Sondern immer seien sie Jahwe vor Augen; / Der tilg ihr Gedächtnis aus dem Lande,',
        16: 'Weil er nicht gedachte, Erbarmen zu üben, / Sondern den verfolgte, der elend und arm, / Ja den Verzagten zu morden suchte.',
        17: 'So hat er den Fluch geliebt: der treffe ihn nun! / Den Segen begehrte er nicht: der bleibe ihm fern!',
        18: 'Drum zog er den Fluch an wie sein Kleid: / Der dringe nun wie ein Wasser in ihn / Und gehe wie Öl in seine Gebeine!',
        19: 'Wie ein Kleid sei er ihm, in das er sich hüllt, / Wie ein Gurt, mit dem er sich ständig gürtet.',
        20: 'So lohne Jahwe meinen Verklägern / Und denen, die Böses wider mich reden.',
        21: 'Du aber, Jahwe Adonái, / Wirke mit mir um deines Namens willen! / Rette du mich, weil deine Huld so herrlich ist!',
        22: 'Denn ich bin elend und arm, / Und mein Herz ist in mir verwundet.',
        23: 'Wie ein Schatten, wenn er sich dehnt, so bin ich vergangen, / Gleich Heuschrecken bin ich hinweggescheucht.',
        24: 'Meine Knie schlottern vom Fasten, / Mein Fleisch ist verfallen und mager.',
        25: 'Den Leuten bin ich zum Hohn geworden, / Sie schütteln den Kopf, sooft sie mich sehn.',
        26: 'Hilf du mir, Jahwe, mein Gott, / Rette du mich nach deiner Huld!',
        27: 'Dann werden die Leute erkennen, daß dies deine Hand, / Daß du, o Jahwe, es hast getan.',
        28: 'Fluchen sie, so wollest du segnen. / Erheben sie sich, so laß sie zuschanden werden, / Während dein Knecht sich freuen darf.',
        29: 'Laß meine Verkläger sich kleiden in Schmach / Und Schande anziehn wie ein Gewand!',
        30: 'Ich will Jahwe laut danken mit meinem Munde, / Inmitten vieler ihn loben.',
        31: 'Denn er tritt dem Armen zur Rechten, / Um ihn zu retten vor denen, / Die ihn verurteilen wollen.',
    },
    110: {
        1: 'Ein Psalm Davids. / Gesprochen hat Jahwe zu meinem Herrn: / Setz dich zu meiner Rechten, / bis ich deine Feinde gemacht / Zum Schemel für deine Füße.',
        2: 'Den Herrscherstab deiner Macht wird Jahwe drum / Ausstrecken von Zion her: / Herrsche nun unter deinen Feinden!"',
        3: 'Dein Volk wird auch opferwillig dir folgen / An dem Tage, da du dein Heer zum Kampfe rufst. / In heiligem Schmuck / Strömt dir deine junge Mannschaft zu / Wie Tau aus dem Schoße des Frührots.',
        4: 'Geschworen hat Jahwe, nicht wird es ihn reun: / "Du sollst ein Priester auf ewig sein / Nach Melchisedeks Weise."',
        5: 'Adonái, der dir helfend zur Rechten steht, / Wird Könige niederwerfen / Am Tage seines Zorns.',
        6: 'Er richtet einst inmitten der Völker: / Er wird von Leichen umgeben sein, / Zerschmettern wird er das Haupt über weites Land.',
        7: 'Aus dem Bache am Wege wird er trinken. / Drum hebt er (siegreich) das Haupt empor.',
    },
    111: {
        1: 'Lobet Jah! / Auf! Jahwe will ich preisen mit ganzem Herzen / Beisammen mit Redlichen und der Gemeinde.',
        2: 'Groß sind die Werke Jahwes, / Durchforschenswert für alle, die daran Gefallen finden.',
        3: 'Hoheit und Glanz offenbart sein Tun. / Währt seine Gerechtigkeit nicht ewig?',
        4: 'Seiner Wunder Gedächtnis hat er gestiftet. / Gnädig und voll Erbarmen ist Jahwe.',
        5: 'Treu hat er Speise den Seinen gegeben; / Ja, immer gedachte er seines Bunds.',
        6: 'Kraftvolle Werke tat er seinem Volke kund, / Ließ sie besitzen der Heiden Erbe.',
        7: 'Machttaten seiner Hände sind Treue und Recht, / Nimmer täuschen all seine Befehle.',
        8: 'Sie bleiben fest für immer und ewig, / Auf Treue und Geradheit sind sie gegründet.',
        9: 'Freiheit sandte er seinem Volk; / Zu seinem Bund rief er es für immer. / Kann sein Name wohl anders als heilig sein und ehrfurchtgebietend?',
        10: 'Rechter Weisheit Anfang ist Furcht vor Jahwe. / Sie, die sie üben, zeigen treffliche Einsicht, / Tragen dauerndes Lob davon.',
    },
    112: {
        1: 'Auf den kommt Heil, der Jahwe fürchtet, / Bei seinen Geboten mit Freuden beharrt.',
        2: 'Gewaltig im Lande wird sein sein Geschlecht: / Die Redlichen sollen gesegnet werden.',
        3: 'Habe in Fülle, ja Reichtum wird bergen sein Haus, / Währt seine Gerechtigkeit nicht ewig?',
        4: 'Stets strahlt den Frommen im Dunkel Licht, / Gnädig, barmherzig, gerecht ist er.',
        5: 'Trefflich der Mann, der spendet und leiht, / Ja, der seine Sache nur stützt auf Recht.',
        6: 'Kann dessen Glück wohl jemals wanken? / Lebt nicht auf immer des Gerechten Gedächtnis?',
        7: 'Mitnichten fürchtet er Unglückskunde; / Nie wankt ja sein Herz, weil er Jahwe vertraut.',
        8: 'Sicher gestützt ist sein Herz, er fürchtet sich nicht: / Auf seine Bedränger sieht er mit Ruhe.',
        9: 'Freudig und reichlich gibt er den Armen; / Zu aller Zeit steht seine Gerechtigkeit fest. / Kraftvoll wird er dastehn und geehrt.',
        10: 'Recht mit Unmut wird das der Frevler sehn, / Scheelsüchtig mit seinen Zähnen knirschend wird er vor Neid vergehn. / Traun, was die Gottlosen wünschen, erfüllt sich nimmer.',
    },
    113: {
        1: 'Lobet Jah! / Lobet, ihr Knechte Jahwes. / Lobet den Namen Jahwes!',
        2: 'Jahwes Name sei gepriesen / Von nun an bis in Ewigkeit!',
        3: 'Vom Aufgang der Sonne bis zu ihrem Niedergang / Sei Jahwes Name gelobt!',
        4: 'Erhaben über alle Völker ist Jahwe, / Über den Himmeln thront seine Herrlichkeit.',
        5: 'Wer gleicht Jahwe, unserm Gott, / Der sich die Höhe zur Wohnung bereitet,',
        6: 'Aber auch alles tief durchforscht / Im Himmel und auf Erden?',
        7: 'Er richtet den Schwachen empor aus dem Staub, / Aus dem Aschenhaufen erhebt er den Armen.',
        8: 'Dann setzt er ihn neben den Edlen, / Neben die Edlen seines Volks.',
        9: 'Der Unfruchtbaren gibt er im Haus einen festen Platz, / Daß sie sich freut als Mutter inmitten der Kinderschar. / Lobet Jah!',
    },
    114: {
        1: 'Als Israel aus Ägypten zog, / Jakobs Haus aus fremdem Volk:',
        2: 'Da ward Juda sein Heiligtum, / Israel sein Herrschaftsgebiet.',
        3: 'Das Meer sah es und floh, / Der Jordan wandte sich rückwärts.',
        4: 'Die Berge hüpften wie Widder, / Die Hügel wie junge Schafe.',
        5: 'Was war dir, o Meer, daß du flohest, / Dir, Jordan, daß du dich rückwärts wandtest?',
        6: 'Was war euch, ihr Berge, daß ihr hüpftet wie Widder, / Ihr Hügel, wie junge Schafe?',
        7: 'Vor dem Herrn erbebe, du Erde, / Vor dem Antlitz des Gottes Jakobs!',
        8: 'Er wandelte Felsen in Wasserteich, / Kieselstein in sprudelnde Quellen.',
    },
    115: {
        1: '(Der Chor der Tempelsänger:) / Nicht uns, Jahwe, nicht uns, / Nein, deinem Namen schaff Ehre, / Ob deiner Huld, ob deiner Treu!',
        2: 'Warum sollen die Heiden sagen: / "Wo ist denn nun ihr Gott?"',
        3: 'Und doch: Unser Gott, der im Himmel thront, / Hat stets hinausgeführt, woran er Gefallen fand.',
        4: 'Aber ihre Götzen sind Silber und Gold, / Das Gebilde von Menschenhand.',
        5: 'Sie haben einen Mund und können nicht reden. / Sie haben Augen und sehen doch nicht.',
        6: 'Ohren haben sie und hören nicht, / Sie haben eine Nase und riechen nicht.',
        7: 'Ihre Hände — damit tasten sie nicht, / Ihre Füße — damit gehen sie nicht; / Nicht können sie reden mit ihrer Kehle.',
        8: 'Ihnen gleich sind, die sie bilden — / Jeder, der ihnen vertraut.',
        9: '(Erster Priesterchor:) / Israel, trau auf Jahwe! / (Zweiter Priesterchor:) / Ihr Helfer und Schild ist er.',
        10: '(Erster Priesterchor:) / Haus Aarons, trau auf Jahwe! / (Zweiter Priesterchor:) / Ihr Helfer und Schild ist er.',
        11: '(Beide Priesterchöre:) / Die ihr Jahwe fürchtet, traut auch ihr Jahwe! / (Der Chor der Tempelsänger:) / Ihr Helfer und Schild ist er.',
        12: '(Der opfernde Priester am Altar:) / Jahwe hat unser gedacht: er wird auch segnen. / Er wird segnen Israels Haus, / Er wird segnen Aarons Haus.',
        13: 'Er wird segnen, die Jahwe fürchten / Beide: Kleine und Große.',
        14: 'Jahwe wolle euch mehren, / Euch selbst und eure Kinder!',
        15: 'Gesegnet seid ihr von Jahwe, / Der Himmel und Erde geschaffen!',
        16: '(Erster Priesterchor:) / Der Himmel ist Jahwes Himmel, / Die Erde aber hat er den Menschenkindern gegeben.',
        17: '(Zweiter Priesterchor:) / Die Toten, sie werden Jah nicht loben, / Sie alle nicht, die in die Stille hinabgestiegen.',
        18: '(Alle Chöre zusammen:) / Wir aber, wir preisen Jah / Von nun an bis in Ewigkeit. / Lobt Jah!',
    },
    116: {
        1: 'Jahwe hab ich lieb, / Denn er hat meine Stimme, mein Flehn erhört.',
        2: 'Ja, er hat mir sein Ohr zugeneigt; / Drum werd ich ihn auch, solang ich lebe, anrufen.',
        3: 'Mich hatten des Todes Bande umringt, / Ich fürchtete schon, ins Grab zu sinken, / Angst und Kummer erfuhr ich.',
        4: 'Da rief ich Jahwes Namen an: / "Ach, Jahwe, rette mein Leben!"',
        5: 'Jahwe war auch gnädig und treu, / Und es erbarmte sich unser Gott.',
        6: 'Schutzlose behütet Jahwe: / Drum half er mir auch, als ich elend war.',
        7: '"Kehr nun ein, meine Seele, in deine Ruh, / Denn Jahwe hat dir wohlgetan!"',
        8: 'Ja, du hast meine Seele dem Tode entrissen, / Meinen Augen die Tränen getrocknet, / Meinen Fuß vor Gleiten bewahrt.',
        9: 'So darf ich vor Jahwe noch wandeln / In der Lebendigen Landen.',
        10: 'Ich sprach die Wahrheit, als ich sagte: / "Ich bin sehr niedergedrückt."',
        11: 'Ich habe sogar in meiner Angst gesagt: / "Alle Menschen sind Lügner."',
        12: 'Wie soll ich nun aber Jahwe vergelten / All seine Wohltaten, die ich erfahren?',
        13: 'Den Becher des Heils werd ich erheben / Und Jahwes Namen anrufen.',
        14: 'Meine Gelübde werd ich Jahwe erfüllen / Frei und offen vor all seinem Volk.',
        15: 'Selten nur läßt Jahwe / Seine Frommen (frühzeitig) sterben.',
        16: 'Ach Jahwe, (erhalte darum mein Leben auch ferner)! / Ich bin ja dein Knecht. / Ich bin dein Knecht, der Sohn deiner Magd. / Du hat meine Fesseln gelöst.',
        17: 'Dir will ich Dankopfer bringen / Und Jahwes Namen anrufen.',
        18: 'Meine Gelübde will ich Jahwe erfüllen / Frei und offen vor all seinem Volk.',
        19: 'In den Vorhöfen des Hauses Jahwes, / In der Mitte, Jerusalem! / Lobt Jah!',
    },
    117: {
        1: 'Lobt Jahwe, alle Heiden, / Preist ihn, all ihr Völker!',
        2: 'Denn seine Huld waltet mächtig über uns, / Und Jahwes Treue währt ewig! / Lobt Jah!',
    },
    118: {
        1: '(Gesang der Festgemeinde auf dem Wege zum Tempelberg:) / (1. Chor:) / Danket Jahwe, denn er ist gütig, / (2. Chor:) / Ja, ewig währet seine Huld.',
        2: '(1. Chor:) / Es spreche Israel: / (2. Chor:) / "Ja, ewig währet seine Huld."',
        3: '(1. Chor:) / Es spreche Aarons Haus: / (2. Chor:) / "Ja, ewig währet seine Huld."',
        4: '(1. Chor:) / Es mögen alle sprechen, die Jahwe fürchten: / (2. Chor:) / "Ja, ewig währet seine Huld."',
        5: '(Der Chorführer allein im Namen der ganzen Festgemeinde:) / Als ich aus der Bedrängnis Jahwe anrief, / Da erhörte mich Jah und machte mich frei.',
        6: 'Ist Jahwe mit mir, so fürchte ich nichts: / Was können mir Menschen tun?',
        7: 'Tritt Jahwe für mich als Helfer auf, / So schau ich siegreich auf meine Hasser.',
        8: '(Eine Einzelstimme des Festchors:) / Es ist besser, bei Jahwe Zuflucht zu suchen / (Der ganze Chor:) / Als zu vertrauen auf Menschen.',
        9: '(Eine Einzelstimme des Festchors:) / Es ist besser, bei Jahwe Zuflucht zu suchen / (Der ganze Chor:) / Als zu vertrauen auf Fürsten.',
        10: '(Der siegreiche Feldherr allein:) / Es haben mich alle Heiden umringt, / Doch in Jahwes Namen zerhieb ich sie.',
        11: 'Sie haben mich umringt, ja immer wieder umringt; / Doch in Jahwes Namen zerhieb ich sie.',
        12: 'Sie haben mich sogar wie Bienen umringt, / Doch wie ein Dornenfeuer sind sie erloschen: / In Jahwes Namen zerhieb ich sie.',
        13: 'Man hat mich zwar heftig gestoßen, damit ich käme zu Fall, / Doch Jahwe hat mir geholfen.',
        14: 'Mein Sieg und mein Sang war Jah, / Er ward meine Rettung.',
        15: '(Eine Einzelstimme des Festchors:) / Ein Jubel- und Siegesruf schallt in den Zelten der Frommen: / (Der ganze Festchor:) / "Jahwes Rechte tut mächtige Taten.',
        16: 'Jahwes Recht ist hoch erhoben, / Jahwes Rechte tut mächtige Taten."',
        17: '(Eine Einzelstimme des Festchors:) / Ich werde nicht sterben, sondern leben / Und verkünden die Werke Jahs.',
        18: '(Der siegreiche Feldherr allein nach der Ankunft des Festzuges vor den Tempeltoren:) / Hart zwar hat Jah mich gezüchtigt, / Aber dem Tod mich nicht preisgegeben.',
        19: 'Tut mir die Tore auf, durch die nur Gerechte ziehn; / Eingehn will ich in sie, ich will Jah danken!',
        20: 'Dies ist das Tor, das zu Jahwe führt: / Gerechte dürfen hier eingehn.',
        21: '(Der siegreiche Feldherr allein:) / Dir dank ich, daß du mich erhört / Und mir Errettung gebracht hast.',
        22: '(Der Chor der Priester vom Tempel aus:) / Der Stein, den die Bauleute verworfen haben, / Der ist zum Eckstein geworden.',
        23: '(Der ganze Festchor:) / Von Jahwe ist dies geschehn: / Wunderbar ist es in unsern Augen.',
        24: '(Der Chor der Priester:) / Dies ist der Tag, den Jahwe gemacht. / Laßt uns jubeln und sein uns freun!',
        25: '(Der ganze Festchor:) / Ach, Jahwe, gewähre doch Hilfe! / Ach, Jahwe, gib doch Gedeihn!',
        26: '(Der Chor der Priester antwortet darauf:) / Gesegnet sei er, der da kommt, mit Jahwes Namen! / Wir haben euch gesegnet von Jahwes Tempel aus.',
        27: '(Der ganze Festchor:) / Ein starker Gott ist Jahwe: er hat uns Licht gespendet. / (Der Chor der Priester:) / Bindet die Opfertiere so zahlreich an mit Stricken, / (Daß sie den Vorhof füllen) / Bis an die Hörner des Altars!',
        28: '(Der siegreiche Feldherr allein:) / Mein starker Gott bist du: ich will dir danken. / Du bist mein Gott: dich will ich rühmen.',
        29: '(Der ganze Festchor und der Chor der Priester, also die ganze Festversammlung mit einem Munde:) / Danket Jahwe, denn er ist gütig; / Ja, ewig währet seine Huld!',
    },
    119: {
        1: 'Alle sind glücklich zu preisen, die da untadelig wandeln, / Die einhergehn nach Jahwes Gesetz.',
        2: 'Alle sind glücklich zu preisen, die seine Zeugnisse halten, / Die ihn suchen von ganzem Herzen.',
        3: 'Auch keine Frevel verüben, / Sondern in seinen Wegen gehn.',
        4: 'Aufgestellt hast du deine Befehle, / Daß man sie treu erfüllen soll.',
        5: 'Ach, stünde doch mein Wandel fest, / Indem ich deine Gesetze hielte!',
        6: 'Alsdann werd ich nicht zuschanden, / Wenn ich auf all deine Gebote blicke.',
        7: 'Aufrichtigen Herzens dank ich dir, / Wenn ich deine gerechten Befehle lerne.',
        8: 'Auf deine Satzungen achte ich: / Verlaß mich nicht völlig!',
        9: 'Bei einem Jüngling bleibt sein Wandel rein, / Wenn er ihn führt nach deinem Wort.',
        10: 'Begehrt hab ich dein Wort von ganzem Herzen, / Laß mich nicht irren von deinen Geboten!',
        11: 'Bewahret hab ich dein Wort in meinem Herzen, / Damit ich nicht sündige wider dich.',
        12: 'Besungen mit Lobpreis seiest du, Jahwe, / Lehre mich deine Satzungen!',
        13: 'Bekundet hab ich mit meinen Lippen / Alle Ordnungen deines Mundes.',
        14: 'Betracht ich den Wandel, den deine Zeugnisse fordern, / So freu ich mich stets wie über allerlei Reichtum.',
        15: 'Bei deinen Befehlen soll mein Sinnen verweilen, / Und blicken will ich auf deine Pfade.',
        16: 'Bei deinen Satzungen will ich mich ergötzen, / Will nicht vergessen deine Worte.',
        17: 'Gewähre deinem Knechte Gutes, daß ich leben bleibe, / So will ich deine Worte halten.',
        18: 'Gib mir offne Augen, / Damit ich erkenne die Wunder in deinem Gesetz.',
        19: 'Gast nur bin ich auf Erden: / Verbirg vor mir nicht deine Gebote!',
        20: 'Ganz verzehrt hat sich meine Seele vor Sehnsucht / Nach deinen Rechten zu jeder Zeit.',
        21: 'Gescholten hast du Frevelhafte. / Fluch treff alle, die deine Gebote verlassen!',
        22: 'Gespött und Schande, die ich erfahre, nimm weg! / Denn deine Zeugnisse halte ich.',
        23: 'Gingen auch Fürsten wider mich an mit feindlicher Rede: / Dein Knecht sinnt doch über deine Satzungen nach.',
        24: 'Gar meine Lust sind deine Zeugnisse, / Sie sind meine Berater.',
        25: 'Dem Staub klebt meine Seele an; / Belebe mich wieder nach deinem Wort!',
        26: 'Dir hab ich mein Los geschildert: da erhörtest du mich. / Lehre mich deine Satzungen!',
        27: 'Den Weg, den deine Befehle gebieten, laß mich verstehn! / Denn über deine Wunder will ich sinnen.',
        28: 'Durch Kummer zerfließt meine Seele: / Richte mich auf nach deinen Verheißungsworten!',
        29: 'Den Weg der Lüge halte mir fern, / Begnade mich aber mit deiner Lehre!',
        30: 'Den Weg der Treue hab ich erwählt, / Deine Rechte mir vorgesetzt.',
        31: 'Deine Zeugnisse, Jahwe, halt ich fest; / Laß mich nicht zuschanden werden!',
        32: 'Den Weg, den deine Gebote weisen, will ich laufen, / Denn du erfüllst mich mit Einsicht.',
        33: 'Helle mir auf, o Jahwe, deiner Satzungen Weg, / Damit ich ihn immer beachte!',
        34: 'Hilf mir zur rechten Erkenntnis, daß ich deine Lehre bewahre / Und sie von ganzem Herzen befolge!',
        35: 'Hinführen wollest du mich auf deiner Gebote Pfad, / Denn ich habe Gefallen daran.',
        36: 'Hinlenken wollest du mein Herz zu deinen Gesetzen / Und nicht zu ungerechtem Gewinn.',
        37: 'Hinweg zieh meine Augen, daß sie nicht nach dem Eitlen schaun, / Auf deinen Wegen belebe mich!',
        38: 'Halt deinem Knechte deine Verheißung, / Damit ich wachse in Ehrfurcht vor dir!',
        39: 'Halt fern von mir die Schmach, vor der mir graut! / Denn deine Urteilssprüche sind gut.',
        40: 'Hat mich nicht stets verlangt nach deinen Befehlen? / Durch deine Gerechtigkeit belebe mich!',
        41: 'Und laß, o Jahwe, deine Huld mich reich erfahren. / Dein Heil nach deiner Verheißung!',
        42: 'Und dann will ich auch Rede stehn dem, der mich lästert; / Denn ich vertraue auf dein Wort.',
        43: 'Und entzieh doch meinem Munde das Wort der Wahrheit nicht, / Denn auf deine Rechte hoffe ich.',
        44: 'Und deine Weisung will ich stets beachten, / Immer und ewiglich.',
        45: 'Und so werd ich dann auch getrost und unbefangen wandeln, / Denn in deinen Geboten hab ich Rat gesucht.',
        46: 'Und von deinen Zeugnissen will ich reden vor Königen / Furchtlos und ohne Scheu.',
        47: 'Und ich erfreue mich an deinen Geboten, / Die ich liebgewonnen habe.',
        48: 'Und ich will meine Hände erheben zu deinen Geboten, (die ich liebgewonnen habe,) / Nachsinnen will ich über deine Satzungen.',
        49: 'Sei eingedenk des Worts, das du zu deinem Knecht geredet, / Weil du (auf einen guten Ausgang) mich hast hoffen lassen.',
        50: 'So fand ich Trost in meinem Elend, (als ich inneward) / Daß dein Verheißungswort mich neubelebte.',
        51: 'Stolze haben mich gar sehr verspottet, / Dennoch bin ich von deinem Gesetz nicht abgewichen.',
        52: 'Sooft ich daran denke, wie du von altersher gerichtet hast, / Werd ich, o Jahwe, auch getröstet.',
        53: 'Starker Zorn hat mich erfaßt den Frevlern gegenüber, / Die dein Gesetz verlassen haben.',
        54: 'Siegeslieder sind mir deine Satzungen / Im Hause meiner Fremdlingschaft.',
        55: 'Sogar des Nachts hab ich gedacht, o Jahwe, deines Namens, / Und darum hab ich deine Weisung auch befolgt.',
        56: 'Solches ist mir zuteil geworden: / Daß ich deine Befehle halte.',
        57: 'Geschenkt — so habe ich gesagt — ist mir, o Jahwe, deine Gnade, / Daß ich deine Worte befolgen darf.',
        58: 'Gesucht hab ich von ganzem Herzen deine Huld: / Sei mir denn gnädig nach deiner Verheißung!',
        59: 'Gedacht hab ich an meine Wege / Und habe meine Füße dann gelenkt zu deinen Zeugnissen.',
        60: 'Geeilt bin ich dabei und habe nicht gezaudert, / Deine Gebote zu halten.',
        61: 'Gottlose haben mich mit Stricken umringt: / Aber dein Gesetz hab ich nicht vergessen.',
        62: 'Gegen Mitternacht steh ich auf, um dir zu danken / Für deine gerechten Gerichtsurteile.',
        63: 'Genosse bin ich allen, die dich fürchten / Und deine Befehle befolgen.',
        64: 'Gefüllt mit deiner Güte, Jahwe, ist die Erde: / Lehre mich nun deine Satzungen!',
        65: 'Tröstliches hast du deinem Knechte erwiesen, / Jahwe, nach deinen Worten.',
        66: 'Treffliche Klugheit und Einsicht lehre mich! / Denn deinen Geboten vertrau ich.',
        67: 'Trugwege bin ich gewandelt, eh ich ins Elend geriet; / Nun aber acht ich auf dein Gebot.',
        68: 'Treusorgend bist du und voller Güte: / Lehre mich deine Satzungen!',
        69: 'Trugvoll haben Frevler mir Lügen angedichtet: / Ich aber halte dennoch mit ganzem Herzen deine Befehle.',
        70: 'Töricht und fühllos ist ihr Herz; / Doch mein Entzücken ist dein Gesetz.',
        71: 'Traun, heilsam war mir des Leidens Schule, / Damit ich deine Satzungen lernte.',
        72: 'Teurer ist mir deines Mundes Gesetz / Als reiche Schätze an Silber und Gold.',
        73: 'Ja, deine Hände haben mich geschaffen und bereitet: / Gib mir nun auch Einsicht, daß ich deine Gebote lerne!',
        74: 'Jeder, der dich fürchtet, wird freudig auf mich blicken; / Denn ich habe darauf geharrt, daß sich dein Verheißungswort erfülle.',
        75: 'Ich weiß, o Jahwe: gerecht sind deine Gerichte, / Und weil du es treu mit mir meinst, hast du mich in Trübsal geführt.',
        76: 'In deiner Gnade laß mich nun aber auch Trost erfahren, / Wie du es deinem Knechte verheißen!',
        77: 'In dein Erbarmen hülle mich ein, damit ich lebe! / Denn dein Gesetz ist meine Lust.',
        78: 'In Schande laß fallen die Frevelhaften, weil sie mich mit Lügen ins Elend gebracht! / Ich aber will über deine Befehle sinnen.',
        79: 'Ja, mögen sich zu mir wenden, die dich fürchten / Und die deine Zeugnisse anerkennen!',
        80: 'In deinen Satzungen soll mein Herz beständig leben, / Damit ich nicht zuschanden werde.',
        81: 'Klagend hat meine Seele nach deiner Hilfe geschmachtet: / Auf dein Wort hab ich geharrt.',
        82: 'Konnten nicht meine Augen vergehn, als ich nach deinem Wort ausschaute / Und (ängstlich) fragte: "Wann wirst du mich trösten?"',
        83: 'Kann man auch von mir sagen: / "Der ist wie ein Schlauch im Rauch" — / Deine Satzungen hab ich doch nimmer vergessen.',
        84: 'Kurz sind die Lebenstage deines Knechts. / Wann wirst du nun das Gericht vollstrecken an meinen Verfolgern?',
        85: 'Kerkergruben haben mir Gottvergeßne gegraben, / Sie, die nicht handeln nach deinem Gesetz.',
        86: 'Können doch all deine Gebote nichts als ein Ausfluß deiner Treue sein! / Sie aber haben mich mit Lügen verfolgt: hilf du mir!',
        87: 'Kümmerlich hätten sie mich beinah in der Grube sterben lassen, / Aber trotzdem hab ich deine Befehle nicht verlassen.',
        88: 'Könnt ich doch wieder aufleben durch deine Güte! / Dann will ich auch das Zeugnis deines Mundes halten.',
        89: 'Lebt, o Jahwe, nicht in Ewigkeit / Dein Wort im Himmel fort?',
        90: 'Lang bis ins fernste Geschlecht währt deine Treu; / Du hast die Erde gegründet, und sie bleibt.',
        91: 'Laut deiner Ordnung stehn sie noch heute; / Denn alles ist dir untertan.',
        92: 'Ließe mich dein Gesetz nicht immer wieder Freude empfinden: / Ich wäre vergangen in meinem Elend.',
        93: 'Lebenslang werd ich deine Befehle nicht vergessen, / Denn durch sie hast du mich im Dasein erhalten.',
        94: 'Liebend bin ich dein: drum rette mich! / Deine Befehle suche ich ja.',
        95: 'Listig haben mir Frevler nachgestellt, um mich zu töten; / Dennoch werd ich auf deine Zeugnisse merken.',
        96: 'Läßt sich auch sehn, daß alles Vollkommne begrenzt ist: / Dein Gebot reicht über die Maßen weit.',
        97: 'Mit ganzer Seele lieb ich dein Gesetz; / Den ganzen Tag sinn ich darüber nach.',
        98: 'Mich werden deine Gebote weiser machen, als meine Feinde sind; / Denn sie sind mein für immer.',
        99: 'Meine Lehrer alle übertreffe ich an Einsicht, / Denn über deine Zeugnisse sinne ich.',
        100: 'Mehr als Alte werd ich mir Verstand erwerben, / Wenn ich deinen Befehlen folge.',
        101: 'Mit allen bösen Pfaden haben meine Füße nichts gemein, / Damit ich deine Gebote mit der Tat erfülle.',
        102: 'Mitnichten bin ich von deinen Rechten gewichen; / Du hast mich ja belehrt.',
        103: 'Meinem Geschmack sind deine Worte lieber / Als Honig meinem Mund.',
        104: 'Mit Einsicht erfüllen mich deine Befehle; / Drum haß ich jeden Lügenpfad.',
        105: 'Nur dein Wort ist eine Leuchte meinem Fuß / Und ein Licht für meinen Weg.',
        106: 'Nimmer werd ich brechen, was ich eidlich gelobt: / "Deine gerechten Vorschriften will ich befolgen."',
        107: 'Niedergebeugt bin ich gar sehr; / Jahwe, belebe mich wieder nach deinem Wort!',
        108: 'Nimm wohlgefällig an, o Jahwe, die willigen Opfer meines Mundes / Und lehre mich deine Gebote!',
        109: 'Nicht einen Augenblick bin ich des Lebens sicher: / Dennoch hab ich dein Gesetz nicht vergessen.',
        110: 'Nichtswürdige haben mir Schlingen gelegt; / Aber von deinen Befehlen bin ich nicht abgeirrt.',
        111: 'Nie werd ich deine Zeugnisse fahren lassen, / Denn sie sind meines Herzens Wonne.',
        112: 'Neigen lassen hab ich mein Herz, deine Satzungen zu erfüllen: / Das bringt ewigen Lohn.',
        113: 'Solche, die sich absondern, hasse ich; / Doch dein Gesetz hab ich lieb.',
        114: 'Sichrer Schutz und Schild bist du für mich; / Auf dein Wort hab ich geharrt.',
        115: 'Sondert euch ab von mir, ihr Übeltäter, / Damit ich meines Gottes Gebote halte!',
        116: 'Sei du meine Stütze nach deiner Verheißung, damit ich am Leben bleibe, / Und laß mich nicht zuschanden werden mit meiner Hoffnung!',
        117: 'Sei du mein sichrer Halt, damit ich gerettet werde! / Dann will ich stets mit Vertraun auf deine Satzungen schaun.',
        118: 'Sie, die von deinen Satzungen irren, hast du immer verworfen; / Denn nichts als Lüge ist ihr verführerisch Tun.',
        119: 'So wie Schlacken hast du alle Frevler des Landes hinweggeräumt; / Drum lieb ich deine Zeugnisse.',
        120: 'Sieh, ich schaudre in Angst vor dir; / Denn vor deinen Gerichten fürcht ich mich.',
        121: 'Ausgeübt hab ich Recht und Gerechtigkeit: / So gib mich denn nicht meinen Drängern preis!',
        122: 'Auf deines Knechtes Wohl sei du bedacht, / Daß Frevler mich nicht vergewaltigen!',
        123: 'Ausgeschaut hab ich voll Sehnsucht, daß mir Hilfe komme / Und deine Verheißung sich erfülle.',
        124: 'An deinem Knechte handle du nach deiner Huld / Und lehre mich deine Satzungen!',
        125: 'Ach, sieh, ich bin dein Knecht: unterweise mich, / Daß ich deine Zeugnisse erkenne!',
        126: "An der Zeit ist's für Jahwe, zu handeln: / Sie haben ja dein Gesetz gebrochen.",
        127: 'Aus diesem Grunde lieb ich deine Gebote / Mehr als Gold und gediegen Gold.',
        128: 'Aus diesem Grunde hab ich auch stets all deine Befehle aufrechtgehalten / Und jeglichen Lügenpfad gehaßt.',
        129: 'Fürwahr, deine Zeugnisse sind wunderbar; / Darum bewahrt sie auch meine Seele.',
        130: 'Führst du in deine Gebote ein, so wird es licht: / Einfältige werden verständig.',
        131: 'Frei hab ich meinen Mund geöffnet voll Verlangen; / Denn nach deinen Geboten sehnte ich mich.',
        132: 'Führ mir deine Gnade zu: / Das dürfen ja auch erwarten, die deinen Namen lieben.',
        133: 'Fest mach meine Schritte durch dein Wort / Und laß mich nichts Böses beherrschen!',
        134: 'Frei laß mich sein von der Menschen Druck, / Damit ich deine Befehle erfülle!',
        135: 'Für deinen Knecht laß du dein Antlitz leuchten / Und lehre mich deine Satzungen!',
        136: 'Flossen nicht aus meinen Augen Wasserbäche / Über die, die dein Gesetz nicht halten?',
        137: 'Zeigst du nicht, Jahwe, dich gerecht? / Drum ist auch all dein Walten richtig.',
        138: 'Zugeteilt hast du deine Zeugnisse / In Treue und großer Wahrhaftigkeit.',
        139: 'Zehrender Eifer hat mich vernichtet; / Denn meine Feinde haben deine Worte vergessen.',
        140: 'Zerschmolzen gleichsam in Feuer, ganz echt und bewährt ist dein Wort, / Und dein Knecht hat es lieb.',
        141: 'Zwar bin ich jung und verachtet; / Doch deine Befehle hab ich nicht vergessen.',
        142: 'Zuverlässig gerecht bleibt deine Gerechtigkeit auf ewig, / Und dein Gesetz bleibt Wahrheit.',
        143: 'Zwang und Drangsal haben mich getroffen; / Doch deine Gebote sind meine Lust.',
        144: 'Zu aller Zeit sind deine Zeugnisse gerecht: / Laß mich sie verstehn, damit ich lebe!',
        145: 'Kraftvoll hab ich dich angerufen: / "Erhöre mich, Jahwe, deine Satzungen will ich halten!"',
        146: 'Komm mir zu Hilfe, wenn ich dich rufe: / So will ich auf deine Zeugnisse achten.',
        147: 'Kaum graute der Morgen, da flehte ich schon: / "Ich habe geharrt, daß du dein Wort erfüllest."',
        148: 'Konnte doch keine Nachtwache beginnen, ohne daß ich meine Augen schon offen hatte, / Um nachzusinnen über dein Wort.',
        149: 'Klagend ruf ich: hör mich in deiner Huld! / Nach deiner Treue, o Jahwe, belebe mich wieder!',
        150: 'Kommen mir nahe, die Schandtaten verüben wollen, / Menschen, die fern sind von deinem Gesetz:',
        151: 'Kommst du mir auch nahe, o Jahwe — / All deine Gebote aber sind Wahrheit.',
        152: 'Kann ich doch längst schon aus deinen Zeugnissen sehn, / Daß du sie für immer verordnet hast.',
        153: 'Richte den Blick auf mein Elend und reiß mich heraus, / Denn dein Gesetz hab ich nimmer vergessen.',
        154: 'Recht schaffe du mir und erlöse mich, / Nach deiner Verheißung belebe mich wieder!',
        155: 'Rettung bleibt den Frevlern fern, / Denn deine Satzungen haben sie nicht gesucht.',
        156: 'Reich, o Jahwe, ist dein Erbarmen; / Nach deinem Urteil belebe mich wieder!',
        157: 'Reichlich bin ich verfolgt und bedrängt, / Aber doch nicht gewichen von deinen Geboten.',
        158: 'Recht von Ekel ward ich erfaßt, wenn ich Treulose sah, / Weil sie dein Wort nicht hielten.',
        159: 'Rechne mir zu, daß ich deine Befehle liebe; / Jahwe, belebe mich wieder nach deiner Huld!',
        160: "Richtig ist's: deines Wortes Inhalt ist Wahrheit, / Und ewig währt all dein gerechtes Walten.",
        161: 'Sonder Ursach haben mich Fürsten verfolgt, / Doch nur vor deinem Worte hat mein Herz gezittert.',
        162: 'So froh bin ich ob deiner Verheißung / Wie einer, der viel Beute findet.',
        163: 'Schändliche Lüge hab ich stets gehaßt und verabscheut, / Dein Gesetz aber hab ich lieb.',
        164: 'Siebenmal täglich hab ich dich stets gepriesen / Ob deiner gerechten Gerichtsurteile.',
        165: 'Schönen Frieden genießen alle, die deine Lehre lieben, / Und sie straucheln nimmer.',
        166: 'Sehnend hab ich, Jahwe, deiner Hilfe geharrt, / Und deine Gebote erfülle ich stets.',
        167: 'Scheu befolg ich deine Befehle, / Und ich liebe sie sehr.',
        168: 'Scheu halt ich stets deine Ordnungen und Befehle, / Weil du ja all meine Wege kennst.',
        169: 'Tu auf meinem Ruf den Weg zu dir, o Jahwe, / In deinem Wort mach mich verständig!',
        170: 'Tu auf meinem innigen Flehn den Weg zu dir, / Nach deiner Verheißung rette mich!',
        171: 'Triefen sollen meine Lippen von Lobgesang, / Wenn du mich deine Satzungen lehrst.',
        172: 'Tönen soll von meiner Zunge das Loblied auf deine Verheißung; / Denn deine Gebote sind alle gerecht.',
        173: 'Tritt du mir als Helfer zur Seite! / Denn deine Befehle hab ich zu Führern erkoren.',
        174: 'Tiefes Sehnen nach deinem Heil erfüllt mich, o Jahwe, / Und dein Gesetz ist meine Lust.',
        175: 'Teile mir Leben zu, damit ich dich lobe! / Und deine Rechte mögen mir helfen.',
        176: 'Tret ich auf einen Irrweg wie ein verloren Schaf, / Dann suche du deinen Knecht; denn deine Gebote vergesse ich nicht.',
    },
    120: {
        1: 'Ein Stufenlied. / Zu Jahwe hab ich gerufen in meiner Not, / Und er hat mich erhört.',
        2: 'Jahwe, so rette mich auch jetzt von der Lügenlippe, / Von arglistiger Zunge!',
        3: 'Was wird er dir geben, was dir zufügen, / Du arglistige Zunge?',
        4: 'Scharfe Pfeile eines Starken / Mit glühenden Kohlen aus Ginstersträuchern.',
        5: 'Weh mir, daß ich ein Fremdling bin in Meschech, / Bei Kedars Zelten wohnen muß!',
        6: 'Zu lange schon hab ich weilen müssen / Bei denen, die Frieden hassen.',
        7: 'Ich will Frieden; doch wenn ich nur rede, / So beginnen sie Krieg.',
    },
    121: {
        1: 'Ein Stufenlied. / Ich hebe meine Augen zu den Bergen: / Woher wird mir Hilfe kommen?',
        2: 'Meine Hilfe kommt von Jahwe, / Der Himmel und Erde geschaffen hat.',
        3: 'Wird er deinen Fuß wohl wanken lassen? / Wird etwa dein Hüter schlummern?',
        4: 'Sieh, nicht wird schlummern oder gar schlafen / Israels Hüter.',
        5: 'Jahwe ist dein Hüter, / Jahwe ist dein Schatten über deiner rechten Hand.',
        6: 'Tagsüber wird dich die Sonne nicht stechen / Und der Mond nicht des Nachts.',
        7: 'Jahwe wird dich behüten vor allem Übel, / Er wird deine Seele behüten.',
        8: 'Jahwe wird deinen Ausgang und Eingang behüten / Von nun an bis in Ewigkeit.',
    },
    122: {
        1: 'Ein Stufenlied von David. / Ich hab mich gefreut über die, die zu mir sagten: / "Zu Jahwes Hause wollen wir wallen."',
        2: 'Dann standen endlich unsre Füße / In deinen Toren, Jerusalem.',
        3: 'Jerusalem, du wiedererbaute, / Als eine Stadt, die eng in sich verbunden!',
        4: 'Dorthin zogen die Stämme hinauf, / Die Stämme Jahs — / Wie es Israel vorgeschrieben —, / Um Jahwes Namen zu preisen.',
        5: 'Dort standen einst die Stühle für die Gerichtsverhandlung, / Stühle für Davids Haus.',
        6: 'Erbittet Jerusalem Frieden! / Wohl geh es denen, die dich lieben!',
        7: 'Friede walte in deinen Mauern, / Sicherheit in deinen Palästen!',
        8: 'Um meiner Brüder und Freunde willen / Will ich doch sagen: "Friede walte in dir!"',
        9: 'Aus Liebe zum Hause Jahwes, unsers Gottes, / Will ich dein Bestes suchen.',
    },
    123: {
        1: 'Ein Stufenlied. / Zu dir hab ich meine Augen erhoben, / Der du im Himmel thronst.',
        2: 'Sieh, wie die Augen der Knechte auf die Hand ihres Herrn, / Wie die Augen der Magd auf ihrer Gebieterin Hand: / So schaun unsre Augen auf Jahwe, unsern Gott, / Bis er sich uns gnädig erzeigt.',
        3: 'Sei uns gnädig, o Jahwe, sei uns gnädig, / Denn wir sind reichlich mit Schmähung gesättigt!',
        4: 'Reichlich hat unsre Seele satt / Den Hohn der Sichern, die Schmähung der Stolzen.',
    },
    124: {
        1: 'Ein Stufenlied von David. / "Wäre Jahwe nicht für uns gewesen", / So möge Israel sprechen,',
        2: '"Wäre Jahwe nicht für uns gewesen, / Als Menschen sich wider uns stellten,',
        3: 'Dann hätten sie uns lebendig verschlungen, / Als ihr Zorn gegen uns entflammte;',
        4: 'Dann hätten die Wasser uns überflutet, / Ein Strom wäre über uns hingerauscht;',
        5: 'Dann wären über uns hingerauscht / Die wildbrausenden Wasser."',
        6: 'Gepriesen sei Jahwe, der uns nicht hingegeben / Ihren Zähnen als einen Raub!',
        7: 'Unsre Seele gleicht einem Vöglein, / Das des Voglers Netz entronnen. / Das Netz ist zerrissen, und wir sind frei!',
        8: 'Unsre Hilfe liegt im Namen Jahwes, / Der Himmel und Erde geschaffen hat.',
    },
    125: {
        1: 'Ein Stufenlied. / Die auf Jahwe vertraun, die gleichen dem Zionsberg, / Der nicht wankt, der in Ewigkeit bleibt.',
        2: 'Rings um Jerusalem her sind Berge. / So ist Jahwe rings um sein Volk / Von nun an bis in Ewigkeit.',
        3: 'Denn des Frevlers Zepter soll nicht bleiben / Auf der Gerechten Erbe, / Damit nicht etwa die Gerechten / Zum Frevel ausstrecken ihre Hände.',
        4: 'Tu wohl, o Jahwe, den Guten / Und denen, die redlichen Herzens sind!',
        5: 'Die aber auf ihre krummen Pfade abbiegen, / Die lasse Jahwe hinfahren samt den Übeltätern! / Friede sei über Israel!',
    },
    126: {
        1: 'Als Jahwe Zions Wandrer in die Heimat führte, / Waren wir wie Träumende.',
        2: 'Damals war unser Mund voll Lachens / Und unsre Zunge voll Jubels. / Damals sagte man unter den Heiden: / "Großes hat Jahwe an ihnen getan!"',
        3: 'Ja, Großes hat Jahwe an uns getan: / Darüber waren wir fröhlich.',
        4: 'Wende nun, Jahwe, auch unser Geschick / Gleich Regenbächen im Mittagsland.',
        5: 'Die mit Tränen säen, / Werden mit Jubel ernten.',
        6: 'Wohl geht man jetzt mit Weinen dahin, / Indem man den Samen zur Aussaat trägt. / Aber man kommt mit Jubel an, / Indem man trägt seine Garben.',
    },
    127: {
        1: 'Ein Stufenlied von Salomo. / Wenn Jahwe das Haus nicht baut, / So mühen sich vergeblich ab, die daran bauen. / Wenn Jahwe die Stadt nicht behütet, / So wachen die Wächter vergeblich.',
        2: "Vergeblich ist's, daß ihr früh aufsteht / Und spät bei der Arbeit sitzt, / Die ihr esset mühsam erworbnes Brot. / Seinen Freunden gibt er genug im Schlaf.",
        3: 'Sieh, Jahwes Gabe sind Kinder, / Lohn ist Leibesfrucht.',
        4: 'Wie Pfeile in eines Helden Hand, / So sind die Kinder der Jugend.',
        5: 'Heil dem Manne, / Des Köcher mit ihnen gefüllt ist! / Sie werden nicht zuschanden, / Wenn sie mit Feinden reden im Tor.',
    },
    128: {
        1: 'Ein Stufenlied. / Heil dem, der Jahwe fürchtet, / Der da wandelt auf seinen Wegen!',
        2: 'Deiner Hände Erwerb — fürwahr, du wirst ihn genießen: / Heil dir! es wird dir wohl ergehn.',
        3: 'Dein Weib wird sein wie ein fruchtbarer Weinstock / Drinnen in deinem Hause; / Deine Kinder sind wie Ölbaumpflänzchen / Rings um deinen Tisch.',
        4: 'Ja wahrlich, so wird gesegnet der Mann, / Der Jahwe fürchtet.',
        5: 'Es segne dich Jahwe von Zion her, / Daß du schauest Jerusalems Glück / Dein ganzes Leben lang,',
        6: 'Und schauest Kindeskinder! / Friede sei über Israel!',
    },
    129: {
        1: 'Ein Stufenlied. / "Oft haben sie mich bedrängt von meiner Jugend an", / So möge Israel sprechen,',
        2: '"Oft haben sie mich bedrängt von meiner Jugend an, / Doch sie haben mich nicht überwältigt.',
        3: 'Auf meinem Rücken haben Pflüger gepflügt / Und ihre Furchen lang gezogen.',
        4: 'Doch Jahwe, der Gerechte, / Er hat zerhaun der Frevler Strick."',
        5: 'Zuschanden werden und rückwärtsweichen / Sollen alle, die Zion hassen.',
        6: "Sie sollen dem Gras auf den Dächern gleichen: / Das ist schon dürr, noch ehe man's ausrauft.",
        7: 'Damit füllt der Schnitter nicht seine Hand / Noch seinen Arm der Garbenbinder.',
        8: 'Die vorübergehen sagen auch nicht: / "Jahwes Segen sei über euch!" / Wir aber haben euch in Jahwes Namen gesegnet.',
    },
    130: {
        1: 'Ein Stufenlied. / Aus Tiefen hab ich, Jahwe, zu dir gerufen.',
        2: 'Adonái, hör meine Stimme! / Laß doch deine Ohren merken / Auf mein lautes Flehn!',
        3: 'Wenn du Sünden anrechnest, Jah, / Adonái, wer kann dann bestehn?',
        4: 'Ja, du vergibst, / Damit man dich fürchte.',
        5: 'Jahwes habe ich stets geharrt; / Es hat meine Seele geharrt, / Schon immer hoffte ich auf sein Wort.',
        6: 'Meine Seele harrt Adonáis, / Mehr, als Wächter des Morgens harren, / Ja, Wächter des Morgens.',
        7: 'Israel, harr auf Jahwe! / Denn bei Jahwe ist die Gnade, / Und reichlich ist bei ihm Erlösung.',
        8: 'Ja, er wird Israel erlösen / Von allen seinen Sünden.',
    },
    131: {
        1: 'Ein Stufenlied von David. / Jahwe, mein Herz ist nicht hochmütig, / Und meine Augen erheben sich nicht stolz. / Auch geh ich nicht um mit Dingen, / Die zu groß und schwer für mich sind.',
        2: 'Ich habe vielmehr meine Seele gestillt und beruhigt. / Wie ein entwöhntes Kind an der Brust seiner Mutter liegt, / So ruht meine Seele entwöhnt in mir.',
        3: 'Israel, harre auf Jahwe / Von nun an bis in Ewigkeit!',
    },
    132: {
        1: 'Ein Stufenlied. / Gedenke, Jahwe, dem David / All die Opfer, die er gebracht.',
        2: 'Er leistete Jahwe einen Schwur, / Gelobte dem starken Gott Jakobs:',
        3: '"Wahrlich, nicht geh ich ins Zelt meines Hauses, / Nicht besteig ich das Bett meines Lagers,',
        4: 'Nicht gönne ich Schlaf meinen Augen / Noch meinen Wimpern Schlummer:',
        5: 'Bis ich eine Stätte für Jahwe gefunden, / Eine Wohnung für Jakobs starken Gott."',
        6: 'Sieh, wir hörten, sie sei in Efrâta, / Wir haben sie dann in Jaars Gefilden gefunden.',
        7: 'So laßt uns denn in seine Wohnung gehn, / Uns niederwerfen vor seiner Füße Schemel.',
        8: 'Auf, Jahwe, begib dich zu deiner Ruhstatt, / Du und die Lade, das Bild deiner Macht!',
        9: 'Deine Priester werden dir dienen in Treue, / Und deine Frommen werden sich freun.',
        10: 'Um Davids, deines Knechtes, willen / Versage nicht deines Gesalbten Bitte!',
        11: "Jahwe hat David geschworen / — Wahr ist's, nicht nimmt er's zurück —: / Von der Frucht deines Leibes / Will ich einen Mann auf den Thron dir setzen.",
        12: 'Halten deine Söhne den Bund mit mir / Und mein Zeugnis, das ich sie lehre: / So sollen auch ihre Söhne für immer / Dir auf dem Throne sitzen."',
        13: 'Denn Jahwe hat Zion erwählt, / Hat es zu seinem Wohnsitz begehrt:',
        14: '"Dies ist meine Ruhstatt für immer; / Hier will ich bleiben, weil ich es begehrt.',
        15: 'Seine Nahrung will ich reichlich segnen, / Seine Armen sättigen mit Brot.',
        16: 'Seine Priester will ich kleiden in Heil, / Und seine Frommen sollen laut jauchzen.',
        17: 'Dort laß ich ein Horn für David sprossen: / Meinem Gesalbten hab ich eine Leuchte bereitet.',
        18: 'Seine Feinde will ich in Schande kleiden, / Aber auf ihm soll glänzen seine Krone."',
    },
    133: {
        1: "Ein Stufenlied von David. / Sieh, wie schön und wie lieblich ist's, / Wenn Brüder auch (friedlich) beisammen wohnen.",
        2: 'Das gleicht dem köstlichen Öl auf dem Haupt, / Das herabfloß auf den Bart, / Auf Aarons Bart, der niederwallte / Auf seiner Gewänder Rand.',
        3: 'Es gleicht auch dem Hermontau, / Der auf Zions Berg niederfällt. / Denn dorthin hat Jahwe den Segen entboten, / Leben für immer.',
    },
    134: {
        1: 'Ein Stufenlied. / (Ein Ruf der Gemeinde an die Tempelwächter:) / Wohlan, preist Jahwe, all ihr Knechte Jahwes Haus!',
        2: 'Hebt auf eure Hände zum Heiligtum / Und preist Jahwe!',
        3: '(Die Antwort der Tempelwächter an die Gemeinde:) / Es segne dich Jahwe von Zion her, / Der Schöpfer von Himmel und Erde!',
    },
    135: {
        1: 'Lobet Jah! / Lobt den Namen Jahwes, / Lobt ihn, ihr Knechte Jahwes,',
        2: 'Die ihr steht in Jahwes Haus, / In den Höfen des Hauses unsers Gottes!',
        3: 'Lobt Jah, denn Jahwe ist gütig, / Spielt seinem Namen, denn lieblich ist er!',
        4: 'Denn Jah hat Jakob erkoren, / Israel sich zum Eigentum erwählt.',
        5: 'Denn ich weiß wohl, daß Jahwe groß ist / Und unser Herr alle Götter überragt.',
        6: 'Alles, was Jahwe gefiel, das hat er gemacht / Im Himmel und auf Erden, / In den Meeren und allen Tiefen.',
        7: 'Er führt Wolken herauf vom Ende der Erde, / Läßt künden durch Blitze Gewitterregen, / Holt Wind aus seinen Speichern hervor.',
        8: 'Er schlug Ägyptens Erstgeburten / Von Menschen bis zum Vieh.',
        9: 'Er sandte Zeichen und Wunder / Wider dich, Ägyptenland, / Wider Pharao und all seine Knechte.',
        10: 'Er schlug viele Völker / Und tötete mächtige Könige.',
        11: 'Sihon, der Amoriter König, / Und Og, den König von Basan, / Ja, machte zunichte alle Reiche Kanaans.',
        12: 'Er gab ihr Land als Erbe, / Als Erbe Israel, seinem Volk.',
        13: 'Jahwe, dein Name währt ewig; / Dein Gedächtnis, Jahwe, bleibt für und für.',
        14: 'Denn Jahwe wird seinem Volk Recht schaffen / Und mit seinen Knechten Erbarmen haben.',
        15: 'Der Heiden Götzen sind Silber und Gold, / Das Gebilde von Menschenhand.',
        16: 'Sie haben einen Mund und können nicht reden, / Sie haben Augen und sehen doch nicht.',
        17: 'Ohren haben sie und hören nicht, / Noch haben sie Odem in ihrem Mund.',
        18: 'Ihnen gleich sind, die sie bilden — / Jeder, der ihnen vertraut.',
        19: 'Ihr von Israels Haus, preist Jahwe! / Ihr von Aarons Haus, preist Jahwe!',
        20: 'Ihr von Levis Haus, preist Jahwe! / Die ihr Jahwe fürchtet, preist Jahwe!',
        21: 'Gepriesen sei Jahwe von Zion aus, / Er, der in Jerusalem wohnt. / Lobt Jah!',
    },
    136: {
        1: '(Der Chor der Priester:) / — (Der Chor der Gemeinde:) / Dankt Jahwe, denn er ist gütig. / — Denn ewig währet seine Huld!',
        2: 'Dankt dem Gott der Götter. / — Denn ewig währet seine Huld!',
        3: 'Dankt dem Herrn der Herren. / — Denn ewig währet seine Huld!',
        4: '(Dankt) dem, der allein große Wunder tut. / — Denn ewig währet seine Huld!',
        5: '(Dankt) dem, der die Himmel mit Weisheit erschaffen. / — Denn ewig währet seine Huld!',
        6: '(Dankt) dem, der die Erde über die Wasser ausgebreitet. / — Denn ewig währet seine Huld!',
        7: '(Dankt) dem, der große Lichter erschaffen: / — Denn ewig währet seine Huld!',
        8: 'Die Sonne, um den Tag zu beherrschen, / — Denn ewig währet seine Huld!',
        9: 'Den Mond und die Sterne, um die Nacht zu beherrschen. / — Denn ewig währet seine Huld!',
        10: '(Dankt) dem, der die Ägypter schlug an ihren Erstgebornen / — Denn ewig währet seine Huld!',
        11: 'Und Israel aus dem Lande führte / — Denn ewig währet seine Huld!',
        12: 'Mit starker Hand und ausgerecktem Arm. / — Denn ewig währet seine Huld!',
        13: '(Dankt) dem, der das Schilfmeer in zwei Teile spaltete / — Denn ewig währet seine Huld!',
        14: 'Und Israel hindurchziehen ließ, / — Denn ewig währet seine Huld!',
        15: 'Doch Pharao und sein Heer ins Schilfmeer trieb. / — Denn ewig währet seine Huld!',
        16: '(Dankt) dem, der sein Volk in der Wüste führte. / — Denn ewig währet seine Huld!',
        17: '(Dankt) dem, der mächtige Könige schlug / — Denn ewig währet seine Huld!',
        18: 'Und stolze Könige tötete: / — Denn ewig währet seine Huld!',
        19: 'Sihon, der Amoriter König, / — Denn ewig währet seine Huld!',
        20: 'Und Og, den König von Basan, / — Denn ewig währet seine Huld!',
        21: 'Und ihr Land zum Erbe gab, / — Denn ewig währet seine Huld!',
        22: 'Zum Erbe Israel, seinem Knecht. / — Denn ewig währet seine Huld!',
        23: '(Dankt dem), der in unsrer Niedrigkeit an uns gedachte / — Denn ewig währet seine Huld!',
        24: 'Und uns von unsern Drängern befreite; / — Denn ewig währet seine Huld!',
        25: 'Der allen Lebewesen Speise gibt. / — Denn ewig währet seine Huld!',
        26: 'Dankt dem Gott des Himmels. / — Denn ewig währet seine Huld!',
    },
    137: {
        1: 'An den Flüssen Babels, daß saßen wir und weinten, / Wenn wir an Zion gedachten.',
        2: 'An den Weiden, die dort standen, / Hingen wir unsre Zithern auf.',
        3: 'Denn da wollten unsre Sieger von uns Lieder hören / Und unsre Quäler Freudengesang. / "Singt uns", so riefen sie (höhnisch), / "eins von den Zionsliedern!"',
        4: 'Wie sollten wir Jahwes Lieder singen / In einem fremden Lande?',
        5: 'Vergeß ich dein Jerusalem, / So sterbe mir ab meine rechte Hand!',
        6: 'Meine Zunge klebe an meinem Gaumen, / Wenn ich nicht dein gedenke, / Wenn mir nicht Jerusalem / Meine höchste Freude ist.',
        7: 'Gedenke, o Jahwe, Edoms Söhnen / Den Tag Jerusalems, / Die da riefen: "Nieder, nieder mit ihr / Bis auf den Grund!"',
        8: 'O Tochter Babels, du Zwingherrin, wohl dem, der dir vergelten wird / All das, was du an uns verübt!',
        9: 'Wohl dem, der deine jungen Kinder ergreift / Und sie am Felsen zerschmettert!',
    },
    138: {
        1: 'Von David. / Ich will dir danken von ganzem Herzen, / Sogar vor "Göttern" will ich dir lobsingen.',
        2: 'Zu deinem heiligen Tempel hin will ich anbeten / Und deinen Namen preisen ob deiner Huld und Treu. / Denn deine Verheißung hast du verherrlicht / Über all deinen Namen hinaus.',
        3: 'Als ich rief, hast du mich erhört / Und mich mit Kraft und Mut erfüllt.',
        4: 'Danken werden dir, Jahwe, alle Könige der Erde / Wenn sie deines Mundes Worte vernommen.',
        5: 'Sie werden Jahwes Walten besingen, / Denn groß ist Jahwes Herrlichkeit.',
        6: 'Ja, erhaben ist Jahwe; aber er sieht den Niedrigen an, / Und den Stolzen kennet er schon von fern.',
        7: 'Käm ich auch mitten in Drangsal hinein, / Du erhieltest mich trotz des Zorns meiner Feinde am Leben; / Du würdest deine Hand ausstrecken, / Und deine Rechte würde mich retten.',
        8: "Jahwe wird's mir zum Heil vollführen. / Jahwe, ewig währt deine Huld. / Deiner Hände Werk — o, laß es nicht unvollendet!",
    },
    139: {
        1: 'Dem Sangmeister. Ein Psalm Davids. / Jahwe, du hast mich durchforscht und erkannt:',
        2: 'Du weißt, wann ich sitze und wann ich aufstehe; / Mein Denken und Streben kennst du sogar, / Noch eh es mir klar geworden.',
        3: 'Du siehst, wann ich wandre und wann ich mich niederlege, / Mit all meinen Wegen bist du vertraut.',
        4: 'Denn es ist kein Wort auf meiner Zunge — / Sieh, o Jahwe, du weißt es ganz.',
        5: 'Von allen Seiten hältst du mich umschlossen, / Du hast deine Hand auf mich gelegt.',
        6: 'Dies Wissen ist mir zu wunderbar, / Zu hoch: ich kann mich ihm nicht entziehn.',
        7: 'Wohin soll ich gehn vor deinem Geist, / Wohin vor deinem Antlitz fliehn?',
        8: 'Wenn ich in den Himmel stiege — du wärest da; / Und wollt ich mir im Totenreich ein Lager bereiten — / Dort wärest du auch.',
        9: 'Flög ich auf Flügeln der Morgenröte, / Wollt ich weilen am Ende des Meers:',
        10: 'Auch da würde deine Hand mich leiten / Und deine Rechte mich fassen.',
        11: 'Spräche ich: "Dunkel umhülle mich ganz, / Das Licht um mich her: es werde zur Nacht!" —',
        12: 'Auch Dunkel ist dir nicht zu dunkel; / Die Nacht vielmehr — sie leuchtet sogar wie der Tag, / Das Dunkel ist ebenso wie das Licht.',
        13: 'Denn du hast meine Nieren gebildet, / Du hast mich gewoben im Mutterleib.',
        14: 'Ich danke dir, daß ich so erstaunlich wunderbar entstanden bin: / Wunderbar sind ja auch sonst deine Werke, / Und meine Seele erkennt es wohl.',
        15: 'Nicht war dir mein Wesen unbekannt, / Als ich im Verborgnen bereitet ward, / Gewirkt in den Tiefen der Erde.',
        16: 'Schon meinen Fruchtkeim haben deine Augen gesehn; / Und auf dein Buch wurden alle geschrieben: / Die Tage, die mir bestimmt, / Eh noch einer von ihnen erschienen war.',
        17: 'Wie sind mir so köstlich, Gott, deine Gedanken, / Wie ist ihre Zahl so gewaltig!',
        18: 'Wollt ich sie zählen — sie wären mehr als Sand: / Ich bin erwacht und bin noch bei dir.',
        19: 'Möchtest du doch, Eloah, die Frevler töten! / Und "ihr Blutmenschen, weicht von mir!"',
        20: 'Sie reden in Arglist von dir, / Mißbrauchen zu Lug deinen Namen — sie, die Feinde!',
        21: 'Sollt ich nicht hassen, Jahwe, die dich hassen, / Nicht Abscheu empfinden vor denen, die dir widerstreben?',
        22: 'Ich hasse sie mit dem größten Haß: / Sie gelten mir als Feinde.',
        23: 'Erforsche mich, Gott, und erkenne mein Herz, / Prüf mich, erkenne meine Gedanken!',
        24: 'Sieh, ob ich neige zu unheilvollem Wandel, / Und leite mich auf den Ewigkeitsweg!',
    },
    140: {
        1: 'Dem Sangmeister. Ein Psalm Davids.',
        2: 'Rette mich, Jahwe, von bösen Menschen, / Bewahre mich vor den Gewalttätigen,',
        3: 'Die im Herzen Böses sinnen, / Die täglich Streit erregen!',
        4: 'Sie schärfen ihre Zunge wie eine Schlange, / Unter ihren Lippen ist Otterngift. Sela.',
        5: 'Behüte mich, Jahwe, vor Frevlerhänden, / Bewahre mich vor den Gewalttätigen, / Die da sinnen auf meinen Sturz!',
        6: 'Stolze haben mir heimlich Schlingen und Seile gelegt, / Ein Netz gebreitet meinen Pfad entlang, / Sie haben mir Fallen gestellt. Sela.',
        7: 'Ich aber habe zu Jahwe gesagt: "Mein Gott bist du, / Vernimm doch, Jahwe, mein lautes Flehn!',
        8: 'Jahwe Adonái, du meine mächtige Hilfe, / Der du mein Haupt am Tage des Kampfes beschirmst,',
        9: 'Erfülle nicht, Jahwe, der Frevler Begehren, / Ihren Anschlag laß nicht gelingen! / Sie würden sich sonst überheben." Sela.',
        10: 'Das Haupt derer, die mich umlauern, / Möge das Unheil bedecken, das sie wider mich geredet!',
        11: 'Mögen glühende Kohlen auf sie fallen! / Ins Feuer stürze er sie, / In Fluten, draus sie nicht wieder auftauchen können!',
        12: 'Ein Verleumder wird nicht im Lande bestehn; / Der Gewaltmensch werde vom Unglück gejagt ins Verderben!',
        13: 'Ich weiß, daß Jahwe des Elenden Sache führen, / Den Armen zum Rechte verhelfen wird. Fürwahr, die Gerechten werden deinem Namen danken, / Die Redlichen bleiben vor deinem Antlitz.',
    },
    141: {
        1: 'Ein Psalm Davids. / Jahwe, ich habe dich angerufen: eile zu mir, / Horch auf mein Flehn, wenn ich zu dir rufe!',
        2: 'Nimm mein Gebet als Rauchopfer an, / Meiner Hände Aufheben als Abendopfer.',
        3: 'Stell eine Wache, Jahwe, vor meinen Mund, / Bewahre die Tür meiner Lippen!',
        4: 'Laß mein Herz sich nicht neigen zum Bösen, / Untat zu üben in Frevlermut / Im Bunde mit Männern, die übeltun; / Und von ihren Leckerbissen laß mich nicht essen!',
        5: 'Rügt mich ein Gerechter in Liebe und tadelt er mich, / So soll mein Haupt dies köstliche Öl nicht verschmähn; / Denn noch begegne ich nur mit Gebet ihren bösen Tücken.',
        6: 'Werden ihre Richter vom Felsen gestürzt, / Dann heißt man meine Worte als lieblich willkommen.',
        7: 'Wie einer das Erdreich mit Furchen durchzieht und lockert, / So sind unsre Gebeine dem Rachen des Grabes hingestreut.',
        8: 'Denn auf dich, Jahwe Adonái, sehn meine Augen, / Bei dir such ich Schutz: gib mich nicht hin in den Tod!',
        9: 'Bewahre mich vor der Schlinge, die man mir gelegt, / Vor den Nachstellungen der Übeltäter!',
        10: 'Laß die Frevler fallen ins eigene Netz! / Zugleich werd ich für immer daran vorübergehn.',
    },
    142: {
        1: 'Eine Betrachtung (?) Davids, als er in der Höhle war. Ein Gebet.',
        2: 'Laut schrei ich zu Jahwe, / Laut fleh ich zu Jahwe.',
        3: 'Vor ihm ergieß ich meine Klage, / Ihm mach ich meine Bedrängnis kund.',
        4: 'Ist mein Geist in mir verzagt: / Du kennst doch meinen Lebenspfad. / Auf dem Wege, den ich gehen will, / Hat man mir heimlich ein Netz gespannt.',
        5: 'Schau ich zur Rechten und blicke aus: / Niemand ist da, der mich kennen will. / Jede Zuflucht ist mir genommen, / Niemand frage nach mir.',
        6: 'Ich habe zu dir, o Jahwe, geschrien, / Ich habe gesagt: "Meine Zuflucht bist du, / Mein Teil in der Lebendigen Land!"',
        7: 'O merke doch auf mein lautes Flehn, / Denn ich bin elend und matt! / Von meinen Verfolgern errette mich, / Denn sie sind stärker als ich! Führe mich aus dem Kerker, / Daß ich deinen Namen preise! / Glück wünschend werden mich Fromme umringen, / Wenn du mir wohlgetan.',
    },
    143: {
        1: 'Ein Psalm Davids. / Jahwe, höre mein Gebet, / Vernimm mein Flehn um deiner Treue willen, / Antworte mir um deiner Gerechtigkeit willen!',
        2: 'Und geh nicht ins Gericht mit deinem Knecht, / Denn kein Lebendiger ist gerecht vor dir!',
        3: 'Denn der Feind hat mir nach dem Leben getrachtet, / Er hat mein Leben zu Boden geschlagen, / Mich in tiefes Dunkel versetzt wie die auf ewig Toten.',
        4: 'Nun ist mein Geist verschmachtet in mir, / Mein Herz ist mir in der Brust erstarrt.',
        5: 'Ich habe der Tage der Vorzeit gedacht, / Habe nachgesonnen über all dein Tun, / Das Werk deiner Hände erwogen.',
        6: 'Meine Hände hab ich zu dir gebreitet, / Wie nach Regen lechzendes Land lag meine Seele vor dir. Sela.',
        7: 'Eilends erhöre mich, Jahwe, es schmachtet mein Geist! / Verbirg nicht dein Antlitz vor mir! / Sonst gleich ich ins Grab Gesunknen.',
        8: 'Laß mich deine Huld schon früh am Morgen erfahren, / Denn ich vertraue auf dich! / Tu mir kund den Weg, den ich gehen soll, / Denn zu dir hab ich meine Seele erhoben!',
        9: 'Rette mich, Jahwe, von meinen Feinden! / Bei dir hab ich Zuflucht gesucht.',
        10: 'Lehre mich tun, was dir gefällt; / Du bist ja mein Gott: / Dein guter Geist führ mich auf ebner Bahn!',
        11: 'Um deines Namens willen, Jahwe, erhalt mich am Leben, / In deiner Treue reiß mich aus der Bedrängnis!',
        12: 'In deiner Huld vertilge du meine Feinde, / Vernichte alle, die meine Seele bedrängen! / Ich bin ja dein Knecht.',
    },
    144: {
        1: 'Von David. / Gepriesen sein Jahwe, mein Fels: / Er hat meine Hände zum Kampf, / Meine Finger zum Kriege geschickt gemacht.',
        2: 'Er schenkt mir Huld, er ist meine Burg, meine Feste, mein Retter, / Mein Schild: in ihm war ich immer geborgen; / Völker hat er mir unterworfen.',
        3: 'Jahwe, was ist doch der Mensch, daß du sein gedenkst, / Des Sterblichen Kind, daß du ihn beachtest?',
        4: 'Der Mensch ist ja nur wie ein Hauch, / Seine Tage sind wie ein schwindender Schatten.',
        5: 'Jahwe, neig deine Himmel, fahre herab, / Rühre die Berge an, daß sie rauchen!',
        6: 'Schleudre Blitze: zerstreue sie, / Schieß deine Pfeile: verstöre sie!',
        7: 'Streck aus deine Hand von der Himmelshöh! / Reiß mich heraus, befrei mich aus großen Wassern: / Aus der Hand der Söhne der Fremde,',
        8: 'Deren Mund Falsches zu reden pflegt, / Deren Rechte eine Rechte der Lüge ist!',
        9: 'Elohim, ich will dir singen ein neues Lied, / Auf zehnsaitiger Harfe dir spielen:',
        10: 'Dir, der den Königen Sieg verleiht, / Der David, seinen Knecht, aus der Not gerissen.',
        11: 'Dem mordenden Schwerte entreiße mich! / Rette mich aus der Hand der Söhne der Fremde, / Deren Mund Falsches zu reden pflegt, / Deren Rechte eine Rechte der Lüge ist!',
        12: 'Dann werden unsre Söhne in ihrer Jugendfrische / Wie kräftig wachsende Pflanzen sein, / Unsre Töchter gleichen Ecksäulen, / Die man meißelt zum Bau von Palästen.',
        13: 'Unsre Speicher sind dann gefüllt / Und spenden allerlei Frucht. / Unsre Schafe gehen tausend-, ja zehntausendweis / Auf unsern Triften.',
        14: 'Unsre Rinder tragen ohn Unfall und Fehlgeburt. / Auf unsern Straßen ist kein Klagegeschrei.',
        15: 'Heil dem Volk, dem es so ergeht, / Heil dem Volk, des Gott ist Jahwe!',
    },
    145: {
        1: 'Ein Loblied Davids. / Ah, dich will ich rühmen, mein Gott, du König, / Und deinen Namen preisen immer und ewig.',
        2: 'Beharrlich will ich dich preisen / Und deinen Namen loben immer und ewig.',
        3: 'Groß ist Jahwe und sehr preiswürdig, / Seine Größe ist unergründlich.',
        4: 'Das eine Geschlecht rühmt deine Werke dem andern, / Man macht deine großen Taten kund.',
        5: 'Hoheitsvoll ist deine herrliche Pracht, / Deine Wunder will ich besingen.',
        6: 'Wie soll man reden von deinem gewaltig erhabnen Tun! / Von deiner Größe will ich erzählen.',
        7: 'So soll man auch deiner Güte gedenken / Und ob deiner Gerechtigkeit jauchzen.',
        8: 'Gnädig ist Jahwe und barmherzig, / Langmütig und sehr gütig.',
        9: 'Tiefhuldreich erweist sich Jahwe allen / Und erbarmt sich all seiner Werke.',
        10: 'Jauchzen sollen dir, Jahwe, all deine Werke, / Deine Frommen sollen dich preisen.',
        11: 'Kundmachen sollen sie deines Königtums Herrlichkeit / Und reden von deiner Macht.',
        12: 'Loben sollen sie seine großen Taten vor den Menschenkindern / Und seines Königtums rühmliche Pracht.',
        13: 'Mit ewiger Dauer besteht dein Königreich, / Deine Herrschaft währet für und für.',
        14: 'Stützt nicht Jahwe alle, die fallen, / Hilft er nicht allen Gebeugten auf?',
        15: 'Aller Augen schaun empor zu dir: / Du gibst ihnen Nahrung zur rechten Zeit.',
        16: 'Freundlich öffnest du deine Hand / Und sättigst alles Lebendge mit dem, was ihm gefällt.',
        17: 'Zeigt sich nicht Jahwe gerecht in seinem Walten / Und gütig in all seinem Tun?',
        18: 'Kommt Jahwe nicht nahe allen, die ihn anrufen, / Allen, die ihn anrufen in Treue?',
        19: 'Recht erfüllen wird er, was seine Frommen begehren; / Er hört ihr Schrein und wird ihnen helfen.',
        20: 'Schützt Jahwe doch alle, die ihn lieben; / Alle Frevler aber wird er vertilgen.',
        21: 'Tönen soll mein Mund von Jahwes Lob, / Und alles Fleisch preise seinen heiligen Namen immer und ewig!',
    },
    146: {
        1: 'Lobet Jah! / Lobe Jahwe, o meine Seele!',
        2: 'Loben will ich Jahwe, solang ich lebe, / Meinem Gott will ich spielen, solange ich bin.',
        3: 'Vertraut nicht auf Fürsten, / Nicht auf Menschen, da sie nicht helfen können!',
        4: 'Fährt ihr Odem aus, so kehren sie wieder zum Staube zurück. / Dann hat es ein Ende mit ihren Plänen.',
        5: 'Heil dem, der Jakobs Gott zum Helfer hat, / Der auf Jahwe hofft als seinen Gott!',
        6: 'Er hat ja Himmel und Erde geschaffen, / Das Meer und alles, was weit und breit, / Er hält Treue in Ewigkeit.',
        7: 'Er schafft den Bedrückten Recht; / Er, Jahwe, gibt den Hungernden Brot, / Befreit die Gefangnen aus ihrer Not.',
        8: 'Jahwe öffnet die Augen der Blinden, / Gebeugte läßt Jahwe Erquickung finden, / Jahwe hat die Gerechten lieb.',
        9: 'Jahwe gibt den Fremdlingen Schutz, / Witwen und Waisen hilft er auf, / Aber er hemmt der Frevler Lauf.',
        10: 'Herrschen wird Jahwe in Ewigkeit, / Dein Gott, o Zion, in allen Geschlechtern. / Lobet Jah!',
    },
    147: {
        1: "Lobet Jah! / Denn köstlich ist's, unsern Gott zu preisen; / Ja, lieblich ist's, es ziemt sich Lobgesang.",
        2: 'Jahwe bauet Jerusalem, / Die Vertriebnen Israels sammelt er wieder.',
        3: 'Er heilt die zerbrochnen Herzen, / Und ihre Wunden verbindet er.',
        4: 'Er bestimmt den Sternen ihre Zahl, / Sie alle ruft er bei Namen.',
        5: 'Groß ist unser Herr und reich an Kraft, / Seine Einsicht ist unermeßlich.',
        6: 'Den Duldern hilft Jahwe auf, / Aber Frevler erniedrigt er tief zu Boden.',
        7: 'Stimmt für Jahwe ein Danklied an, / Spielt unserm Gott auf der Zither!',
        8: 'Er bedeckt den Himmel mit Wolken, / Er spendet Regen der Erde, / Läßt Gras auf den Bergen sprossen.',
        9: 'Er gibt dem Vieh sein Futter, / Den jungen Raben, wenn sie schrein.',
        10: 'Nicht an des Rosses Stärke hat er Gefallen, / Er hat nicht Lust an des Mannes Beinen.',
        11: 'Lust hat Jahwe an seinen Frommen, / Die da harren auf seine Huld.',
        12: 'Preise, Jerusalem, Jahwe, / Lobe, Zion, deinen Gott!',
        13: 'Denn er hat deiner Tore Riegel gestärkt, / Hat deine Kinder gesegnet in dir.',
        14: 'Er hat deinem Lande Frieden geschenkt, / Dich mit dem besten Weizen gesättigt.',
        15: 'Er sendet sein Machtwort nieder zur Erde, / Eilend läuft sein Gebot.',
        16: 'Er gibt Schnee wie Wolle, / Streut Reif wie Asche aus.',
        17: 'Er wirft seinen Hagel herab in Stücken: / Wer hält vor seiner Kälte stand?',
        18: 'Sendet er aber sein Wort, so zerschmelzt er sie. / Er läßt seinen Tauwind wehn, so rinnen Gewässer.',
        19: 'Er hat für Jakob sein Wort verkündet, / Seine Satzungen und Rechte für Israel.',
        20: 'So hat er sonst keinem Volke getan; / Drum kennen sie auch seine Rechte nicht. / Lobt Jah!',
    },
    148: {
        1: 'Lobet Jah! / Lobet Jah vom Himmel her, / Lobet ihn in der Höhe!',
        2: 'Lobt ihn, all seine Engel, / Lobet ihn, all sein Heer!',
        3: 'Lobt ihn, Sonne und Mond, / Lobet ihn, all ihr lichten Sterne!',
        4: 'Lobt ihn, ihr höchsten Himmel, / Und ihr Wasser über dem Himmel!',
        5: 'Loben sollen sie Jahwes Namen; / Denn er gebot, und sie wurden geschaffen.',
        6: 'Er stellte sie hin für immer und ewig; / Er gab ein Gesetz, das sie nicht übertreten.',
        7: 'Lobt Jahwe von der Erde her, / Ihr Seeungeheuer und all ihr Meerestiefen,',
        8: 'Ihr, Feuer und Hagel, Schnee und Rauch, / Du Sturmwind, der sein Wort vollstreckt.',
        9: 'Ihr Berge und alle Hügel, / Ihr Fruchtbäume und alle Zedern.',
        10: 'Ihr wilden und zahmen Tiere, / Ihr Gewürm und gefiederten Vögel,',
        11: 'Ihr Erdenkönige und Völker alle, / Ihr Fürsten und alle Richter auf Erden,',
        12: 'Ihr Jünglinge und ihr Jungfraun auch, / Ihr Alten mit den Jungen!',
        13: 'Sie alle sollen Jahwes Namen loben; / Denn sein Name allein ist erhaben, / Seine Hoheit geht über Erde und Himmel.',
        14: 'Er hat seinem Volk wieder Macht verliehn: / Das ist ein Ruhm für all seine Frommen, / Für Israels Söhne — das Volk, das ihm am nächsten steht. / Lobt Jah!',
    },
    149: {
        1: 'Lobet Jah! / Singet Jahwe ein neues Lied, / Singt sein Lob in der Frommen Versammlung!',
        2: 'Israel freue sich seines Schöpfers, / Zions Söhne mögen über ihren König jubeln!',
        3: 'Sie mögen seinen Namen preisen im Reigentanz, / Mit Pauke und Zither ihm spielen!',
        4: 'Denn Gefallen hat Jahwe an seinem Volk, / Er schmückt die Dulder mit Heil.',
        5: 'Frohlocken mögen die Frommen in ihrer Seele, / Jubeln auf ihren Lagern!',
        6: 'Ihr Mund sei voll von Gottes Lobpreis, / Ihre Hand aber führe ein zweischneidig Schwert!',
        7: 'So sollen sie Rache üben an den Heiden, / Strafe an den Völkern.',
        8: 'Deren Könige sollen sie binden mit Ketten, / Ihre Edlen mit eisernen Fesseln,',
        9: 'Und so an ihnen vollziehn das geschriebne Recht: / Das ist ein Ruhm für all seine Frommen. / Lobt Jah!',
    },
    150: {
        1: 'Lobet Jah! / Lobt El in seinem Heiligtum, / Lobt ihn an seiner mächtigen Feste!',
        2: 'Lobt ihn ob seiner gewaltigen Taten, / Lobt ihn, wie es seiner überschwenglichen Größe geziemt!',
        3: 'Lobt ihn mit dem Blasen des Widderhorns, / Lobt ihn mit Harfe und Zither!',
        4: 'Lobt ihn mit Pauke und Reigen, / Lobt ihn mit Saitenspiel und Flöte!',
        5: 'Lobt ihn mit klingenden Zimbeln, / Lobt ihn mit schallenden Zimbeln!',
        6: 'Alles, was Oden hat, lobe Jah! / Lobet Jah!',
    },
}
